window.ANSWER_TERMS = {"ATP":{"match":"adenosinetrifosfaat|adenosine trifosfaat|adenosine-trifosfaat|ATP","title":"ATP (adenosinetrifosfaat)","short":"ATP is de energiemunt van de cel: bij afsplitsing van de derde fosfaatgroep komt energie vrij die transport, contractie en biosynthese aandrijft.","definition":"<p><strong>ATP</strong> (adenosinetrifosfaat) bestaat uit adenine, ribose en drie fosfaatgroepen. Hydrolyse van de eindstandige fosfaatbinding (ATP → ADP + P<sub>i</sub>) levert ongeveer 30 kJ/mol — genoeg om ongunstige reacties te koppelen aan een gunstige: spiercontractie, de Na⁺/K⁺-ATPase, en de opbouw van eiwitten, vetten en DNA.</p><p>Het meeste ATP komt uit de <em>oxidatieve fosforylering</em> in het mitochondrion: de elektronentransportketen pompt protonen naar de intermembraanruimte, en ATP-synthase laat die protonengradiënt terugstromen en maakt daarmee ATP (chemiosmose). Glycolyse en de citroenzuurcyclus leveren daarnaast rechtstreeks een kleine hoeveelheid.</p><p>De cel slaat ATP nauwelijks op — de voorraad gaat in seconden — dus productie en verbruik zijn strak gekoppeld: veel ADP versnelt de verbranding, overmaat ATP remt die af.</p>","image_url":"","wiki_titles":["Adenosine triphosphate","ATP synthase"]},"lysosoom":{"title":"Lysosoom","short":"Membraanblaasje vol verterende enzymen dat afvalstoffen en opgenomen materiaal afbreekt.","definition":"<p>Het <b>lysosoom</b> is een blaasje omgeven door één membraan, gevuld met hydrolytische enzymen die bij een lage pH (~4,5) macromoleculen afbreken. Het is de 'maag' van de cel.</p><p>Het verteert materiaal dat via endocytose of fagocytose is opgenomen en ruimt via autofagie versleten celonderdelen op.</p>","image_url":"","wiki_title":"Lysosome","match":"lysosoom|lysosomen"},"ruw endoplasmatisch reticulum":{"title":"Ruw endoplasmatisch reticulum","short":"Deel van het ER bezet met ribosomen; hier worden eiwitten voor secretie en membranen gemaakt.","definition":"<p>Het <b>ruw endoplasmatisch reticulum</b> dankt zijn 'ruwe' aanzien aan de ribosomen op het oppervlak. Deze ribosomen synthetiseren eiwitten die het ER in worden geloodst.</p><p>In het ER-lumen worden die eiwitten gevouwen en van suikergroepen voorzien, op weg naar het Golgi-complex, de membranen of secretie.</p>","image_url":"","wiki_title":"Endoplasmic reticulum","match":"ruw endoplasmatisch reticulum|ruw ER"},"glad endoplasmatisch reticulum":{"title":"Glad endoplasmatisch reticulum","short":"ER zonder ribosomen; maakt lipiden, ontgift stoffen en slaat calcium op.","definition":"<p>Het <b>glad endoplasmatisch reticulum</b> heeft geen ribosomen. Het synthetiseert lipiden en steroïden, ontgift geneesmiddelen (vooral in de lever) en slaat Ca²⁺ op.</p><p>In spiercellen (sarcoplasmatisch reticulum) regelt de calciumopslag de spiercontractie.</p>","image_url":"","wiki_title":"Endoplasmic reticulum","match":"glad endoplasmatisch reticulum|glad ER"},"ribosoom":{"title":"Ribosoom","short":"Moleculaire machine die met behulp van mRNA aminozuren aaneenrijgt tot een eiwit (translatie).","definition":"<p>Het <b>ribosoom</b> is opgebouwd uit ribosomaal RNA en eiwitten. Het leest de codons van het mRNA af en koppelt de bijbehorende aminozuren aan elkaar.</p><p>Ribosomen komen vrij in het cytoplasma voor of gebonden aan het ruw endoplasmatisch reticulum.</p>","image_url":"","wiki_title":"Ribosome","match":"ribosoom|ribosomen"},"mitochondrion":{"title":"Mitochondrion","short":"De 'energiecentrale' van de cel; produceert ATP via de citroenzuurcyclus en oxidatieve fosforylering.","definition":"<p>Het <b>mitochondrion</b> heeft een dubbele membraan; de binnenste is sterk geplooid (cristae). Hier vinden de citroenzuurcyclus en de elektronentransportketen plaats.</p><p>Zo levert het mitochondrion het grootste deel van de ATP van de cel. Het bevat eigen DNA en kan zich delen.</p>","image_url":"","wiki_title":"Mitochondrion","match":"mitochondrion|mitochondriën|mitochondrien|mitochondria|mitochondrium"},"cholesterol":{"title":"Cholesterol","short":"Vetachtige stof die de celmembraan stevigheid en de juiste vloeibaarheid geeft en grondstof is voor steroïden.","definition":"<p><b>Cholesterol</b> is een steroïd dat tussen de fosfolipiden van de celmembraan zit en de membraanvloeibaarheid stabiliseert.</p><p>Het is bovendien de grondstof voor steroïdhormonen, vitamine D en galzouten.</p>","image_url":"","wiki_title":"Cholesterol","match":"cholesterol"},"endocytose":{"title":"Endocytose","short":"Opname van stoffen door de cel via inknopping van de membraan tot een blaasje.","definition":"<p>Bij <b>endocytose</b> stulpt de celmembraan naar binnen en snoert een blaasje af met daarin opgenomen materiaal.</p><p>Varianten zijn fagocytose (grote deeltjes), pinocytose (vloeistof) en receptorgemedieerde endocytose (specifieke moleculen).</p>","image_url":"","wiki_title":"Endocytosis","match":"endocytose"},"apoptose":{"title":"Apoptose","short":"Geprogrammeerde celdood: een geordend 'zelfmoordprogramma' dat de cel netjes opruimt zonder ontsteking.","definition":"<p><b>Apoptose</b> is gecontroleerde celdood. De cel krimpt, het DNA wordt in stukken geknipt en de cel valt uiteen in nette blaasjes (apoptotic bodies).</p><p>Macrofagen ruimen die op zonder ontstekingsreactie. Het is essentieel voor ontwikkeling en het verwijderen van beschadigde cellen.</p>","image_url":"","wiki_title":"Apoptosis","match":"apoptose"},"necrose":{"title":"Necrose","short":"Ongecontroleerde celdood door schade, waarbij de cel opzwelt, openbarst en een ontstekingsreactie uitlokt.","definition":"<p><b>Necrose</b> is celdood door acute schade (zuurstoftekort, toxinen, trauma). De cel zwelt op en de membraan scheurt.</p><p>De vrijkomende celinhoud lokt een ontstekingsreactie uit — anders dan bij de 'nette' apoptose.</p>","image_url":"","wiki_title":"Necrosis","match":"necrose"},"glycolyse":{"title":"Glycolyse","short":"Afbraak van glucose tot pyruvaat in het cytoplasma, met een kleine netto-opbrengst aan ATP en NADH.","definition":"<p><b>Glycolyse</b> splitst in het cytoplasma één glucose in tien stappen tot twee moleculen pyruvaat.</p><p>Het levert netto 2 ATP en 2 NADH op en verloopt zonder zuurstof. Bij aanwezigheid van zuurstof gaat pyruvaat de citroenzuurcyclus in.</p>","image_url":"","wiki_title":"Glycolysis","match":"glycolyse"},"citroenzuurcyclus":{"title":"Citroenzuurcyclus","short":"Kringloop in het mitochondrion die acetyl-CoA volledig oxideert en NADH, FADH₂ en CO₂ oplevert.","definition":"<p>De <b>citroenzuurcyclus</b> (Krebscyclus) vindt plaats in de mitochondriale matrix. Acetyl-CoA gaat de cyclus in en wordt stapsgewijs geoxideerd.</p><p>Er ontstaan NADH en FADH₂ (die de elektronentransportketen voeden), wat GTP/ATP en CO₂ als afvalstof.</p>","image_url":"","wiki_title":"Citric acid cycle","match":"citroenzuurcyclus|krebscyclus"},"oxidatieve fosforylering":{"title":"Oxidatieve fosforylering","short":"Vorming van het grootste deel van de ATP via de elektronentransportketen en ATP-synthase in het mitochondrion.","definition":"<p>Bij <b>oxidatieve fosforylering</b> drijft de protongradiënt van de elektronentransportketen het enzym ATP-synthase aan.</p><p>Zo wordt uit ADP en fosfaat ATP gevormd — de belangrijkste ATP-bron van de cel, waarvoor zuurstof nodig is.</p>","image_url":"","wiki_title":"Oxidative phosphorylation","match":"oxidatieve fosforylering"},"acetyl-coa":{"title":"Acetyl-CoA","short":"Centrale metaboliet die een acetylgroep de citroenzuurcyclus in brengt; knooppunt van suiker-, vet- en eiwitafbraak.","definition":"<p><b>Acetyl-CoA</b> ontstaat uit pyruvaat (uit glycolyse), vetzuren en sommige aminozuren.</p><p>Het draagt zijn acetylgroep de citroenzuurcyclus in en is zo het centrale knooppunt van het energiemetabolisme.</p>","image_url":"","wiki_title":"Acetyl-CoA","match":"acetyl-coa|acetyl coa"},"pyruvaat":{"title":"Pyruvaat","short":"Eindproduct van de glycolyse; gaat bij zuurstof over in acetyl-CoA, zonder zuurstof in lactaat.","definition":"<p><b>Pyruvaat</b> (pyrodruivenzuur) is het eindproduct van de glycolyse.</p><p>Met zuurstof wordt het in het mitochondrion omgezet tot acetyl-CoA voor de citroenzuurcyclus; zonder zuurstof wordt het via gisting lactaat.</p>","image_url":"","wiki_title":"Pyruvic acid","match":"pyruvaat|pyrodruivenzuur"},"nadh":{"title":"NADH","short":"Elektronendrager die de citroenzuurcyclus 'oplaadt' en zijn elektronen aan de elektronentransportketen levert.","definition":"<p><b>NADH</b> is de gereduceerde vorm van NAD⁺. Het ontstaat als tijdens glycolyse en citroenzuurcyclus elektronen worden opgenomen.</p><p>In het mitochondrion staat NADH die elektronen weer af aan de elektronentransportketen, wat ATP oplevert.</p>","image_url":"","wiki_title":"Nicotinamide adenine dinucleotide","match":"nadh"},"citraat":{"title":"Citraat","short":"Eerste product van de citroenzuurcyclus, gevormd uit acetyl-CoA en oxaalacetaat.","definition":"<p><b>Citraat</b> (citroenzuur) ontstaat wanneer acetyl-CoA in de citroenzuurcyclus aan oxaalacetaat wordt gekoppeld.</p><p>Het is de eerste stap van de cyclus; de naamgever citroenzuurcyclus verwijst ernaar.</p>","image_url":"","wiki_title":"Citric acid","match":"citraat"},"fosforylering":{"title":"Fosforylering","short":"Toevoeging van een fosfaatgroep aan een eiwit; een veelgebruikte aan/uit-schakelaar van eiwitactiviteit.","definition":"<p><b>Fosforylering</b> is het koppelen van een fosfaatgroep aan een eiwit door een kinase. Een fosfatase haalt hem er weer af.</p><p>Zo schakelen cellen eiwitten razendsnel aan of uit — de basis van veel signaaltransductie.</p>","image_url":"","wiki_title":"Phosphorylation","match":"fosforylering|fosforylatie"},"fibroblast":{"title":"Fibroblast","short":"De belangrijkste bindweefselcel; produceert collageen, elastine en de overige extracellulaire matrix.","definition":"<p>De <b>fibroblast</b> is de meest voorkomende cel in bindweefsel en de dermis. Hij maakt de vezels (collageen, elastine) en de grondsubstantie aan.</p><p>Bij wondgenezing migreren fibroblasten naar de wond, vormen nieuw matrixmateriaal en kunnen als myofibroblast de wond samentrekken.</p>","image_url":"","wiki_title":"Fibroblast","match":"fibroblast|fibroblasten"},"macrofaag":{"title":"Macrofaag","short":"Grote fagocyt in de weefsels die pathogenen en celresten opruimt en antigenen presenteert.","definition":"<p>De <b>macrofaag</b> ontstaat uit een monocyt die het weefsel is binnengegaan. Hij fagocyteert bacteriën, dode cellen en afval.</p><p>Als antigeenpresenterende cel activeert hij ook T-cellen en scheidt hij ontstekingsmediatoren uit. In de huid heten verwante cellen histiocyten.</p>","image_url":"","wiki_title":"Macrophage","match":"macrofaag|macrofagen"},"thymus":{"title":"Thymus","short":"Lymfoïd orgaan achter het borstbeen waar T-lymfocyten uitrijpen en geselecteerd worden.","definition":"<p>De <b>thymus</b> (zwezerik) ligt achter het borstbeen. Hier rijpen T-lymfocyten uit en worden ze getest op nut en veiligheid (positieve en negatieve selectie).</p><p>De thymus is het actiefst in de jeugd en neemt daarna geleidelijk af.</p>","image_url":"","wiki_title":"Thymus","match":"thymus"},"milt":{"title":"Milt","short":"Lymfoïd orgaan dat oude bloedcellen afbreekt en bloedgedragen ziekteverwekkers filtert.","definition":"<p>De <b>milt</b> filtert het bloed: de rode pulpa ruimt versleten erytrocyten op, de witte pulpa herbergt lymfocyten voor de afweer tegen bloedgedragen pathogenen.</p><p>Ook dient de milt als bloedreservoir.</p>","image_url":"","wiki_title":"Spleen","match":"milt"},"lymfeklier":{"title":"Lymfeklier","short":"Filterstation in de lymfebaan waar antigenen worden gepresenteerd en de afweerreactie op gang komt.","definition":"<p>De <b>lymfeklier</b> filtert de lymfe en is een ontmoetingsplaats voor antigeenpresenterende cellen en lymfocyten.</p><p>Hier worden T- en B-cellen geactiveerd; bij infectie zwellen lymfeklieren op doordat de lymfocyten zich vermenigvuldigen.</p>","image_url":"","wiki_title":"Lymph node","match":"lymfeklier|lymfeklieren|lymfklier|lymfklieren"},"meerlagig plaveiselepitheel":{"title":"Meerlagig plaveiselepitheel","short":"Epitheel van meerdere lagen platte cellen; beschermt tegen mechanische belasting (o.a. de opperhuid).","definition":"<p><b>Meerlagig plaveiselepitheel</b> bestaat uit meerdere cellagen met bovenop platte (plaveisel)cellen.</p><p>Het is bestand tegen slijtage en komt voor waar veel mechanische belasting is: epidermis, mondholte, slokdarm. In de huid is het verhoornd.</p>","image_url":"","wiki_title":"Stratified squamous epithelium","match":"meerlagig plaveiselepitheel"},"overgangsepitheel":{"title":"Overgangsepitheel","short":"Rekbaar epitheel (urotheel) dat van vorm verandert bij vullen en legen, o.a. in de blaas.","definition":"<p><b>Overgangsepitheel</b> (urotheel) kan uitrekken en samentrekken: de cellen worden platter als het orgaan zich vult.</p><p>Het bekleedt de urinewegen, zoals de blaas, en is daar ook een waterdichte barrière.</p>","image_url":"","wiki_title":"Transitional epithelium","match":"overgangsepitheel"},"meerrijig epitheel":{"title":"Meerrijig epitheel","short":"Eenlagig epitheel waarvan de kernen op verschillende hoogtes liggen, waardoor het meerlagig lijkt.","definition":"<p><b>Meerrijig (pseudomeerlagig) epitheel</b> lijkt uit meerdere lagen te bestaan doordat de celkernen op verschillende hoogtes zitten, maar alle cellen raken de basaalmembraan.</p><p>Het komt vaak trilhaardragend voor in de luchtwegen.</p>","image_url":"","wiki_title":"Pseudostratified columnar epithelium","match":"meerrijig epitheel|meerrijïg epitheel"},"collageen":{"title":"Collageen","short":"Sterkste structuureiwit van het lichaam; hoofdbestanddeel van bindweefsel, dermis, pezen en bot.","definition":"<p><b>Collageen</b> is het meest voorkomende eiwit in het lichaam en vormt sterke, drievoudig gewonden vezels.</p><p>In de dermis geeft het de huid trekvastheid; fibroblasten maken het aan. Voor de aanmaak is vitamine C nodig (hydroxylering van proline).</p>","image_url":"","wiki_title":"Collagen","match":"collageen"},"nodulus":{"title":"Nodulus","short":"Vaste, verheven en voelbare knobbel die dieper in de huid reikt dan een papel (> ~1 cm).","definition":"<p>Een <b>nodulus</b> (nodus, knobbel) is een stevige, verheven laesie die groter is dan een papel en dieper in de dermis of subcutis reikt.</p><p>Voorbeelden zijn een dermatofibroom of sommige huidtumoren.</p>","image_url":"","wiki_title":"Nodule (medicine)","match":"nodulus|nodus|noduli|nodi"},"vesikel":{"title":"Vesikel","short":"Klein, met helder vocht gevuld blaasje in de huid (< ~1 cm).","definition":"<p>Een <b>vesikel</b> (vesicula) is een klein blaasje gevuld met helder vocht, kleiner dan ongeveer 1 cm.</p><p>Vesikels komen voor bij o.a. herpes, waterpokken en acuut eczeem. Een groter blaasje heet een bulla.</p>","image_url":"","wiki_title":"Blister","match":"vesikel|vesikels|vesicula|vesiculae"},"ulcus":{"title":"Ulcus","short":"Diep huiddefect tot in de dermis of dieper, dat met een litteken geneest (een 'zweer').","definition":"<p>Een <b>ulcus</b> (zweer) is een dieper weefselverlies dat tot in de dermis of subcutis reikt.</p><p>Doordat de dermis is aangetast, geneest het met littekenvorming. Een ulcus cruris (open been) is een bekend voorbeeld.</p>","image_url":"","wiki_title":"Ulcer (dermatology)","match":"ulcus|ulcera"},"atrofie":{"title":"Atrofie","short":"Verdunning of afname van weefsel; bij de huid een dunnere, kwetsbaardere epidermis en/of dermis.","definition":"<p><b>Atrofie</b> is het slinken van een weefsel of orgaan doordat de cellen krimpen of in aantal afnemen.</p><p>Huidatrofie (bijv. na langdurig sterk corticosteroïdgebruik of door veroudering) geeft een dunne, doorschijnende, kwetsbare huid.</p>","image_url":"","wiki_title":"Atrophy","match":"atrofie"},"plaveiselcelcarcinoom":{"title":"Plaveiselcelcarcinoom","short":"Op één na meest voorkomende huidkanker, uit keratinocyten; kan uitzaaien.","definition":"<p>Het <b>plaveiselcelcarcinoom</b> gaat uit van de keratinocyten van de epidermis en is de op één na meest voorkomende huidkanker.</p><p>Anders dan het basaalcelcarcinoom kan het metastaseren. Het ontstaat vooral op zonbeschadigde huid, vaak vanuit een actinische keratose.</p>","image_url":"","wiki_title":"Squamous-cell carcinoma","match":"plaveiselcelcarcinoom|plaveiselcel carcinoom"},"radiotherapie":{"title":"Radiotherapie","short":"Behandeling met ioniserende straling die het DNA van tumorcellen beschadigt.","definition":"<p><b>Radiotherapie</b> (bestraling) gebruikt ioniserende straling om het DNA van kankercellen zodanig te beschadigen dat ze afsterven.</p><p>In de dermatologie is het een alternatief voor chirurgie bij bijvoorbeeld basaal- en plaveiselcelcarcinomen, vooral bij oudere patiënten of moeilijke locaties.</p>","image_url":"","wiki_title":"Radiation therapy","match":"radiotherapie"},"pneumonie":{"title":"Pneumonie","short":"Een pneumonie is een infectie van het longweefsel (alveoli), meestal door bacteriën of virussen, met koorts, hoesten en kortademigheid.","definition":"<p>Bij een <strong>pneumonie</strong> (longontsteking) raken de alveoli ontstoken en vullen ze zich met ontstekingsvocht en cellen. Daardoor is minder longoppervlak beschikbaar voor gaswisseling.</p><p>Typische klachten zijn koorts, hoesten (vaak met sputum), kortademigheid en soms pijn bij het ademen. Bij lichamelijk onderzoek kunnen crepitaties of een gedempte percussie optreden; een X-thorax toont een infiltraat. De meest voorkomende verwekker van de buiten het ziekenhuis opgelopen pneumonie is <em>Streptococcus pneumoniae</em>.</p>","image_url":"","wiki_title":"Pneumonia","match":"pneumonie|longontsteking","option_only":true},"escherichia coli":{"title":"Escherichia coli","short":"E. coli is een gramnegatieve staafbacterie die normaal in de darm leeft en de belangrijkste verwekker is van urineweginfecties.","definition":"<p><strong><em>Escherichia coli</em></strong> is een gramnegatieve, facultatief anaerobe staaf uit de familie van de <em>Enterobacteriaceae</em>. Het is een normaal onderdeel van de darmflora.</p><p>Buiten de darm is E. coli de belangrijkste verwekker van urineweginfecties (cystitis, pyelonefritis) en een belangrijke oorzaak van sepsis en neonatale meningitis. Sommige stammen (zoals EHEC en ETEC) veroorzaken diarree; EHEC kan via shigatoxine het hemolytisch-uremisch syndroom veroorzaken.</p>","image_url":"","wiki_title":"Escherichia coli","match":"escherichia coli|e. coli|e.coli","option_only":true},"staphylococcus aureus":{"title":"Staphylococcus aureus","short":"S. aureus is een grampositieve kok in trosjes, coagulasepositief, die huid- en wondinfecties, abcessen en ernstige systemische infecties veroorzaakt.","definition":"<p><strong><em>Staphylococcus aureus</em></strong> is een grampositieve kok die in trosjes groeit en <em>coagulase-positief</em> is (onderscheid met andere stafylokokken). Ongeveer een derde van de mensen draagt hem in de neus.</p><p>Hij veroorzaakt huid- en wekedeleninfecties (impetigo, furunkels, abcessen, wondinfecties), maar ook osteomyelitis, septische artritis, endocarditis en sepsis. Via toxines kan hij voedselvergiftiging en het toxischeshocksyndroom veroorzaken. MRSA is een methicillineresistente variant.</p>","image_url":"","wiki_title":"Staphylococcus aureus","match":"staphylococcus aureus|s. aureus|stafylococcus aureus","option_only":true},"pseudomonas aeruginosa":{"title":"Pseudomonas aeruginosa","short":"P. aeruginosa is een gramnegatieve, aerobe staaf die van vochtige omgevingen houdt en vooral bij verzwakte patiënten ziekenhuisinfecties veroorzaakt.","definition":"<p><strong><em>Pseudomonas aeruginosa</em></strong> is een gramnegatieve, strikt aerobe staaf die leeft in water en vochtige omgevingen. Hij is van nature resistent tegen veel antibiotica.</p><p>Hij veroorzaakt vooral opportunistische infecties: ziekenhuispneumonie (o.a. bij beademing), infecties van brandwonden, urineweginfecties bij katheters, otitis externa en chronische luchtweginfecties bij cystische fibrose. Kolonies hebben vaak een groenblauw pigment en een zoete geur.</p>","image_url":"","wiki_title":"Pseudomonas aeruginosa","match":"pseudomonas aeruginosa|p. aeruginosa|pseudomonas","option_only":true},"candida albicans":{"title":"Candida albicans","short":"Candida albicans is een gist die normaal op slijmvliezen voorkomt en bij verminderde weerstand spruw, vaginale schimmelinfectie of invasieve infecties geeft.","definition":"<p><strong><em>Candida albicans</em></strong> is een gist (schimmel) die bij veel mensen in mond, darm en vagina voorkomt. Hij kan zowel als ronde gistcel als met (pseudo)hyfen groeien.</p><p>Bij een verstoorde flora (antibiotica) of verminderde afweer veroorzaakt hij oppervlakkige infecties zoals spruw (orale candidiasis), vaginale candidiasis en intertrigo. Bij ernstig immuungecompromitteerden of patiënten met lijnen kan een invasieve candidemie ontstaan.</p>","image_url":"","wiki_title":"Candida albicans","match":"candida albicans|c. albicans|candida","option_only":true},"kinkhoest":{"title":"Kinkhoest (pertussis)","short":"Kinkhoest is een luchtweginfectie door Bordetella pertussis met langdurige hoestbuien en een gierende inademing; gevaarlijk voor zuigelingen.","definition":"<p><strong>Kinkhoest</strong> (pertussis) wordt veroorzaakt door de gramnegatieve bacterie <em>Bordetella pertussis</em>, die zich hecht aan het trilhaarepitheel en toxines produceert.</p><p>Na een verkoudheidsfase volgen weken met heftige hoestbuien, vaak eindigend in een gierende inademing (‘kink’) of braken. Bij jonge zuigelingen kan kinkhoest apneus en overlijden veroorzaken; daarom wordt gevaccineerd (ook zwangeren, om de baby te beschermen).</p>","image_url":"","wiki_title":"Whooping cough","match":"kinkhoest|pertussis|bordetella pertussis","option_only":true},"hepatitis a":{"title":"Hepatitis A","short":"Hepatitis A is een fecaal-oraal overgedragen virale leverontsteking die acuut verloopt en nooit chronisch wordt.","definition":"<p><strong>Hepatitis A</strong> wordt veroorzaakt door het hepatitis A-virus, een niet-omhuld RNA-virus dat fecaal-oraal wordt overgedragen (besmet water en voedsel, reizen).</p><p>Het geeft een acute hepatitis met moeheid, misselijkheid, geelzucht en verhoogde transaminasen; bij jonge kinderen vaak zonder klachten. Hepatitis A wordt <em>niet chronisch</em> en geeft levenslange immuniteit. Er is een vaccin.</p>","image_url":"","wiki_title":"Hepatitis A","match":"hepatitis a|hav|hepatitis a-virus","option_only":true},"hepatitis b":{"title":"Hepatitis B","short":"Hepatitis B is een via bloed en seks overgedragen DNA-virus dat acute en chronische leverontsteking geeft, met risico op cirrose en levercelcarcinoom.","definition":"<p><strong>Hepatitis B</strong> wordt veroorzaakt door het hepatitis B-virus, een omhuld (gedeeltelijk dubbelstrengs) DNA-virus. Overdracht via bloed, seksueel contact en van moeder op kind rond de geboorte.</p><p>Bij volwassenen geneest de meeste acute infectie; bij pasgeborenen wordt de infectie meestal <em>chronisch</em>. Chronische hepatitis B kan leiden tot levercirrose en hepatocellulair carcinoom. Diagnostiek via serologie (HBsAg, anti-HBc, anti-HBs). Er is een effectief vaccin.</p>","image_url":"","wiki_title":"Hepatitis B","match":"hepatitis b|hbv|hepatitis b-virus","option_only":true},"bovenste luchtweginfectie":{"title":"Bovenste luchtweginfectie","short":"Een bovenste luchtweginfectie is een (meestal virale) infectie van neus, keel, bijholten of strottenhoofd, zoals een verkoudheid.","definition":"<p>Een <strong>bovenste luchtweginfectie</strong> betreft de luchtwegen boven de stembanden: neus, bijholten, farynx en larynx. Voorbeelden zijn de gewone verkoudheid (rhinitis), faryngitis, sinusitis en laryngitis.</p><p>Ze worden meestal veroorzaakt door virussen (rhino-, adeno-, coronavirussen) en zijn zelflimiterend. Antibiotica zijn zelden nodig.</p>","image_url":"","wiki_title":"Upper respiratory tract infection","match":"bovenste luchtweginfectie|bovensteluchtweginfectie|blwi","option_only":true},"acetylcholine":{"title":"Acetylcholine","short":"Acetylcholine is de neurotransmitter van de neuromusculaire overgang, van alle autonome ganglia en van het parasympathische zenuwstelsel.","definition":"<p><strong>Acetylcholine</strong> wordt gemaakt uit choline en acetyl-CoA en na afgifte snel afgebroken door <em>acetylcholinesterase</em>.</p><p>Het werkt op <em>nicotinerge</em> receptoren (ionkanalen: neuromusculaire eindplaat, autonome ganglia, bijniermerg) en <em>muscarinerge</em> receptoren (G-eiwitgekoppeld: doelorganen van het parasympathicus en de zweetklieren). Centraal speelt het een rol bij aandacht en geheugen; bij de ziekte van Alzheimer is er een cholinerg tekort.</p>","image_url":"","wiki_title":"Acetylcholine","match":"acetylcholine|ach","option_only":true},"serotonine":{"title":"Serotonine","short":"Serotonine (5-HT) is een monoamine uit tryptofaan; neurotransmitter voor stemming, slaap en eetlust en in de darm en bloedplaatjes actief.","definition":"<p><strong>Serotonine</strong> (5-hydroxytryptamine) wordt gemaakt uit het aminozuur <em>tryptofaan</em>. Het meeste zit in enterochromaffiene cellen van de darm en wordt in bloedplaatjes opgeslagen.</p><p>In het brein komen serotonerge neuronen uit de raphekernen van de hersenstam; ze beïnvloeden stemming, angst, slaap, eetlust en pijn. SSRI's remmen de heropname en worden bij depressie en angststoornissen gebruikt. In de darm stimuleert serotonine de motiliteit; perifeer veroorzaakt het vasoconstrictie of -dilatatie afhankelijk van het vaatbed.</p>","image_url":"","wiki_title":"Serotonin","match":"serotonine|5-ht|5-hydroxytryptamine|serotonin","option_only":true},"glucose":{"title":"Glucose","short":"Glucose is een monosacharide (C₆H₁₂O₆) en de belangrijkste brandstof van het lichaam; de bloedspiegel wordt strak geregeld door insuline en glucagon.","definition":"<p><strong>Glucose</strong> is een hexose en de centrale brandstof van het metabolisme. Cellen breken het af via de glycolyse en daarna (aeroob) via de citroenzuurcyclus en oxidatieve fosforylering tot CO<sub>2</sub> en water, met vorming van ATP.</p><p>Het lichaam slaat glucose op als <em>glycogeen</em> in lever en spier. De bloedglucose (normaal nuchter ±4–6 mmol/L) wordt verlaagd door insuline en verhoogd door glucagon, adrenaline en cortisol. Het brein is sterk afhankelijk van glucose.</p>","image_url":"","wiki_title":"Glucose","match":"glucose|druivensuiker|bloedglucose","option_only":true},"glucose-1-fosfaat (g1p)":{"title":"Glucose-1-fosfaat","short":"Glucose-1-fosfaat is het product van de glycogeenafbraak door glycogeenfosforylase en een tussenstap bij de glycogeensynthese.","definition":"<p><strong>Glucose-1-fosfaat</strong> ontstaat wanneer glycogeenfosforylase glucose-eenheden van glycogeen afsplitst. Fosfoglucomutase zet het vervolgens om in <em>glucose-6-fosfaat</em>, dat de glycolyse in kan of (in de lever) via glucose-6-fosfatase tot vrij glucose wordt omgezet.</p><p>Bij de glycogeensynthese loopt de route andersom: glucose-6-fosfaat → glucose-1-fosfaat → UDP-glucose, dat door glycogeensynthase aan de keten wordt gekoppeld.</p>","image_url":"","wiki_title":"Glucose 1-phosphate","match":"glucose-1-fosfaat (g1p)|glucose-1-fosfaat|g1p|glucose 1-fosfaat","option_only":true},"spier glycogeen":{"title":"Spierglycogeen","short":"Spierglycogeen is de glucosevoorraad in skeletspier; het wordt alleen voor de spier zelf gebruikt en levert bij intensieve inspanning snel energie via de glycolyse.","definition":"<p><strong>Spierglycogeen</strong> is een vertakt polymeer van glucose dat in skeletspiercellen ligt opgeslagen (totaal enkele honderden grammen). Omdat spier geen glucose-6-fosfatase heeft, kan het glucose niet aan het bloed afgeven: de voorraad is alleen voor de spier zelf.</p><p>Bij inspanning wordt het via glycogenolyse en glycolyse afgebroken, ook anaeroob (met lactaatvorming).</p>","image_url":"","wiki_title":"","match":"spier glycogeen|spierglycogeen|glycogeen in spier","option_only":true},"vetzuren":{"title":"Vetzuren","short":"Vetzuren zijn koolstofketens met een carboxylgroep; ze worden via bèta-oxidatie in de mitochondriën verbrand en leveren veel ATP, maar alleen aeroob.","definition":"<p><strong>Vetzuren</strong> zijn lange koolwaterstofketens met een carboxylgroep, verzadigd of onverzadigd. Ze worden opgeslagen als triglyceriden in vetweefsel en bij behoefte door lipolyse vrijgemaakt.</p><p>In de cel worden ze met carnitine de mitochondriën in getransporteerd en via <em>bèta-oxidatie</em> afgebroken tot acetyl-CoA, dat de citroenzuurcyclus in gaat. Vetzuren leveren per gram veel meer energie dan glucose, maar alleen via zuurstofafhankelijke stofwisseling en relatief langzaam. In de lever kunnen ze ketonlichamen vormen.</p>","image_url":"","wiki_title":"Fatty acid","match":"vetzuren|vrije vetzuren|vetzuur|vetzuurverbranding|vetzuuroxidatie","option_only":true},"alcohol":{"title":"Alcohol (ethanol)","short":"Ethanol wordt in de lever afgebroken via acetaldehyde tot azijnzuur; overmatig gebruik schaadt lever, brein, hart en pancreas.","definition":"<p><strong>Ethanol</strong> wordt vooral in de lever geoxideerd door <em>alcoholdehydrogenase</em> tot acetaldehyde en daarna door aldehydedehydrogenase tot acetaat. Hierbij ontstaat veel NADH, wat de gluconeogenese remt (hypoglykemie) en vetstapeling in de lever bevordert.</p><p>Chronisch overmatig gebruik geeft leververvetting, alcoholische hepatitis en cirrose, pancreatitis, cardiomyopathie, hypertensie, neuropathie, thiaminetekort (Wernicke-Korsakov) en een verhoogd risico op verschillende kankers.</p>","image_url":"","wiki_title":"Alcohol (drug)","match":"alcohol|ethanol|alcoholgebruik|overmatig alcoholgebruik|alcoholmisbruik","option_only":true},"roken":{"title":"Roken","short":"Roken is de belangrijkste vermijdbare oorzaak van ziekte en sterfte: het veroorzaakt o.a. longkanker, COPD en hart- en vaatziekten.","definition":"<p>Tabaksrook bevat nicotine (verslavend), koolmonoxide, teer en tientallen kankerverwekkende stoffen. <strong>Roken</strong> beschadigt het luchtwegepitheel en het endotheel en bevordert ontsteking en trombose.</p><p>Het is een hoofdoorzaak van longkanker en andere kankers (o.a. mond, slokdarm, blaas), COPD, atherosclerose (myocardinfarct, CVA, perifeer arterieel vaatlijden) en complicaties in de zwangerschap. Stoppen loont op elke leeftijd.</p>","image_url":"","wiki_title":"Tobacco smoking","match":"roken|tabaksgebruik|tabak","option_only":true},"vena cava superior":{"title":"Vena cava superior","short":"De vena cava superior voert het bloed van hoofd, hals, armen en thoraxwand terug naar het rechteratrium.","definition":"<p>De <strong>vena cava superior</strong> ontstaat door samenvloeiing van de linker en rechter v. brachiocephalica, achter het sternum rechts, en mondt uit in het <em>rechteratrium</em>.</p><p>Zij draineert hoofd, hals, armen en (via de v. azygos) de thoraxwand. Compressie door een tumor (vaak longcarcinoom of lymfoom) geeft het vena cava superior-syndroom: zwelling van gezicht en armen en gestuwde halsvenen.</p>","image_url":"","wiki_title":"Superior vena cava","match":"vena cava superior|v. cava superior|bovenste holle ader","option_only":true},"trachea":{"title":"Trachea","short":"De trachea is de luchtpijp van het strottenhoofd tot de splitsing (carina), verstevigd door C-vormige kraakbeenringen en bekleed met trilhaarepitheel.","definition":"<p>De <strong>trachea</strong> loopt van de onderrand van het cricoïd (±C6) tot de <em>carina</em> (±T4–T5), waar hij splitst in de linker en rechter hoofdbronchus.</p><p>Ze wordt opengehouden door 16–20 C-vormige ringen van hyalien kraakbeen die dorsaal open zijn; daar ligt de m. trachealis (gladde spier), tegen de slokdarm aan. De binnenkant is bekleed met <em>meerrijig trilhaarcilindrisch epitheel</em> met slijmbekercellen (respiratoir epitheel).</p>","image_url":"","wiki_title":"Trachea","match":"trachea|luchtpijp","option_only":true},"ductus alveolaris":{"title":"Ductus alveolaris","short":"Ductus alveolares zijn de gangetjes na de bronchioli respiratorii waarvan de wand vrijwel geheel uit alveoli bestaat.","definition":"<p>De <strong>ductus alveolaris</strong> volgt in de luchtwegboom op de bronchiolus respiratorius en eindigt in de sacculi alveolares. De wand bestaat bijna helemaal uit openingen naar alveoli, met tussen de openingen kleine bundeltjes gladde spier.</p><p>Hij hoort bij het <em>respiratoire deel</em> van de long, waar gaswisseling plaatsvindt (samen met bronchioli respiratorii en alveoli), in tegenstelling tot het geleidende deel (trachea t/m bronchioli terminales).</p>","image_url":"","wiki_title":"Alveolar duct","match":"ductus alveolaris|ductuli alveolares|alveolaire gang","option_only":true},"pneumothorax":{"title":"Pneumothorax","short":"Een pneumothorax is lucht in de pleuraholte, waardoor de long (deels) inklapt; acuut kortademig met pijn, bij spanningspneumothorax levensbedreigend.","definition":"<p>Bij een <strong>pneumothorax</strong> komt lucht tussen de pleurabladen, waardoor de negatieve intrapleurale druk verdwijnt en de long door zijn elastische terugslag inklapt.</p><p>Hij kan spontaan ontstaan (primair bij lange, slanke jonge mannen door blebs; secundair bij longziekte zoals COPD) of na trauma. Klachten: plotselinge pijn op de borst en kortademigheid; verminderd ademgeruis en hypersonore percussie. Bij een <em>spanningspneumothorax</em> hoopt lucht zich op als een ventiel, met verschuiving van het mediastinum en circulatoire shock: direct ontlasten.</p>","image_url":"","wiki_title":"Pneumothorax","match":"pneumothorax|klaplong","option_only":true},"longfibrose":{"title":"Longfibrose","short":"Bij longfibrose wordt het longinterstitium vervangen door bindweefsel; de long wordt stug, met een restrictief beeld en verminderde diffusie.","definition":"<p>Bij <strong>longfibrose</strong> leidt beschadiging en abnormaal herstel van het longinterstitium tot verlittekening. Oorzaken zijn idiopathisch (IPF), stofblootstelling (asbest, silica), auto-immuunziekten, medicatie, bestraling of chronische extrinsieke allergische alveolitis.</p><p>De long wordt stijver (lagere compliantie): een <em>restrictieve</em> longfunctiestoornis (lage TLC en VC, normale of verhoogde FEV1/FVC) met verlaagde diffusiecapaciteit. Klachten: progressieve kortademigheid en droge hoest; bij auscultatie fijne ‘knisper’crepitaties; vaak trommelstokvingers.</p>","image_url":"","wiki_title":"Pulmonary fibrosis","match":"longfibrose|pulmonale fibrose|idiopathische pulmonale fibrose|ipf","option_only":true},"x-thorax":{"title":"X-thorax","short":"Een X-thorax is een röntgenfoto van de borstkas; het eerste beeldvormend onderzoek bij verdenking op longafwijkingen, hartfalen of pneumothorax.","definition":"<p>Een <strong>X-thorax</strong> is een röntgenopname van de borstkas, meestal posterieur-anterieur en lateraal. Lucht is zwart, weke delen grijs en bot wit.</p><p>Het is snel, goedkoop en met een lage stralingsdosis, en wordt gebruikt om o.a. pneumonie (infiltraat), pleuravocht, pneumothorax, longtumoren, hartvergroting en tekenen van hartfalen op te sporen. Kleine of subtiele afwijkingen zijn er minder goed op te zien dan op een CT.</p>","image_url":"","wiki_title":"Chest radiograph","match":"x-thorax|thoraxfoto|röntgenfoto van de thorax|x thorax|x-thorax (röntgenfoto)","option_only":true},"echo abdomen":{"title":"Echo abdomen","short":"Een echo abdomen is een echografisch onderzoek van de buikorganen; zonder straling en goed voor galblaas, galwegen, lever, nieren en vrij vocht.","definition":"<p>Bij een <strong>echo abdomen</strong> wordt met geluidsgolven een beeld gemaakt van de buikorganen. Het onderzoek gebruikt geen ioniserende straling, is goedkoop en direct beschikbaar.</p><p>Het is bijzonder geschikt voor het aantonen van galstenen en cholecystitis, verwijde galwegen, leverafwijkingen, nierstuwing (hydronefrose), een abdominaal aorta-aneurysma en vrij vocht. Darmgas en een dikke buikwand beperken het zicht; de kwaliteit hangt af van de onderzoeker.</p>","image_url":"","wiki_title":"Abdominal ultrasonography","match":"echo abdomen|echografie abdomen|echo van de buik|abdominale echografie|echo-abdomen","option_only":true},"ct abdomen":{"title":"CT abdomen","short":"Een CT abdomen is een röntgenscan in dwarsdoorsneden van de buik, vaak met contrast; goed voor acute buik, tumoren, abcessen en trauma.","definition":"<p>Bij een <strong>CT abdomen</strong> worden met röntgenstraling dunne dwarsdoorsneden van de buik gemaakt, meestal met intraveneus (en soms oraal) contrast.</p><p>Het geeft een overzichtelijk beeld van alle buikorganen, de darm en het retroperitoneum en wordt gebruikt bij een acute buik (bijv. perforatie, diverticulitis, appendicitis bij volwassenen), bij het stadiëren van tumoren, het opsporen van abcessen en bij trauma. Nadelen zijn de stralingsbelasting en het contrastmiddel (nierfunctie, allergie).</p>","image_url":"","wiki_title":"CT scan","match":"ct abdomen|ct-abdomen|ct van de buik|ct-scan abdomen","option_only":true},"endotheelcellen":{"title":"Endotheelcellen","short":"Endotheelcellen bekleden als één dunne laag de binnenkant van alle bloed- en lymfevaten en regelen vaattonus, stolling en doorlaatbaarheid.","definition":"<p><strong>Endotheel</strong> is een enkellaags plaveiselepitheel dat de binnenwand (tunica intima) van bloed- en lymfevaten en het hart bekleedt.</p><p>Endotheelcellen zijn actief: ze maken vaatverwijders (NO, prostacycline) en -vernauwers (endotheline), houden het bloed vloeibaar (antistollingsfactoren) maar kunnen bij beschadiging de stolling activeren (von Willebrandfactor), en laten leukocyten via adhesiemoleculen het weefsel in tijdens ontsteking.</p>","image_url":"","wiki_title":"Endothelium","match":"endotheelcellen|endotheel|endotheelcel","option_only":true},"gladde spiercellen":{"title":"Gladde spiercellen","short":"Gladde spiercellen zijn spoelvormige, onwillekeurig aangestuurde spiercellen zonder dwarsstreping, in de wand van vaten en holle organen.","definition":"<p><strong>Gladde spiercellen</strong> zijn spoelvormige cellen met één centraal gelegen kern. Actine en myosine liggen niet in sarcomeren, daarom ontbreekt de dwarsstreping. Contractie wordt via calcium-calmoduline en myosine-lichteketenkinase gereguleerd.</p><p>Ze komen voor in de wand van bloedvaten, luchtwegen, maag-darmkanaal, blaas en uterus en worden aangestuurd door het autonome zenuwstelsel, hormonen en lokale factoren. Ze kunnen langdurig samentrekken met weinig energieverbruik.</p>","image_url":"","wiki_title":"Smooth muscle","match":"gladde spiercellen|glad spierweefsel|gladde spier|gladde spiercel","option_only":true},"stembandpoliep":{"title":"Stembandpoliep","short":"Een stembandpoliep is een goedaardige, meestal eenzijdige zwelling op de stemband, vaak door stemmisbruik of roken; het geeft heesheid.","definition":"<p>Een <strong>stembandpoliep</strong> is een goedaardige, vaak eenzijdige uitgroei van de stemband, meestal aan de vrije rand. Ze ontstaat door overbelasting van de stem (schreeuwen), roken of irritatie (reflux); soms na een bloedinkje in de stemband.</p><p>De belangrijkste klacht is <em>heesheid</em> en een minder belastbare stem. Diagnose door laryngoscopie; behandeling is meestal microchirurgische verwijdering en stemtherapie.</p>","image_url":"","wiki_title":"Vocal fold polyp","match":"stembandpoliep|stembandpoliepen","option_only":true},"maligniteit":{"title":"Maligniteit","short":"Een maligniteit is een kwaadaardige tumor: ongecontroleerd groeiende cellen die omliggend weefsel binnendringen en kunnen uitzaaien.","definition":"<p>Een <strong>maligniteit</strong> (kanker) is een tumor waarvan de cellen ongeremd delen, het omliggende weefsel <em>infiltreren</em> en via bloed- of lymfevaten kunnen <em>metastaseren</em>. Dat onderscheidt ze van goedaardige (benigne) tumoren, die expansief groeien zonder invasie.</p><p>Maligniteiten ontstaan door een opeenstapeling van genetische veranderingen (activatie van oncogenen, uitschakeling van tumorsuppressorgenen). Systemische verschijnselen kunnen zijn: gewichtsverlies, moeheid, nachtzweten, anemie, trombose en paraneoplastische syndromen.</p>","image_url":"","wiki_title":"","match":"maligniteit|maligne tumor|kanker|kwaadaardige tumor","option_only":true},"maagcarcinoom":{"title":"Maagcarcinoom","short":"Een maagcarcinoom is een kwaadaardige tumor (meestal adenocarcinoom) van de maag; risicofactoren zijn o.a. H. pylori, roken en zoutrijke voeding.","definition":"<p>Het <strong>maagcarcinoom</strong> is meestal een adenocarcinoom, uitgaand van het klierepitheel. Het intestinale type ontstaat via een reeks van chronische (H. pylori-)gastritis, atrofie, intestinale metaplasie en dysplasie; het diffuse type (zegelringcellen) infiltreert de wand zonder duidelijke massa (linitis plastica).</p><p>Klachten komen vaak laat: verminderde eetlust, vroege verzadiging, gewichtsverlies, epigastrische pijn, anemie of slikklachten. Metastasen kunnen zich manifesteren als een klier van Virchow (links supraclaviculair) of ovariummetastasen (Krukenberg).</p>","image_url":"","wiki_title":"Stomach cancer","match":"maagcarcinoom|maagkanker|adenocarcinoom van de maag","option_only":true},"diarree":{"title":"Diarree","short":"Diarree is het vaker dan normaal (≥3x per dag) produceren van brijige tot waterdunne ontlasting.","definition":"<p><strong>Diarree</strong> betekent een verhoogde frequentie (meestal ≥3 keer per dag) en verminderde consistentie van de ontlasting. Acute diarree (&lt;2 weken) is meestal infectieus (virussen zoals norovirus, bacteriën, parasieten).</p><p>Mechanismen: <em>secretoir</em> (bijv. door toxines zoals choleratoxine), <em>osmotisch</em> (bijv. lactose-intolerantie, laxantia), <em>inflammatoir</em> (bijv. IBD, invasieve bacteriën, met bloed en slijm) en versnelde motiliteit. Het belangrijkste risico is uitdroging en elektrolytverlies.</p>","image_url":"","wiki_title":"Diarrhea","match":"diarree","option_only":true},"bacteriële overgroei":{"title":"Bacteriële overgroei van de dunne darm","short":"Bij bacteriële overgroei zijn er te veel bacteriën in de dunne darm, met een opgeblazen gevoel, diarree, malabsorptie en B12-tekort.","definition":"<p>Normaal bevat de dunne darm weinig bacteriën. Bij <strong>bacteriële overgroei</strong> (SIBO) nemen die sterk toe, bijvoorbeeld door verminderde motiliteit (diabetes, sclerodermie), anatomische afwijkingen (blinde lis, divertikels, na operaties) of verminderd maagzuur.</p><p>De bacteriën deconjugeren galzouten (vetmalabsorptie, steatorroe), fermenteren koolhydraten (opgeblazen gevoel, winderigheid, diarree) en verbruiken vitamine B12 (tekort). Foliumzuur kan juist hoog zijn. Diagnose o.a. via een waterstofademtest; behandeling met antibiotica.</p>","image_url":"","wiki_title":"","match":"bacteriële overgroei|bacteriële overgroei van de dunne darm|sibo|dunnedarmbacteriële overgroei","option_only":true},"anemie":{"title":"Anemie","short":"Anemie is een te laag hemoglobinegehalte in het bloed, waardoor het zuurstoftransport vermindert.","definition":"<p>Bij <strong>anemie</strong> is de hemoglobineconcentratie verlaagd (bij volwassenen ongeveer &lt;8,5 mmol/L bij mannen en &lt;7,5 mmol/L bij vrouwen). Klachten: moeheid, kortademigheid bij inspanning, bleekheid en hartkloppingen.</p><p>Indeling op het MCV: <em>microcytair</em> (o.a. ijzergebrek, thalassemie), <em>normocytair</em> (o.a. acuut bloedverlies, chronische ziekte, nierfalen) en <em>macrocytair</em> (o.a. vitamine B12- of foliumzuurtekort). Daarnaast onderscheidt men verminderde aanmaak van versterkte afbraak (hemolyse) of verlies.</p>","image_url":"","wiki_title":"Anemia","match":"anemie|bloedarmoede","option_only":true},"koorts":{"title":"Koorts","short":"Koorts is een verhoogde lichaamstemperatuur (≥38,0 °C) doordat de hypothalamus het setpoint hoger instelt, meestal als reactie op infectie.","definition":"<p>Bij <strong>koorts</strong> wordt het temperatuursetpoint in de hypothalamus verhoogd. Pyrogenen zoals bacteriële producten en cytokines (IL-1, IL-6, TNF) stimuleren daar de productie van prostaglandine E<sub>2</sub>.</p><p>Het lichaam ervaart de normale temperatuur dan als te koud: vasoconstrictie en rillingen verhogen de temperatuur. Als het setpoint weer daalt, volgen zweten en vasodilatatie. Koortsremmers (paracetamol, NSAID's) remmen de prostaglandinesynthese. Hyperthermie (bijv. hitteberoerte) is iets anders: daar is het setpoint níet verhoogd.</p>","image_url":"","wiki_title":"Fever","match":"koorts|febris|pyrexie|hoge koorts","option_only":true},"lever":{"title":"Lever","short":"De lever is de grootste klier van het lichaam: hij regelt stofwisseling van suikers, vetten en eiwitten, maakt gal en eiwitten (o.a. albumine, stollingsfactoren) en ontgift stoffen.","definition":"<p>De <strong>lever</strong> ligt rechtsboven in de buik en krijgt bloed uit de a. hepatica en (voor ±75%) uit de <em>v. portae</em>, met voedingsstoffen uit de darm.</p><p>Functies: opslag en afgifte van glucose (glycogeen, gluconeogenese), vet- en cholesterolmetabolisme, aanmaak van plasma-eiwitten (albumine, stollingsfactoren), ureumvorming, galproductie, afbraak van bilirubine en ontgifting van geneesmiddelen en alcohol. Functionele eenheden zijn de leverlobjes met hepatocyten rond sinusoïden.</p>","image_url":"","wiki_title":"Liver","match":"lever|hepar","option_only":true},"hepatocyten":{"title":"Hepatocyten","short":"Hepatocyten zijn de levercellen die vrijwel alle metabole, synthetiserende en ontgiftende functies van de lever uitvoeren.","definition":"<p><strong>Hepatocyten</strong> vormen ±80% van het levervolume. Ze liggen in balkjes langs de sinusoïden en hebben veel mitochondriën, glad en ruw ER en Golgi.</p><p>Ze maken plasma-eiwitten (albumine, stollingsfactoren), gal, glucose (gluconeogenese) en ureum, slaan glycogeen, vet en vitamines op en ontgiften stoffen via het cytochroom P450-systeem. Tussen naburige hepatocyten liggen de galcanaliculi.</p>","image_url":"","wiki_title":"Hepatocyte","match":"hepatocyten|levercellen|hepatocyt","option_only":true},"maag":{"title":"Maag","short":"De maag slaat voedsel tijdelijk op, mengt het met maagzuur en pepsine en geeft het geleidelijk af aan het duodenum.","definition":"<p>De <strong>maag</strong> bestaat uit cardia, fundus, corpus, antrum en pylorus. Het slijmvlies bevat klieren met <em>pariëtale cellen</em> (zoutzuur en intrinsieke factor), <em>hoofdcellen</em> (pepsinogeen), slijmcellen en endocriene cellen (o.a. G-cellen met gastrine in het antrum).</p><p>De maag doodt micro-organismen, start de eiwitvertering en mengt voedsel tot chymus. Intrinsieke factor is nodig voor opname van vitamine B12 in het terminale ileum.</p>","image_url":"","wiki_title":"Stomach","match":"maag|gaster|ventriculus","option_only":true},"pancreas":{"title":"Pancreas","short":"De pancreas is zowel een exocriene klier (verteringsenzymen en bicarbonaat naar het duodenum) als een endocriene klier (insuline en glucagon uit de eilandjes van Langerhans).","definition":"<p>De <strong>pancreas</strong> ligt retroperitoneaal achter de maag, met de kop in de bocht van het duodenum.</p><p>Het <em>exocriene</em> deel (±98%) maakt verteringsenzymen (trypsine(ogeen), lipase, amylase) en bicarbonaatrijk sap, dat via de ductus pancreaticus samen met de galweg in het duodenum uitmondt. Het <em>endocriene</em> deel bestaat uit de eilandjes van Langerhans met bètacellen (insuline), alfacellen (glucagon) en deltacellen (somatostatine).</p>","image_url":"","wiki_title":"Pancreas","match":"pancreas|alvleesklier","option_only":true},"galblaas":{"title":"Galblaas","short":"De galblaas slaat gal uit de lever op en dikt die in; na een vetrijke maaltijd trekt hij samen onder invloed van cholecystokinine.","definition":"<p>De <strong>galblaas</strong> ligt aan de onderzijde van de lever en is via de ductus cysticus verbonden met de galwegen. Ze slaat de gal die de lever continu maakt op en concentreert die door water en zout terug te resorberen.</p><p>Na een (vetrijke) maaltijd geeft het duodenum <em>cholecystokinine</em> af: de galblaas trekt samen en de sfincter van Oddi ontspant, zodat gal in het duodenum komt voor de vetvertering. Galstenen kunnen koliek, cholecystitis of een choledocholithiasis geven.</p>","image_url":"","wiki_title":"Gallbladder","match":"galblaas|vesica biliaris|vesica fellea","option_only":true},"de milt":{"title":"Milt","short":"De milt filtert het bloed: hij ruimt oude en beschadigde rode bloedcellen op en vormt een afweerorgaan tegen bacteriën in het bloed.","definition":"<p>De <strong>milt</strong> ligt linksboven in de buik onder het diafragma. Ze bestaat uit <em>rode pulpa</em> (sinusoïden waar verouderde of afwijkende erytrocyten worden afgebroken) en <em>witte pulpa</em> (lymfatisch weefsel met B- en T-cellen rond arteriolen).</p><p>De milt is belangrijk voor de afweer tegen <em>gekapselde bacteriën</em> (pneumokok, meningokok, H. influenzae). Na splenectomie is het risico op een ernstige sepsis daardoor verhoogd; deze patiënten worden gevaccineerd.</p>","image_url":"","wiki_title":"Spleen","match":"de milt|milt|lien|splenomegalie","option_only":true},"appendix":{"title":"Appendix","short":"De appendix is een wormvormig aanhangsel van het caecum met veel lymfatisch weefsel; ontsteking ervan (appendicitis) is een veelvoorkomende acute buik.","definition":"<p>De <strong>appendix vermiformis</strong> is een smal, blind eindigend aanhangsel van het caecum, meestal rechtsonder in de buik. De wand bevat veel lymfoïde follikels.</p><p>Bij <em>appendicitis</em> raakt het lumen afgesloten (bijv. door een fecoliet of lymfoïde hyperplasie), waarna ontsteking en infectie volgen. Typisch begint de pijn rond de navel en verplaatst zich naar rechtsonder (punt van McBurney), met misselijkheid en koorts.</p>","image_url":"","wiki_title":"Appendix (anatomy)","match":"appendix|blindedarm|appendix vermiformis|wormvormig aanhangsel","option_only":true},"colon ascendens":{"title":"Colon ascendens","short":"Het colon ascendens is het opstijgende deel van de dikke darm rechts in de buik, van caecum tot flexura hepatica; het ligt secundair retroperitoneaal.","definition":"<p>Het <strong>colon ascendens</strong> loopt aan de rechterzijde van de buik omhoog van het caecum tot de <em>flexura coli dextra</em> (hepatica) onder de lever, waar het overgaat in het colon transversum.</p><p>Het ligt secundair retroperitoneaal. De bloedvoorziening komt uit de a. mesenterica superior (a. ileocolica en a. colica dextra). In dit deel is de ontlasting nog vloeibaar en wordt veel water en zout teruggeresorbeerd.</p>","image_url":"","wiki_title":"Ascending colon","match":"colon ascendens|opstijgende colon|opstijgend colon","option_only":true},"nad+":{"title":"NAD⁺","short":"NAD⁺ is een elektronendrager die bij oxidatiereacties wordt gereduceerd tot NADH; NADH levert de elektronen aan complex I van de ademhalingsketen.","definition":"<p><strong>NAD⁺</strong> (nicotinamide-adenine-dinucleotide) is een co-enzym afgeleid van niacine (vitamine B3). Het neemt bij oxidatiereacties een hydride-ion op en wordt dan <em>NADH</em>.</p><p>NADH wordt gevormd in de glycolyse, door pyruvaatdehydrogenase, in de citroenzuurcyclus en in de bèta-oxidatie. Het geeft zijn elektronen af aan <em>complex I</em> van de elektronentransportketen. Zonder zuurstof wordt NAD⁺ geregenereerd door pyruvaat om te zetten in lactaat.</p>","image_url":"","wiki_title":"Nicotinamide adenine dinucleotide","match":"nad+|nad⁺|nadh|nicotinamide-adenine-dinucleotide","option_only":true},"crp":{"title":"CRP (C-reactief proteïne)","short":"CRP is een acutefase-eiwit uit de lever dat binnen een dag sterk stijgt bij ontsteking of infectie, vooral bacterieel.","definition":"<p><strong>C-reactief proteïne</strong> wordt door de lever gemaakt onder invloed van vooral <em>IL-6</em>. Het bindt aan fosfocholine op micro-organismen en beschadigde cellen en activeert zo complement (opsonisatie).</p><p>Het CRP stijgt binnen 6–12 uur na het begin van een ontsteking en daalt snel bij herstel, waardoor het een nuttige maat is voor ontstekingsactiviteit. Bacteriële infecties geven vaak een hoger CRP dan virale, maar de waarde is niet specifiek.</p>","image_url":"","wiki_title":"C-reactive protein","match":"crp|c-reactief proteïne|c-reactief proteine","option_only":true},"astma":{"title":"Astma","short":"Astma is een chronische ontsteking van de luchtwegen met wisselende, reversibele luchtwegobstructie en hyperreactiviteit; klachten zijn piepen, benauwdheid en hoesten.","definition":"<p>Bij <strong>astma</strong> zijn de luchtwegen chronisch ontstoken (vaak eosinofiel/Th2-gemedieerd) en <em>hyperreactief</em>: op prikkels zoals allergenen, inspanning, koude lucht of rook ontstaan bronchoconstrictie, slijmvliesoedeem en slijmproductie.</p><p>De obstructie is variabel en grotendeels <em>reversibel</em> (verbetering van de FEV1 na een luchtwegverwijder). Klachten: aanvallen van piepen, kortademigheid, een beklemd gevoel op de borst en hoesten, vaak ’s nachts. Behandeling met inhalatiecorticosteroïden en luchtwegverwijders.</p>","image_url":"","wiki_title":"Asthma","match":"astma|asthma|astma bronchiale","option_only":true},"duodenum":{"title":"Duodenum (twaalfvingerige darm)","short":"Het duodenum is het eerste, C-vormige deel van de dunne darm; hier komen gal en pancreassap bij de voedselbrij.","definition":"<p>Het <strong>duodenum</strong> loopt van de pylorus in een C-bocht om de pancreaskop heen en gaat bij de flexura duodenojejunalis over in het jejunum. Het ligt grotendeels retroperitoneaal. In de pars descendens mondt via de papil van Vater de ductus choledochus samen met de ductus pancreaticus uit. Klieren van Brunner in de submucosa maken bicarbonaatrijk slijm dat het zure chymus neutraliseert; endocriene cellen maken o.a. secretine en cholecystokinine.</p>","image_url":"","wiki_title":"Duodenum","match":"duodenum|twaalfvingerige darm","option_only":true},"colon":{"title":"Colon (dikke darm)","short":"Het colon is de dikke darm van caecum tot rectum; het resorbeert water en zouten en dikt de ontlasting in.","definition":"<p>Het <strong>colon</strong> bestaat uit caecum, colon ascendens, transversum, descendens en sigmoideum, gevolgd door het rectum. Kenmerkend zijn taeniae coli, haustra en appendices epiploicae. Het slijmvlies heeft geen villi maar wel diepe crypten met veel slijmbekercellen. Het colon resorbeert water en elektrolyten, en de darmflora fermenteert vezels tot korteketenvetzuren.</p>","image_url":"","wiki_title":"Large intestine","match":"colon|dikke darm|dikkedarm","option_only":true},"dikke darm":{"title":"Dikke darm","short":"De dikke darm (caecum, colon en rectum) resorbeert water en zouten en vormt de ontlasting.","definition":"<p>De <strong>dikke darm</strong> loopt van de ileocaecaalklep tot de anus en bestaat uit caecum met appendix, colon en rectum. Hij resorbeert vooral water en natrium, en bevat een rijke bacteriële flora die onverteerbare vezels fermenteert en vitamine K maakt. Het slijmvlies is vlak met crypten en veel slijmbekercellen.</p>","image_url":"","wiki_title":"Large intestine","match":"dikke darm","option_only":true},"dunne darm":{"title":"Dunne darm","short":"De dunne darm (duodenum, jejunum, ileum) is het belangrijkste deel van het maag-darmkanaal voor vertering en opname van voedingsstoffen.","definition":"<p>De <strong>dunne darm</strong> is enkele meters lang en bestaat uit duodenum, jejunum en ileum. Kringplooien, villi en microvilli vergroten het oppervlak enorm. Hier worden koolhydraten, eiwitten en vetten verteerd door pancreasenzymen en brush-border-enzymen en opgenomen; in het terminale ileum worden ook vitamine B12 en galzouten geresorbeerd.</p>","image_url":"","wiki_title":"Small intestine","match":"dunne darm|intestinum tenue","option_only":true},"jejunum":{"title":"Jejunum","short":"Het jejunum is het middelste deel van de dunne darm, met hoge kringplooien en veel opname van voedingsstoffen.","definition":"<p>Het <strong>jejunum</strong> volgt op het duodenum en ligt vooral linksboven in de buik, opgehangen aan het mesenterium. Vergeleken met het ileum heeft het een dikkere wand, hogere kringplooien (plicae circulares), minder vet in het mesenterium en weinig lange vaatarcades. Het grootste deel van de opname van suikers, aminozuren en vetten vindt hier plaats.</p>","image_url":"","wiki_title":"Jejunum","match":"jejunum","option_only":true},"ileum":{"title":"Ileum","short":"Het ileum is het laatste deel van de dunne darm; het terminale ileum neemt vitamine B12 en galzouten op.","definition":"<p>Het <strong>ileum</strong> ligt vooral rechtsonder in de buik en eindigt bij de ileocaecaalklep. Het heeft lagere kringplooien dan het jejunum en veel lymfatisch weefsel in de vorm van Peyerse platen. Het <em>terminale ileum</em> resorbeert vitamine B12 (gebonden aan intrinsieke factor) en galzouten, die via de enterohepatische kringloop terug naar de lever gaan.</p>","image_url":"","wiki_title":"Ileum","match":"ileum","option_only":true},"colon descendens":{"title":"Colon descendens","short":"Het colon descendens is het dalende deel van de dikke darm aan de linkerzijde van de buik.","definition":"<p>Het <strong>colon descendens</strong> loopt van de flexura coli sinistra (lienalis) langs de linkerflank naar beneden tot het colon sigmoideum. Het ligt secundair retroperitoneaal en wordt doorbloed door de a. mesenterica inferior (a. colica sinistra). De ontlasting is hier al grotendeels ingedikt.</p>","image_url":"","wiki_title":"Descending colon","match":"colon descendens|afdalend colon","option_only":true},"oesophagus":{"title":"Oesophagus (slokdarm)","short":"De oesophagus is de gespierde buis die voedsel van de keelholte naar de maag vervoert.","definition":"<p>De <strong>oesophagus</strong> is ongeveer 25 cm lang en loopt achter de trachea door het mediastinum en via de hiatus oesophageus van het diafragma naar de maag. Het slijmvlies is meerlagig onverhoornd plaveiselepitheel. Het bovenste deel bevat dwarsgestreepte, het onderste deel gladde spier. De onderste slokdarmsfincter voorkomt terugstroom van maaginhoud.</p>","image_url":"","wiki_title":"Esophagus","match":"oesophagus|slokdarm|oesofagus|esophagus","option_only":true},"calcium":{"title":"Calcium","short":"Calcium is nodig voor botten, spiercontractie, zenuwgeleiding en stolling; de bloedspiegel wordt geregeld door PTH, vitamine D en calcitonine.","definition":"<p>Het meeste <strong>calcium</strong> zit in botten als hydroxyapatiet. In het bloed is ongeveer de helft eiwitgebonden (vooral aan albumine) en de rest vrij geïoniseerd, de biologisch actieve vorm. Calcium is tweede boodschapper in cellen en essentieel voor spiercontractie, neurotransmitterafgifte en stolling. Afwijkingen geven bijv. tetanie (hypocalciëmie) of dorst, obstipatie en verwardheid (hypercalciëmie).</p>","image_url":"","wiki_title":"Calcium in biology","match":"calcium|ca2+|calciumion","option_only":true},"aminozuren":{"title":"Aminozuren","short":"Aminozuren zijn de bouwstenen van eiwitten; ze bevatten een aminogroep, een carboxylgroep en een specifieke zijketen.","definition":"<p>Er zijn 20 standaard-<strong>aminozuren</strong>, waarvan 9 essentieel (ze moeten uit de voeding komen). Ze worden via peptidebindingen aan elkaar gekoppeld tot eiwitten. Daarnaast zijn ze grondstof voor o.a. neurotransmitters, hormonen, heem en nucleotiden, en kunnen ze worden afgebroken voor energie of gluconeogenese; de stikstof wordt dan via de ureumcyclus afgevoerd.</p>","image_url":"","wiki_title":"Amino acid","match":"aminozuren|aminozuur","option_only":true},"triglyceriden":{"title":"Triglyceriden","short":"Triglyceriden zijn vetten opgebouwd uit glycerol met drie vetzuren; ze zijn de belangrijkste energieopslag in vetweefsel.","definition":"<p><strong>Triglyceriden</strong> worden uit de voeding via chylomicronen en uit de lever via VLDL door het bloed vervoerd. Lipoproteïnelipase in de capillairen splitst ze, zodat vetzuren in spier- en vetweefsel worden opgenomen. Een verhoogd triglyceridengehalte komt voor bij obesitas, diabetes, alcoholgebruik en erfelijke vetstofwisselingsstoornissen; zeer hoge waarden geven risico op pancreatitis.</p>","image_url":"","wiki_title":"Triglyceride","match":"triglyceriden|triglyceride|triacylglycerol","option_only":true},"insuline":{"title":"Insuline","short":"Insuline is het hormoon uit de bètacellen van de pancreas dat de bloedglucose verlaagt en opbouwprocessen stimuleert.","definition":"<p><strong>Insuline</strong> wordt afgegeven als de glucose stijgt. Het bevordert de opname van glucose in spier en vet (via GLUT4), de opslag als glycogeen en vet, en de eiwitsynthese, en remt gluconeogenese, glycogenolyse en lipolyse. Het wordt gemaakt als proinsuline; de afsplitsing van C-peptide maakt het actief. Als geneesmiddel is het onmisbaar bij diabetes type 1.</p>","image_url":"","wiki_title":"Insulin","match":"insuline|insulin","option_only":true},"glucagon":{"title":"Glucagon","short":"Glucagon is het hormoon uit de alfacellen van de pancreas dat de bloedglucose verhoogt, vooral via de lever.","definition":"<p><strong>Glucagon</strong> wordt afgegeven bij een lage glucose en bij eiwitrijke maaltijden. In de lever stimuleert het glycogenolyse, gluconeogenese en ketogenese via cAMP. Het is daarmee de tegenspeler van insuline. Glucagon kan intramusculair worden gegeven bij een ernstige hypoglykemie als iemand niet kan eten.</p>","image_url":"","wiki_title":"Glucagon","match":"glucagon","option_only":true},"adrenaline":{"title":"Adrenaline (epinefrine)","short":"Adrenaline is een catecholamine uit het bijniermerg dat de ‘fight-or-flight’-reactie aanstuurt via alfa- en bèta-receptoren.","definition":"<p><strong>Adrenaline</strong> wordt door chromaffiene cellen van het bijniermerg afgegeven bij stress. Het verhoogt hartfrequentie en contractiekracht (β1), verwijdt de bronchi (β2), vernauwt vaten in huid en darm (α1) en verhoogt de bloedglucose. Als geneesmiddel is het het middel bij anafylaxie (intramusculair) en wordt het gebruikt bij reanimatie.</p>","image_url":"","wiki_title":"Adrenaline","match":"adrenaline|epinefrine|epinephrine","option_only":true},"histamine":{"title":"Histamine","short":"Histamine is een mediator uit mestcellen en basofielen die vaatverwijding, lekkage, jeuk en bronchoconstrictie veroorzaakt.","definition":"<p><strong>Histamine</strong> ontstaat uit histidine en ligt opgeslagen in de granula van mestcellen en basofielen. Via H1-receptoren veroorzaakt het vaatverwijding, verhoogde vaatpermeabiliteit, jeuk en bronchoconstrictie; via H2-receptoren stimuleert het de maagzuursecretie. In het brein werkt het als neurotransmitter voor waakzaamheid.</p>","image_url":"","wiki_title":"Histamine","match":"histamine","option_only":true},"glutamaat":{"title":"Glutamaat (glutaminezuur)","short":"Glutamaat is de belangrijkste prikkelende neurotransmitter in het centrale zenuwstelsel en een centraal aminozuur in de stofwisseling.","definition":"<p><strong>Glutamaat</strong> werkt op ionotrope receptoren (AMPA, NMDA, kainaat) en metabotrope receptoren. NMDA-receptoren spelen een sleutelrol bij leren en geheugen (langetermijnpotentiëring). Overmatige activatie leidt tot instroom van calcium en celdood (excitotoxiciteit), bijvoorbeeld bij ischemie. In de stofwisseling is glutamaat een knooppunt van transaminering en stikstofafvoer.</p>","image_url":"","wiki_title":"Glutamic acid","match":"glutamaat|glutaminezuur|glutamate","option_only":true},"stikstofoxide":{"title":"Stikstofoxide (NO)","short":"Stikstofoxide (NO) is een gasvormige signaalstof uit het endotheel die gladde spier ontspant en zo vaten verwijdt.","definition":"<p><strong>NO</strong> wordt gemaakt uit arginine door NO-synthase. In het endotheel ontstaat het o.a. door schuifspanning en acetylcholine; het diffundeert naar de gladde spiercel, activeert guanylaatcyclase en verhoogt cGMP, wat relaxatie geeft. NO remt ook de plaatjesaggregatie. Nitraten en PDE5-remmers versterken deze route.</p>","image_url":"","wiki_title":"Nitric oxide","match":"stikstofoxide|stikstofmonoxide|no|nitric oxide","option_only":true},"lysozym":{"title":"Lysozym","short":"Lysozym is een antibacterieel enzym in traanvocht, speeksel en slijm dat de peptidoglycaanwand van bacteriën afbreekt.","definition":"<p><strong>Lysozym</strong> splitst de bindingen tussen N-acetylmuraminezuur en N-acetylglucosamine in peptidoglycaan. Het werkt vooral tegen grampositieve bacteriën, die een dikke, onbeschermde peptidoglycaanlaag hebben. Het is onderdeel van de aangeboren afweer en komt voor in tranen, speeksel, moedermelk en de granula van neutrofielen.</p>","image_url":"","wiki_title":"Lysozyme","match":"lysozym|lysozyme","option_only":true},"pepsinogeen":{"title":"Pepsinogeen","short":"Pepsinogeen is het inactieve voorstadium van pepsine, gemaakt door de hoofdcellen van de maag.","definition":"<p><strong>Pepsinogeen</strong> wordt afgegeven door hoofdcellen in de maagklieren. In het zure milieu (pH &lt; 4) splitst het zichzelf tot actief <em>pepsine</em>, een protease dat de eiwitvertering start. Pepsine wordt geïnactiveerd in het neutrale milieu van het duodenum.</p>","image_url":"","wiki_title":"Pepsin","match":"pepsinogeen|pepsine","option_only":true},"a. iliaca communis":{"title":"A. iliaca communis","short":"De aa. iliacae communes ontstaan uit de splitsing van de aorta abdominalis ter hoogte van L4.","definition":"<p>De <strong>a. iliaca communis</strong> loopt aan weerszijden schuin naar beneden en splitst zich ter hoogte van het sacro-iliacale gewricht in de a. iliaca externa (naar het been) en de a. iliaca interna (naar het bekken). De ureter kruist de iliacale vaten ongeveer bij deze splitsing.</p>","image_url":"","wiki_title":"Common iliac artery","match":"a. iliaca communis|arteria iliaca communis","option_only":true},"a. iliaca interna":{"title":"A. iliaca interna","short":"De a. iliaca interna voorziet de bekkenorganen, de bilspieren en het perineum van bloed.","definition":"<p>De <strong>a. iliaca interna</strong> ontstaat uit de a. iliaca communis en loopt het kleine bekken in. Ze heeft een voorste en achterste stam, met takken naar blaas, uterus (a. uterina), rectum, bilspieren (aa. gluteae) en perineum (a. pudenda interna). Bij de foetus lopen de navelarteriën vanuit deze arterie naar de placenta.</p>","image_url":"","wiki_title":"Internal iliac artery","match":"a. iliaca interna|arteria iliaca interna|a. hypogastrica","option_only":true},"a. mesenterica inferior":{"title":"A. mesenterica inferior","short":"De a. mesenterica inferior voorziet het distale derde van het colon transversum, het colon descendens, sigmoïd en bovenste rectum.","definition":"<p>De <strong>a. mesenterica inferior</strong> ontspringt ter hoogte van L3 uit de aorta abdominalis. Haar takken zijn de a. colica sinistra, de aa. sigmoideae en de a. rectalis superior. Via de arcade van Riolan en de marginale arterie (van Drummond) staat ze in verbinding met de a. mesenterica superior.</p>","image_url":"","wiki_title":"Inferior mesenteric artery","match":"a. mesenterica inferior|arteria mesenterica inferior","option_only":true},"truncus brachiocephalicus":{"title":"Truncus brachiocephalicus","short":"De truncus brachiocephalicus is de eerste en grootste tak van de aortaboog en splitst in de rechter a. subclavia en a. carotis communis.","definition":"<p>De <strong>truncus brachiocephalicus</strong> ontspringt als eerste tak van de arcus aortae, achter het manubrium sterni. Ter hoogte van het rechter sternoclaviculaire gewricht splitst hij in de a. subclavia dextra en a. carotis communis dextra. Links ontbreekt zo'n stam: daar ontspringen de a. carotis communis en a. subclavia apart uit de aortaboog.</p>","image_url":"","wiki_title":"Brachiocephalic artery","match":"truncus brachiocephalicus|a. anonyma","option_only":true},"a. subclavia dextra":{"title":"A. subclavia dextra","short":"De rechter a. subclavia ontspringt uit de truncus brachiocephalicus en voorziet de rechterarm en via de a. vertebralis een deel van het brein.","definition":"<p>De <strong>a. subclavia dextra</strong> ontstaat uit de truncus brachiocephalicus. Embryonaal ontstaat ze deels uit de rechter vierde kieuwboogarterie. Een bekende variant is een a. lusoria: een rechter a. subclavia die als laatste tak uit de aortaboog komt en achter de slokdarm langs loopt.</p>","image_url":"","wiki_title":"Subclavian artery","match":"a. subclavia dextra|arteria subclavia dextra|rechter a. subclavia","option_only":true},"a. subclavia sinistra":{"title":"A. subclavia sinistra","short":"De linker a. subclavia ontspringt direct uit de aortaboog als laatste van de drie grote takken.","definition":"<p>De <strong>a. subclavia sinistra</strong> komt rechtstreeks uit de arcus aortae. Ze geeft o.a. de a. vertebralis, a. thoracica interna en truncus thyrocervicalis af en gaat over de eerste rib heen over in de a. axillaris. Bij een stenose vlak voor de a. vertebralis kan een subclavian-steal-fenomeen ontstaan.</p>","image_url":"","wiki_title":"Subclavian artery","match":"a. subclavia sinistra|arteria subclavia sinistra|linker a. subclavia","option_only":true},"vena cava inferior":{"title":"Vena cava inferior","short":"De vena cava inferior voert het bloed uit benen, bekken en buik terug naar het rechteratrium.","definition":"<p>De <strong>vena cava inferior</strong> ontstaat ter hoogte van L5 uit de samenvloeiing van de vv. iliacae communes en loopt rechts van de aorta omhoog. Ze ontvangt o.a. de nier- en levervenen en gaat door het centrum tendineum van het diafragma (ter hoogte van T8) naar het rechteratrium.</p>","image_url":"","wiki_title":"Inferior vena cava","match":"vena cava inferior|v. cava inferior|onderste holle ader","option_only":true},"vena hepatica":{"title":"Vena hepatica (levervene)","short":"De venae hepaticae voeren het bloed uit de lever af naar de vena cava inferior.","definition":"<p>De drie grote <strong>venae hepaticae</strong> (rechts, midden, links) verzamelen het bloed uit de centrale venen van de leverlobjes en monden vlak onder het diafragma uit in de vena cava inferior. Ze lopen tussen de leversegmenten in. Afsluiting ervan heet het syndroom van Budd-Chiari.</p>","image_url":"","wiki_title":"Hepatic veins","match":"vena hepatica|v. hepatica|venae hepaticae|levervene","option_only":true},"enterokokken":{"title":"Enterokokken","short":"Enterokokken zijn grampositieve kokken uit de darmflora die van nature resistent zijn tegen cefalosporines.","definition":"<p><strong>Enterokokken</strong> (vooral <em>E. faecalis</em> en <em>E. faecium</em>) zijn grampositieve kokken in paren of korte ketens. Ze veroorzaken urineweginfecties, wondinfecties, intra-abdominale infecties en endocarditis, vaak in het ziekenhuis. Ze zijn intrinsiek ongevoelig voor cefalosporines; amoxicilline werkt meestal tegen <em>E. faecalis</em>. Vancomycineresistente stammen (VRE) zijn een ziekenhuishygiëneprobleem.</p>","image_url":"","wiki_title":"Enterococcus","match":"enterokokken|enterococcus|enterococcus faecalis|enterococcus faecium","option_only":true},"clostridium difficile":{"title":"Clostridioides difficile","short":"C. difficile is een sporenvormende anaerobe staaf die na antibioticagebruik een toxine-gemedieerde colitis kan veroorzaken.","definition":"<p><strong><em>Clostridioides difficile</em></strong> kan het colon koloniseren als de normale flora door antibiotica is verstoord. Toxine A en B beschadigen het colonepitheel, met waterige diarree, buikpijn en in ernstige gevallen pseudomembraneuze colitis of toxisch megacolon. De sporen zijn resistent tegen alcohol, dus handen wassen met zeep is nodig. Behandeling: vancomycine of fidaxomicine oraal.</p>","image_url":"","wiki_title":"Clostridioides difficile infection","match":"clostridium difficile|clostridioides difficile|c. difficile","option_only":true},"bacteroides fragilis":{"title":"Bacteroides fragilis","short":"Bacteroides fragilis is een gramnegatieve anaerobe staaf uit de darmflora en een belangrijke verwekker van buikabcessen.","definition":"<p><strong><em>Bacteroides fragilis</em></strong> is een van de talrijkste anaeroben in het colon. Bij perforatie of darmchirurgie kan hij in de buikholte terechtkomen en (met andere bacteriën) abcessen en peritonitis veroorzaken; het kapsel bevordert abcesvorming. Hij maakt vaak bètalactamase; metronidazol, amoxicilline-clavulaanzuur en carbapenems werken wel.</p>","image_url":"","wiki_title":"Bacteroides fragilis","match":"bacteroides fragilis|bacteroides","option_only":true},"lactobacillus spp":{"title":"Lactobacillus","short":"Lactobacillen zijn grampositieve staafjes die melkzuur maken; ze domineren de gezonde vaginale flora en komen voor in darm en gefermenteerd voedsel.","definition":"<p><strong>Lactobacillen</strong> fermenteren suikers tot melkzuur. In de vagina houden ze (onder invloed van oestrogeen en glycogeen) de pH laag, wat beschermt tegen ziekteverwekkers; afname ervan leidt tot bacteriële vaginose. Ze worden ook gebruikt in yoghurt en probiotica en zijn zelden ziekteverwekkend.</p>","image_url":"","wiki_title":"Lactobacillus","match":"lactobacillus spp|lactobacillus|lactobacillen|melkzuurbacteriën","option_only":true},"hepatitis c":{"title":"Hepatitis C","short":"Hepatitis C is een via bloed overgedragen RNA-virus dat vaak chronisch wordt en tot cirrose en levercelkanker kan leiden.","definition":"<p>Het <strong>hepatitis C-virus</strong> (flavivirus) wordt vooral via bloed overgedragen (drugsgebruik met naalden, vroeger transfusies). Een acute infectie verloopt meestal zonder klachten, maar wordt in de meerderheid chronisch. Na jaren kunnen fibrose, cirrose en hepatocellulair carcinoom ontstaan. Er is geen vaccin, maar direct werkende antivirale middelen genezen de infectie in vrijwel alle gevallen.</p>","image_url":"","wiki_title":"Hepatitis C","match":"hepatitis c|hcv|hepatitis c-virus","option_only":true},"hepatitis d":{"title":"Hepatitis D","short":"Hepatitis D is een defect virus dat alleen samen met hepatitis B kan vermenigvuldigen en een ernstiger leverziekte geeft.","definition":"<p>Het <strong>hepatitis D-virus</strong> heeft het oppervlakte-antigeen van hepatitis B (HBsAg) nodig voor zijn envelop. Het kan dus alleen tegelijk met HBV (co-infectie) of bij iemand met chronische HBV (superinfectie) voorkomen. Superinfectie leidt vaak tot snel progressieve leverziekte. Vaccinatie tegen hepatitis B beschermt ook tegen hepatitis D.</p>","image_url":"","wiki_title":"Hepatitis D","match":"hepatitis d|hdv|deltahepatitis","option_only":true},"copd":{"title":"COPD","short":"COPD is een chronische longziekte met niet volledig omkeerbare luchtwegobstructie, meestal door roken.","definition":"<p>Bij <strong>COPD</strong> leiden chronische ontsteking van de kleine luchtwegen en afbraak van alveolewanden (emfyseem) tot een blijvende obstructie: FEV1/FVC &lt; 0,7 na bronchodilatatie. Klachten zijn kortademigheid bij inspanning, chronische hoest en sputum, met periodes van verergering (exacerbaties). Belangrijkste behandeling: stoppen met roken, luchtwegverwijders, beweegprogramma's en vaccinaties.</p>","image_url":"","wiki_title":"Chronic obstructive pulmonary disease","match":"copd|chronic obstructive pulmonary disease|chronisch obstructieve longziekte","option_only":true},"acute bronchitis":{"title":"Acute bronchitis","short":"Acute bronchitis is een (meestal virale) ontsteking van de grote luchtwegen met hoesten, al dan niet met sputum.","definition":"<p>Bij <strong>acute bronchitis</strong> raakt het slijmvlies van de bronchi ontstoken, vaak na een verkoudheid. De hoest kan enkele weken aanhouden. Er zijn geen tekenen van een pneumonie (zoals lokale crepitaties of hoge koorts met ernstig ziek-zijn). Bij gezonde mensen zijn antibiotica niet nodig, ook niet bij gekleurd sputum.</p>","image_url":"","wiki_title":"Acute bronchitis","match":"acute bronchitis|bronchitis","option_only":true},"laryngitis":{"title":"Laryngitis","short":"Laryngitis is een ontsteking van het strottenhoofd, met heesheid en soms keelpijn en hoesten.","definition":"<p>Acute <strong>laryngitis</strong> is meestal viraal en gaat vaak samen met een verkoudheid; ook stembelasting kan een oorzaak zijn. De stembanden zwellen, wat heesheid of stemverlies geeft. Bij jonge kinderen kan een subglottische laryngitis (pseudokroep) een blafhoest en inspiratoire stridor geven. Chronische laryngitis kan ontstaan door roken of reflux.</p>","image_url":"","wiki_title":"Laryngitis","match":"laryngitis|strottenhoofdontsteking","option_only":true},"stembandverlamming":{"title":"Stembandverlamming","short":"Bij een stembandverlamming beweegt een stemband niet goed door uitval van de n. laryngeus recurrens, met heesheid als gevolg.","definition":"<p>Een <strong>stembandparese</strong> ontstaat meestal door schade aan de n. laryngeus recurrens, die links om de aortaboog en rechts om de a. subclavia loopt. Oorzaken zijn schildklier- of thoraxchirurgie, tumoren (long, slokdarm, schildklier, mediastinum) en idiopathisch. Een eenzijdige parese geeft een hese, ‘lekkende’ stem; een dubbelzijdige kan benauwdheid en stridor geven.</p>","image_url":"","wiki_title":"Vocal cord paresis","match":"stembandverlamming|stembandparese|recurrensparese","option_only":true},"longembolie":{"title":"Longembolie","short":"Bij een longembolie sluit een stolsel (meestal uit de beenvenen) een longslagader af, met acute benauwdheid en pijn bij het ademen.","definition":"<p>Een <strong>longembolie</strong> ontstaat meestal door een trombus uit de diepe venen van been of bekken. Risicofactoren volgen de trias van Virchow: stase (immobilisatie), hypercoagulabiliteit (kanker, oestrogenen, zwangerschap, erfelijke trombofilie) en vaatwandschade (operatie, trauma). Klachten: plotselinge dyspneu, pleuritische pijn, tachycardie, soms hemoptoë of collaps. Diagnostiek met een beslisregel, D-dimeer en CT-angiografie; behandeling met antistolling.</p>","image_url":"","wiki_title":"Pulmonary embolism","match":"longembolie|pulmonale embolie|longembolieën","option_only":true},"pulmonale hypertensie":{"title":"Pulmonale hypertensie","short":"Pulmonale hypertensie is een verhoogde druk in de longslagaders, die op termijn rechtszijdig hartfalen veroorzaakt.","definition":"<p>Bij <strong>pulmonale hypertensie</strong> is de gemiddelde druk in de a. pulmonalis verhoogd (&gt;20 mmHg in rust bij hartkatheterisatie). Oorzaken: linkszijdige hartziekte (meest voorkomend), longziekten met hypoxie, chronische longembolieën, en zeldzamer pulmonale arteriële hypertensie. Klachten zijn kortademigheid en vermoeidheid bij inspanning; later ontstaan oedeem en tekenen van rechtsfalen.</p>","image_url":"","wiki_title":"Pulmonary hypertension","match":"pulmonale hypertensie","option_only":true},"longcarcinoom":{"title":"Longcarcinoom","short":"Longkanker is een kwaadaardige tumor uitgaande van het epitheel van de luchtwegen; roken is de belangrijkste oorzaak.","definition":"<p>Het <strong>longcarcinoom</strong> wordt ingedeeld in niet-kleincellig (o.a. adenocarcinoom en plaveiselcelcarcinoom) en kleincellig longcarcinoom. Klachten zijn o.a. aanhoudende hoest, hemoptoë, kortademigheid, gewichtsverlies en recidiverende pneumonieën; vaak wordt het pas laat ontdekt. Paraneoplastische syndromen (zoals SIADH, hypercalciëmie, Lambert-Eaton) komen voor.</p>","image_url":"","wiki_title":"Lung cancer","match":"longcarcinoom|longkanker|bronchuscarcinoom","option_only":true},"ecg":{"title":"ECG (elektrocardiogram)","short":"Een ECG registreert de elektrische activiteit van het hart via elektroden op de huid.","definition":"<p>Een standaard <strong>12-afleidingen-ECG</strong> laat de P-top (boezemdepolarisatie), het QRS-complex (kamerdepolarisatie) en de T-top (repolarisatie) zien. Het wordt gebruikt om ritmestoornissen, geleidingsstoornissen, ischemie en infarct, hypertrofie en elektrolytstoornissen (bijv. hyperkaliëmie) op te sporen.</p>","image_url":"","wiki_title":"Electrocardiography","match":"ecg|elektrocardiogram|ekg","option_only":true},"oedeem":{"title":"Oedeem","short":"Oedeem is een ophoping van vocht in het interstitium, bijvoorbeeld als zwelling van enkels of onderbenen.","definition":"<p><strong>Oedeem</strong> ontstaat volgens de wetten van Starling door een verhoogde hydrostatische druk (hartfalen, veneuze insufficiëntie, overvulling), een verlaagde colloïd-osmotische druk (laag albumine bij nefrotisch syndroom, leverziekte, ondervoeding), een verhoogde vaatpermeabiliteit (ontsteking, allergie) of een verminderde lymfeafvoer (lymfoedeem). Putjesvormend oedeem blijft na indrukken even zichtbaar.</p>","image_url":"","wiki_title":"Edema","match":"oedeem|vochtophoping","option_only":true},"hypoventilatie":{"title":"Hypoventilatie","short":"Hypoventilatie is te weinig ademen voor de stofwisseling, waardoor het CO₂ in het bloed stijgt (respiratoire acidose).","definition":"<p>Bij <strong>hypoventilatie</strong> daalt de alveolaire ventilatie, met hypercapnie en vaak hypoxemie. Oorzaken zijn een verminderde ademprikkel (opioïden, sedativa, hersenstamletsel), neuromusculaire ziekten, ernstige obesitas, thoraxwandafwijkingen en ernstige COPD. Het lichaam compenseert met renale retentie van bicarbonaat.</p>","image_url":"","wiki_title":"Hypoventilation","match":"hypoventilatie","option_only":true},"obstipatie":{"title":"Obstipatie","short":"Obstipatie is een te harde en/of te weinig frequente ontlasting, vaak met moeizaam persen.","definition":"<p>Van <strong>obstipatie</strong> spreekt men bij minder dan drie keer per week ontlasting, harde ontlasting, persen of een gevoel van onvolledige lediging. Oorzaken zijn o.a. weinig vezels en vocht, weinig beweging, medicatie (opioïden, ijzer, anticholinergica, calciumantagonisten), hypothyreoïdie, hypercalciëmie, neurologische ziekten en obstructie door een tumor. Behandeling met leefstijladviezen en laxantia zoals macrogol.</p>","image_url":"","wiki_title":"Constipation","match":"obstipatie|verstopping|constipatie","option_only":true},"helicobacter pylori":{"title":"Helicobacter pylori","short":"Helicobacter pylori is een gekromde gramnegatieve bacterie die in de maag leeft en gastritis, ulcera, maagcarcinoom en MALT-lymfoom kan veroorzaken.","definition":"<p><strong><em>Helicobacter pylori</em></strong> overleeft in het zure milieu door urease, dat ureum omzet in ammoniak, en nestelt zich onder de slijmlaag. Besmetting gebeurt meestal op jonge leeftijd. Diagnose met een ademtest, antigeentest in de ontlasting of biopten. Eradicatie gebeurt met een protonpompremmer en twee antibiotica.</p>","image_url":"","wiki_title":"Helicobacter pylori","match":"helicobacter pylori|h. pylori|helicobacter","option_only":true},"coloncarcinoom":{"title":"Coloncarcinoom (darmkanker)","short":"Coloncarcinoom is een kwaadaardige tumor van de dikke darm, meestal een adenocarcinoom dat ontstaat uit een poliep.","definition":"<p>Het <strong>colorectaal carcinoom</strong> ontstaat meestal via de adenoom-carcinoomsequentie, waarbij mutaties (o.a. in APC, KRAS, p53) zich opstapelen. Risicofactoren zijn leeftijd, familiaire belasting (FAP, Lynch-syndroom), IBD, rood en bewerkt vlees, alcohol en roken. Klachten: veranderd ontlastingspatroon, bloed bij de ontlasting en ijzergebreksanemie. In Nederland is er een bevolkingsonderzoek met de FIT-test.</p>","image_url":"","wiki_title":"Colorectal cancer","match":"coloncarcinoom|darmkanker|colorectaal carcinoom|dikkedarmkanker","option_only":true},"colitis ulcerosa":{"title":"Colitis ulcerosa","short":"Colitis ulcerosa is een chronische ontstekingsziekte van het slijmvlies van de dikke darm, die altijd in het rectum begint en zich doorlopend naar proximaal uitbreidt.","definition":"<p>Bij <strong>colitis ulcerosa</strong> is alleen de mucosa ontstoken, zonder ‘skip lesions’. Klachten: bloederige diarree met slijm, aandrang en buikkrampen. Extra-intestinale verschijnselen zijn o.a. artritis, uveïtis, erythema nodosum en primaire scleroserende cholangitis. Langdurige ziekte verhoogt het risico op coloncarcinoom. Roken lijkt (in tegenstelling tot bij Crohn) beschermend.</p>","image_url":"","wiki_title":"Ulcerative colitis","match":"colitis ulcerosa|ulceratieve colitis","option_only":true},"coeliakie":{"title":"Coeliakie","short":"Coeliakie is een auto-immuunziekte waarbij gluten een ontsteking van de dunne darm met vlokatrofie veroorzaken.","definition":"<p>Bij <strong>coeliakie</strong> (geassocieerd met HLA-DQ2/DQ8) wordt gliadine door weefseltransglutaminase gemodificeerd en daarna door T-cellen herkend, wat leidt tot vlokatrofie en crypthyperplasie. Klachten: diarree, buikpijn, gewichtsverlies, groeiachterstand, ijzergebrek en vermoeidheid, maar ook atypische presentaties. Diagnose met anti-tTG-antistoffen en een duodenumbiopt; behandeling is een levenslang glutenvrij dieet.</p>","image_url":"","wiki_title":"Coeliac disease","match":"coeliakie|glutenintolerantie|glutenenteropathie","option_only":true},"peritoneum":{"title":"Peritoneum (buikvlies)","short":"Het peritoneum is het sereuze vlies dat de buikwand (pariëtaal) en de buikorganen (visceraal) bekleedt.","definition":"<p>Het <strong>peritoneum</strong> bestaat uit mesotheel op een laagje bindweefsel. Tussen het pariëtale en viscerale blad ligt de peritoneaalholte met een klein beetje vocht. Organen kunnen intraperitoneaal liggen (bijv. maag, jejunum, ileum, colon transversum) of retroperitoneaal (bijv. nieren, pancreas, duodenum grotendeels). Het pariëtale blad is pijngevoelig en goed te lokaliseren, het viscerale niet.</p>","image_url":"","wiki_title":"Peritoneum","match":"peritoneum|buikvlies","option_only":true},"refluxklachten":{"title":"Gastro-oesofageale reflux","short":"Bij refluxklachten stroomt maaginhoud terug in de slokdarm, met zuurbranden en oprispingen.","definition":"<p><strong>Gastro-oesofageale refluxziekte</strong> ontstaat bij een tekortschietende onderste slokdarmsfincter, een hiatus hernia of verhoogde druk in de buik (overgewicht, zwangerschap). Klachten zijn zuurbranden achter het borstbeen en zure oprispingen, soms hoesten of heesheid. Complicaties: oesofagitis, stenose en Barrett-slokdarm. Behandeling met leefstijladviezen en protonpompremmers.</p>","image_url":"","wiki_title":"Gastroesophageal reflux disease","match":"refluxklachten|reflux|gastro-oesofageale reflux|zuurbranden|refluxziekte","option_only":true},"omeprazol":{"title":"Omeprazol","short":"Omeprazol is een protonpompremmer die de maagzuurproductie sterk vermindert.","definition":"<p><strong>Omeprazol</strong> remt de H⁺/K⁺-ATPase van de pariëtale cellen onomkeerbaar. Het wordt gebruikt bij refluxziekte, ulcus pepticum, H. pylori-eradicatie en als maagbescherming bij NSAID-gebruik. Langdurig gebruik kan leiden tot o.a. hypomagnesiëmie, vitamine B12-tekort en een iets verhoogd risico op darminfecties; omeprazol remt CYP2C19.</p>","image_url":"","wiki_title":"Omeprazole","match":"omeprazol|protonpompremmer|ppi","option_only":true},"h2 antagonisten":{"title":"H2-receptorantagonisten","short":"H2-antagonisten blokkeren de histamine-H2-receptor op pariëtale cellen en verminderen zo de zuurproductie.","definition":"<p><strong>H2-receptorantagonisten</strong> zoals famotidine remmen de door histamine gestimuleerde zuursecretie. Ze zijn minder krachtig dan protonpompremmers en verloren daardoor terrein, maar worden nog gebruikt bij lichte refluxklachten. Ze werken sneller in maar korter dan PPI's.</p>","image_url":"","wiki_title":"H2 receptor antagonist","match":"h2 antagonisten|h2-antagonisten|h2-receptorantagonist|ranitidine|famotidine","option_only":true},"antacida":{"title":"Antacida","short":"Antacida zijn zwakke basen die maagzuur direct neutraliseren en snel verlichting geven bij zuurbranden.","definition":"<p><strong>Antacida</strong> bevatten bijvoorbeeld magnesium- of aluminiumhydroxide of calciumcarbonaat. Ze werken binnen minuten maar kort. Magnesiumzouten kunnen diarree geven, aluminiumzouten obstipatie. Ze kunnen de opname van andere geneesmiddelen (bijv. tetracyclines, ijzer, levothyroxine) verminderen.</p>","image_url":"","wiki_title":"Antacid","match":"antacida|antacidum|maagzuurbinders","option_only":true},"gastro-duodenoscopie":{"title":"Gastroduodenoscopie","short":"Bij een gastroduodenoscopie worden slokdarm, maag en duodenum met een flexibele endoscoop bekeken.","definition":"<p>Bij een <strong>gastroduodenoscopie</strong> gaat een flexibele scoop via de mond naar het duodenum. Er kunnen biopten worden genomen (bijv. voor coeliakie of H. pylori) en behandelingen worden uitgevoerd, zoals het stelpen van een bloeding of het oprekken van een stenose. Het onderzoek gebeurt met keelverdoving, eventueel met sedatie.</p>","image_url":"","wiki_title":"Esophagogastroduodenoscopy","match":"gastro-duodenoscopie|gastroduodenoscopie|gastroscopie","option_only":true},"coloscopie":{"title":"Coloscopie","short":"Bij een coloscopie wordt de hele dikke darm met een flexibele endoscoop bekeken, na darmvoorbereiding.","definition":"<p>Een <strong>coloscopie</strong> wordt gedaan bij o.a. bloed bij de ontlasting, een veranderd ontlastingspatroon, ijzergebreksanemie, een positieve FIT-test en voor surveillance bij poliepen of IBD. Poliepen kunnen direct worden verwijderd en er kunnen biopten worden genomen. Risico's zijn bloeding en (zelden) perforatie.</p>","image_url":"","wiki_title":"Colonoscopy","match":"coloscopie|colonoscopie","option_only":true},"diagnostische laparoscopie":{"title":"Diagnostische laparoscopie","short":"Bij een diagnostische laparoscopie wordt via kleine sneetjes met een camera in de buikholte gekeken.","definition":"<p>Bij een <strong>laparoscopie</strong> wordt de buik opgeblazen met CO₂ en via kleine incisies een camera en instrumenten ingebracht. Het wordt diagnostisch gebruikt bij onduidelijke buikpijn, verdenking op endometriose of buitenbaarmoederlijke zwangerschap en voor stadiëring van tumoren; vaak kan in dezelfde ingreep worden behandeld.</p>","image_url":"","wiki_title":"Laparoscopy","match":"diagnostische laparoscopie|laparoscopie|kijkoperatie","option_only":true},"nsaids":{"title":"NSAID's","short":"NSAID's remmen cyclo-oxygenase en daarmee de vorming van prostaglandinen; ze werken pijnstillend, koortsverlagend en ontstekingsremmend.","definition":"<p><strong>NSAID's</strong> (zoals ibuprofen, naproxen, diclofenac) remmen COX-1 en COX-2. Door remming van beschermende prostaglandinen kunnen ze maagulcera en bloedingen geven, vooral bij ouderen; ook kunnen ze de nierfunctie verslechteren, de bloeddruk verhogen, hartfalen verergeren en het risico op hart- en vaatziekten iets verhogen. Selectieve COX-2-remmers geven minder maagschade.</p>","image_url":"","wiki_title":"Nonsteroidal anti-inflammatory drug","match":"nsaids|nsaid|nsaid's|antiflogistica|ontstekingsremmers","option_only":true},"aceton":{"title":"Aceton (ketonlichaam)","short":"Aceton is een ketonlichaam dat ontstaat uit acetoacetaat; het geeft de zoete ‘nagellakgeur’ van de adem bij ketose.","definition":"<p>Bij vasten of insulinetekort maakt de lever uit vetzuren de <strong>ketonlichamen</strong> acetoacetaat en β-hydroxybutyraat, die door brein, hart en spier als brandstof gebruikt kunnen worden. Aceton ontstaat spontaan uit acetoacetaat, wordt niet verder gebruikt en wordt uitgeademd. Bij diabetische ketoacidose ruikt de adem daardoor fruitig.</p>","image_url":"","wiki_title":"Ketone bodies","match":"aceton|ketonlichamen|ketonen","option_only":true},"ongeconjugeerd bilirubine":{"title":"Ongeconjugeerd bilirubine","short":"Ongeconjugeerd bilirubine is het in vet oplosbare bilirubine dat bij de afbraak van heem ontstaat, voordat de lever het koppelt aan glucuronzuur.","definition":"<p>Bij afbraak van hemoglobine ontstaat <strong>ongeconjugeerd bilirubine</strong>, dat aan albumine gebonden naar de lever gaat. Daar koppelt UGT1A1 het aan glucuronzuur (geconjugeerd, wateroplosbaar). Een verhoogd ongeconjugeerd bilirubine past bij hemolyse, het syndroom van Gilbert of neonatale icterus; bij pasgeborenen kan het de bloed-hersenbarrière passeren (kernicterus).</p>","image_url":"","wiki_title":"Bilirubin","match":"ongeconjugeerd bilirubine|indirect bilirubine","option_only":true},"bnp":{"title":"BNP (brain natriuretic peptide)","short":"BNP is een hormoon uit de hartkamers dat vrijkomt bij rek van de wand; een verhoogde waarde past bij hartfalen.","definition":"<p><strong>BNP</strong> en het inactieve NT-proBNP worden afgegeven door ventrikelcellen bij volume- of drukbelasting. BNP bevordert natriurese en vaatverwijding en remt het RAAS. Een normale waarde maakt hartfalen bij een kortademige patiënt onwaarschijnlijk. Ook nierfalen, hoge leeftijd, longembolie en boezemfibrilleren verhogen de waarde.</p>","image_url":"","wiki_title":"Brain natriuretic peptide","match":"bnp|nt-probnp|natriuretisch peptide","option_only":true},"sinusoïdale endotheelcel":{"title":"Sinusoïdale endotheelcel","short":"Sinusoïdale endotheelcellen bekleden de leversinusoïden en hebben open poriën zonder echte basaalmembraan.","definition":"<p><strong>Lever-sinusoïdale endotheelcellen</strong> bevatten groepjes fenestrae (zeefplaten) waardoor plasma vrij de ruimte van Disse in kan stromen, in contact met de microvilli van hepatocyten. Ze ruimen ook kleine deeltjes uit het bloed op. Bij fibrose verdwijnen de fenestrae (capillarisatie).</p>","image_url":"","wiki_title":"Liver sinusoidal endothelial cell","match":"sinusoïdale endotheelcel|sinusoïdale endotheelcellen|lsec","option_only":true},"fat-storing cel":{"title":"Stellaatcel van de lever (Ito-cel)","short":"Stellaatcellen (Ito-cellen) liggen in de ruimte van Disse, slaan vitamine A op en worden bij leverschade de belangrijkste bron van fibrose.","definition":"<p>In rust slaan <strong>hepatische stellaatcellen</strong> vitamine A op in vetdruppels. Bij chronische leverschade worden ze geactiveerd en veranderen ze in myofibroblasten die veel collageen maken; dat is de kern van leverfibrose en cirrose.</p>","image_url":"","wiki_title":"Hepatic stellate cell","match":"fat-storing cel|ito-cel|stellaatcel|hepatische stellaatcel","option_only":true},"slijmbekercellen":{"title":"Slijmbekercellen","short":"Slijmbekercellen zijn eencellige klieren in het epitheel van darm en luchtwegen die slijm (mucine) afgeven.","definition":"<p><strong>Slijmbekercellen</strong> hebben een bekervorm doordat hun top gevuld is met mucinekorrels. Het slijm beschermt en smeert het epitheel en vangt deeltjes en micro-organismen. Ze zijn talrijk in het colon en in het respiratoire epitheel; bij chronische irritatie (bijv. roken) neemt hun aantal toe.</p>","image_url":"","wiki_title":"Goblet cell","match":"slijmbekercellen|slijmbekercel|goblet cells","option_only":true},"cilindrisch epitheel":{"title":"Cilindrisch epitheel","short":"Cilindrisch epitheel bestaat uit cellen die hoger zijn dan breed, met de kern aan de basis; het bekleedt o.a. maag en darm.","definition":"<p><strong>Eenlagig cilindrisch epitheel</strong> komt voor in maag, dunne en dikke darm en galblaas, en is gespecialiseerd in absorptie en secretie (vaak met microvilli of slijmbekercellen). Met trilharen komt het voor in de eileider. In de slokdarm kan plaveiselepitheel door cilindrisch epitheel vervangen worden (Barrett).</p>","image_url":"","wiki_title":"Simple columnar epithelium","match":"cilindrisch epitheel|eenlagig cilindrisch epitheel|cilinderepitheel","option_only":true},"meerlagig onverhoornend plaveiselepitheel":{"title":"Meerlagig onverhoornd plaveiselepitheel","short":"Meerlagig onverhoornd plaveiselepitheel beschermt vochtige oppervlakken tegen mechanische belasting, zoals mond, slokdarm en vagina.","definition":"<p>In <strong>meerlagig onverhoornd plaveiselepitheel</strong> worden de cellen naar boven toe platter, maar ze behouden hun kern en verhoornen niet. Het komt voor in mondholte, oesophagus, vagina, ectocervix en cornea. Het verhoornde type vormt de epidermis van de huid.</p>","image_url":"","wiki_title":"Stratified squamous epithelium","match":"meerlagig onverhoornend plaveiselepitheel|meerlagig onverhoornd plaveiselepitheel","option_only":true},"meerrijig plaveiselepitheel":{"title":"Meerrijig (pseudostratified) epitheel","short":"Meerrijig epitheel lijkt meerlagig, maar alle cellen raken de basaalmembraan; met trilharen bekleedt het de luchtwegen.","definition":"<p>In <strong>meerrijig epitheel</strong> liggen de kernen op verschillende hoogtes, waardoor het meerlagig lijkt, terwijl elke cel contact maakt met de basaalmembraan. Het klassieke voorbeeld is het respiratoire epitheel (meerrijig trilhaarcilinderepitheel met slijmbekercellen) in neus, trachea en bronchi. Een ‘meerrijig plaveiselepitheel’ bestaat strikt genomen niet.</p>","image_url":"","wiki_title":"Pseudostratified columnar epithelium","match":"meerrijig plaveiselepitheel|meerrijig epitheel|meerrijig trilhaarcilinderepitheel","option_only":true},"bronchus":{"title":"Bronchus","short":"Een bronchus is een luchtweg die van de trachea naar de longen vertakt; de wand bevat kraakbeen, klieren en gladde spier.","definition":"<p>De trachea splitst in de linker en rechter <strong>hoofdbronchus</strong>; de rechter is korter, wijder en loopt steiler, zodat ingeademde voorwerpen vaker rechts terechtkomen. Ze vertakken in lobaire en segmentale bronchi. De wand bevat kraakbeenplaatjes, seromuceuze klieren, gladde spier en respiratoir epitheel; bij de bronchioli verdwijnen kraakbeen en klieren.</p>","image_url":"","wiki_title":"Bronchus","match":"bronchus|bronchi|hoofdbronchus","option_only":true},"cloaca":{"title":"Cloaca","short":"De cloaca is het gemeenschappelijke eindstuk van de embryonale achterdarm, waarin ook de allantois uitmondt.","definition":"<p>Het urorectale septum verdeelt de <strong>cloaca</strong> in een dorsaal deel (rectum en bovenste anaalkanaal) en een ventraal deel, de sinus urogenitalis (blaas en urethra). Het cloacamembraan scheurt later. Een stoornis in deze verdeling geeft anorectale misvormingen en fistels.</p>","image_url":"","wiki_title":"Cloaca (embryology)","match":"cloaca","option_only":true},"hernia diafragmatica":{"title":"Hernia diafragmatica","short":"Bij een hernia diafragmatica liggen buikorganen via een defect in het diafragma in de borstholte.","definition":"<p>De <strong>congenitale hernia diafragmatica</strong> ontstaat meestal links-achter (hernia van Bochdalek) doordat de pleuroperitoneale membranen niet goed sluiten. Darmen en soms maag en lever liggen in de thorax en belemmeren de groei van de long (longhypoplasie, pulmonale hypertensie). De pasgeborene is direct na de geboorte benauwd met een ingevallen buik.</p>","image_url":"","wiki_title":"Congenital diaphragmatic hernia","match":"hernia diafragmatica|congenitale hernia diafragmatica|hernia van bochdalek","option_only":true},"adenocarcinoom":{"title":"Adenocarcinoom","short":"Een adenocarcinoom is een kwaadaardige tumor van klierepitheel, zoals in darm, borst, prostaat, long en pancreas.","definition":"<p>Een <strong>adenocarcinoom</strong> vormt (verwaarloosde) klierstructuren of maakt slijm. Het is de meest voorkomende vorm van kanker van colon, maag, pancreas, prostaat, borst en een groot deel van het longcarcinoom. De mate van differentiatie (graad) en het stadium bepalen de prognose.</p>","image_url":"","wiki_title":"Adenocarcinoma","match":"adenocarcinoom|adenocarcinomen","option_only":true},"anorexie":{"title":"Anorexie (verminderde eetlust)","short":"Anorexie betekent als symptoom verminderde of afwezige eetlust; het is iets anders dan de eetstoornis anorexia nervosa.","definition":"<p>Als symptoom is <strong>anorexie</strong> een aspecifiek teken van ziekte, bijvoorbeeld bij infecties, ontsteking (cytokines), maligniteiten, leverziekte, nierfalen, depressie en als bijwerking van medicatie. Bij acute buikpathologie, zoals appendicitis, is verminderde eetlust een veelvoorkomend begeleidend symptoom.</p>","image_url":"","wiki_title":"Anorexia (symptom)","match":"anorexie|eetlustverlies|verminderde eetlust","option_only":true},"bse":{"title":"Bezinkingssnelheid (BSE)","short":"De BSE meet hoe snel rode bloedcellen in een buisje uitzakken; een verhoogde waarde wijst op ontsteking, maar is weinig specifiek.","definition":"<p>De <strong>bezinkingssnelheid</strong> stijgt doordat acutefase-eiwitten (vooral fibrinogeen) en immunoglobulinen de rode bloedcellen in rouleaux laten samenklonteren. Ze stijgt en daalt trager dan het CRP. Sterk verhoogde waarden passen bij o.a. reuscelarteriitis, polymyalgia reumatica, multipel myeloom en ernstige infecties. Leeftijd, geslacht en anemie beïnvloeden de waarde.</p>","image_url":"","wiki_title":"Erythrocyte sedimentation rate","match":"bse|bezinking|bezinkingssnelheid|erytrocytenbezinking","option_only":true},"lig. gastrocolicum":{"title":"Ligamentum gastrocolicum","short":"Het ligamentum gastrocolicum is het deel van het grote omentum tussen de grote curvatuur van de maag en het colon transversum.","definition":"<p>Het <strong>ligamentum gastrocolicum</strong> maakt deel uit van het omentum majus. Het vormt een deel van de voorwand van de bursa omentalis; door het te openen krijgt de chirurg toegang tot de achterkant van de maag en de pancreas. In het ligament lopen de aa. gastro-omentales.</p>","image_url":"","wiki_title":"Gastrocolic ligament","match":"lig. gastrocolicum|ligamentum gastrocolicum","option_only":true},"lig. teres hepatis":{"title":"Ligamentum teres hepatis","short":"Het ligamentum teres hepatis is het bindweefselrestant van de navelvene, in de onderrand van het ligamentum falciforme.","definition":"<p>In de foetale circulatie voert de v. umbilicalis zuurstofrijk bloed van de placenta naar de lever en via de ductus venosus naar de v. cava inferior. Na de geboorte verbindweefselt de navelvene tot het <strong>ligamentum teres hepatis</strong>. Bij portale hypertensie kan het restlumen weer opengaan, met verwijde venen rond de navel (caput medusae).</p>","image_url":"","wiki_title":"Round ligament of liver","match":"lig. teres hepatis|ligamentum teres hepatis|ronde leverband","option_only":true},"tachycardie":{"title":"Tachycardie","short":"Tachycardie is een snelle hartslag, bij volwassenen boven 100 slagen per minuut.","definition":"<p>Een <strong>sinustachycardie</strong> is een fysiologische reactie op o.a. inspanning, koorts, pijn, angst, hypovolemie, anemie, hypoxie en hyperthyreoïdie. Pathologische tachycardieën zijn o.a. boezemfibrilleren, AVNRT en ventrikeltachycardie. Het ECG maakt het onderscheid.</p>","image_url":"","wiki_title":"Tachycardia","match":"tachycardie|sinustachycardie","option_only":true},"perifeer oedeem":{"title":"Perifeer oedeem","short":"Perifeer oedeem is vochtophoping in de benen en voeten, vaak putjes achterlatend bij indrukken.","definition":"<p><strong>Perifeer oedeem</strong> ontstaat door een verhoogde veneuze druk (rechtszijdig hartfalen, veneuze insufficiëntie, trombose), een laag albumine (nefrotisch syndroom, cirrose, ondervoeding), medicatie (calciumantagonisten, NSAID's) of lymfoedeem. Eenzijdig oedeem past vaker bij een lokale oorzaak, zoals trombose of cellulitis.</p>","image_url":"","wiki_title":"Edema","match":"perifeer oedeem|enkeloedeem","option_only":true},"zoutzuur":{"title":"Zoutzuur (maagzuur)","short":"Zoutzuur wordt door de pariëtale cellen van de maag uitgescheiden; het maakt de maaginhoud zuur, doodt micro-organismen en activeert pepsine.","definition":"<p>De pariëtale cellen pompen H⁺ via de H⁺/K⁺-ATPase het maaglumen in; chloride volgt. Stimulatoren zijn gastrine, histamine (H2) en acetylcholine (vagus); somatostatine remt. Het lage pH (1–2) helpt bij eiwitvertering en ijzeropname en beschermt tegen infecties. Protonpompremmers en H2-antagonisten verminderen de productie.</p>","image_url":"","wiki_title":"Gastric acid","match":"zoutzuur|hcl|maagzuur","option_only":true},"vagotomie":{"title":"Vagotomie","short":"Bij een vagotomie worden (takken van) de n. vagus doorgesneden om de maagzuursecretie te verminderen.","definition":"<p>Een <strong>vagotomie</strong> werd vroeger veel gedaan bij ulcuslijden. Omdat de vagus ook de maagontlediging stimuleert, werd een trunculaire vagotomie vaak gecombineerd met een pyloroplastiek. Sinds protonpompremmers en H. pylori-eradicatie wordt het nauwelijks meer toegepast.</p>","image_url":"","wiki_title":"Vagotomy","match":"vagotomie","option_only":true},"bisacodyl":{"title":"Bisacodyl","short":"Bisacodyl is een prikkelend (contactlaxans) laxeermiddel dat de darmperistaltiek stimuleert.","definition":"<p><strong>Bisacodyl</strong> stimuleert de zenuwen in de darmwand en vermindert de wateropname in het colon. Het werkt na 6–12 uur (oraal) of na 15–60 minuten (zetpil). Het wordt gebruikt bij obstipatie, ook bij opioïdgebruik, en voor darmvoorbereiding. Bijwerkingen zijn buikkrampen en bij langdurig hoog gebruik elektrolytverlies.</p>","image_url":"","wiki_title":"Bisacodyl","match":"bisacodyl|dulcolax","option_only":true},"ct scan":{"title":"CT-scan","short":"Een CT-scan maakt met röntgenstraling dwarsdoorsneden van het lichaam.","definition":"<p>Bij <strong>computertomografie</strong> draait een röntgenbuis rond de patiënt en wordt een driedimensionaal beeld berekend. CT is snel en zeer geschikt voor trauma, bloedingen in het hoofd, longen, buik en bot; met contrast ook voor vaten. Nadelen zijn de stralingsbelasting en het contrastmiddel (nierfunctie, allergie).</p>","image_url":"","wiki_title":"CT scan","match":"ct scan|ct-scan|computertomografie","option_only":true},"voordarm":{"title":"Voordarm (foregut)","short":"De voordarm is het craniale deel van de embryonale darmbuis, waaruit o.a. slokdarm, maag, lever, pancreas en een deel van het duodenum ontstaan.","definition":"<p>Uit de <strong>voordarm</strong> ontstaan de farynx, de onderste luchtwegen (longknop), oesophagus, maag, het proximale duodenum, lever, galblaas en pancreas. Hij wordt doorbloed door de truncus coeliacus. Pijn uit voordarmorganen wordt in het epigastrium gevoeld.</p>","image_url":"","wiki_title":"Foregut","match":"voordarm|foregut","option_only":true},"niet-steroïdale anti-inflammatoire drugs (nsaids)":{"title":"NSAID's","short":"NSAID's remmen cyclo-oxygenase en daarmee de vorming van prostaglandinen; ze werken pijnstillend, koortsverlagend en ontstekingsremmend.","definition":"<p><strong>NSAID's</strong> (zoals ibuprofen, naproxen, diclofenac) remmen COX-1 en COX-2. Door remming van beschermende prostaglandinen kunnen ze maagulcera en bloedingen geven, vooral bij ouderen; ook kunnen ze de nierfunctie verslechteren, de bloeddruk verhogen, hartfalen verergeren en het risico op hart- en vaatziekten iets verhogen. Selectieve COX-2-remmers geven minder maagschade.</p>","image_url":"","wiki_title":"Nonsteroidal anti-inflammatory drug","match":"niet-steroïdale anti-inflammatoire drugs (nsaids)","option_only":true},"nsaid’s":{"title":"NSAID's","short":"NSAID's remmen cyclo-oxygenase en daarmee de vorming van prostaglandinen; ze werken pijnstillend, koortsverlagend en ontstekingsremmend.","definition":"<p><strong>NSAID's</strong> (zoals ibuprofen, naproxen, diclofenac) remmen COX-1 en COX-2. Door remming van beschermende prostaglandinen kunnen ze maagulcera en bloedingen geven, vooral bij ouderen; ook kunnen ze de nierfunctie verslechteren, de bloeddruk verhogen, hartfalen verergeren en het risico op hart- en vaatziekten iets verhogen. Selectieve COX-2-remmers geven minder maagschade.</p>","image_url":"","wiki_title":"Nonsteroidal anti-inflammatory drug","match":"nsaid’s","option_only":true},"lobaire pneumonie, veroorzaakt door pneumokokken":{"title":"Pneumonie","short":"Een pneumonie is een infectie van het longweefsel (alveoli), meestal door bacteriën of virussen, met koorts, hoesten en kortademigheid.","definition":"<p>Bij een <strong>pneumonie</strong> (longontsteking) raken de alveoli ontstoken en vullen ze zich met ontstekingsvocht en cellen. Daardoor is minder longoppervlak beschikbaar voor gaswisseling.</p><p>Typische klachten zijn koorts, hoesten (vaak met sputum), kortademigheid en soms pijn bij het ademen. Bij lichamelijk onderzoek kunnen crepitaties of een gedempte percussie optreden; een X-thorax toont een infiltraat. De meest voorkomende verwekker van de buiten het ziekenhuis opgelopen pneumonie is <em>Streptococcus pneumoniae</em>.</p>","image_url":"","wiki_title":"Pneumonia","match":"lobaire pneumonie, veroorzaakt door pneumokokken","option_only":true},"overmatig alcoholgebruik":{"title":"Alcohol (ethanol)","short":"Ethanol wordt in de lever afgebroken via acetaldehyde tot azijnzuur; overmatig gebruik schaadt lever, brein, hart en pancreas.","definition":"<p><strong>Ethanol</strong> wordt vooral in de lever geoxideerd door <em>alcoholdehydrogenase</em> tot acetaldehyde en daarna door aldehydedehydrogenase tot acetaat. Hierbij ontstaat veel NADH, wat de gluconeogenese remt (hypoglykemie) en vetstapeling in de lever bevordert.</p><p>Chronisch overmatig gebruik geeft leververvetting, alcoholische hepatitis en cirrose, pancreatitis, cardiomyopathie, hypertensie, neuropathie, thiaminetekort (Wernicke-Korsakov) en een verhoogd risico op verschillende kankers.</p>","image_url":"","wiki_title":"Alcohol (drug)","match":"overmatig alcoholgebruik","option_only":true},"hoge koorts":{"title":"Koorts","short":"Koorts is een verhoogde lichaamstemperatuur (≥38,0 °C) doordat de hypothalamus het setpoint hoger instelt, meestal als reactie op infectie.","definition":"<p>Bij <strong>koorts</strong> wordt het temperatuursetpoint in de hypothalamus verhoogd. Pyrogenen zoals bacteriële producten en cytokines (IL-1, IL-6, TNF) stimuleren daar de productie van prostaglandine E<sub>2</sub>.</p><p>Het lichaam ervaart de normale temperatuur dan als te koud: vasoconstrictie en rillingen verhogen de temperatuur. Als het setpoint weer daalt, volgen zweten en vasodilatatie. Koortsremmers (paracetamol, NSAID's) remmen de prostaglandinesynthese. Hyperthermie (bijv. hitteberoerte) is iets anders: daar is het setpoint níet verhoogd.</p>","image_url":"","wiki_title":"Fever","match":"hoge koorts","option_only":true},"stembandknobbeltjes":{"title":"Stembandknobbeltjes","short":"Stembandknobbeltjes zijn kleine, symmetrische verdikkingen op de stembanden door overbelasting van de stem.","definition":"<p><strong>Stembandknobbeltjes</strong> zitten op de vrije rand van beide stembanden, op de overgang van het voorste naar het middelste derde. Ze ontstaan door langdurige stembelasting (schreeuwen, zingen) en geven heesheid en een snel vermoeide stem. Behandeling is in eerste instantie logopedie.</p>","image_url":"","wiki_title":"Vocal fold nodule","match":"stembandknobbeltjes|noduli van de stembanden","option_only":true},"lactose-intolerantie":{"title":"Lactose-intolerantie","short":"Bij lactose-intolerantie is er te weinig lactase in de dunne darm, waardoor melksuiker in de dikke darm wordt gefermenteerd.","definition":"<p>Bij <strong>lactose-intolerantie</strong> geeft melk een opgeblazen gevoel, winderigheid, buikkrampen en osmotische diarree. De primaire vorm (afnemende lactase na de kindertijd) komt wereldwijd bij de meerderheid van de volwassenen voor; secundaire vormen ontstaan bij darmschade (bijv. coeliakie, gastro-enteritis). Diagnose met een waterstofademtest of eliminatie.</p>","image_url":"","wiki_title":"Lactose intolerance","match":"lactose-intolerantie|lactoseintolerantie|lactasedeficiëntie|lactase deficiëntie","option_only":true},"hartfalen":{"title":"Hartfalen","short":"Bij hartfalen kan het hart onvoldoende bloed rondpompen voor de behoefte van het lichaam, met kortademigheid, vermoeidheid en vochtophoping.","definition":"<p><strong>Hartfalen</strong> wordt ingedeeld naar ejectiefractie (verminderd, licht verminderd, behouden). Oorzaken zijn o.a. ischemie, hypertensie, klepziekten en cardiomyopathieën. Klachten: inspanningsdyspneu, orthopneu, oedeem, gewichtstoename. Diagnose met NT-proBNP en echocardiografie. Behandeling bij verminderde EF: ACE-remmer/ARNI, bètablokker, MRA, SGLT2-remmer en diuretica bij overvulling.</p>","image_url":"","wiki_title":"Heart failure","match":"hartfalen|decompensatio cordis|hartinsufficiëntie","option_only":true},"peptiderge hormonen":{"title":"Peptidehormonen","short":"Peptidehormonen zijn hormonen opgebouwd uit aminozuurketens; ze binden aan receptoren op het celmembraan.","definition":"<p><strong>Peptidehormonen</strong> (bijv. insuline, glucagon, ADH, PTH, groeihormoon) zijn wateroplosbaar, worden opgeslagen in blaasjes en bij een prikkel afgegeven. Ze werken via membraanreceptoren en tweede boodschappers. Steroïd- en schildklierhormonen werken daarentegen via intracellulaire receptoren op de gentranscriptie.</p>","image_url":"","wiki_title":"Peptide hormone","match":"peptiderge hormonen|peptidehormonen","option_only":true},"troponine t":{"title":"Troponine","short":"Troponine is een eiwit uit de hartspier; een stijging in het bloed wijst op schade aan hartspiercellen.","definition":"<p><strong>Cardiaal troponine</strong> (T of I) komt vrij bij beschadiging van myocyten. Het is de belangrijkste marker voor een myocardinfarct: het stijgt binnen enkele uren en blijft dagen verhoogd. Ook bij myocarditis, longembolie, hartfalen, sepsis, nierfalen en na zware inspanning kan het stijgen. Met hooggevoelige tests wordt naar de verandering in de tijd gekeken.</p>","image_url":"","wiki_title":"Troponin","match":"troponine t|troponine|troponine i|hs-troponine","option_only":true},"diffusiestoornis":{"title":"Diffusiestoornis","short":"Bij een diffusiestoornis gaat zuurstof minder goed van de alveoli naar het bloed, door verdikking van de membraan of verlies van oppervlak.","definition":"<p>Een <strong>diffusiestoornis</strong> wordt gemeten met de DLCO (koolmonoxide-diffusiecapaciteit). Ze komt voor bij interstitiële longziekten (verdikte alveolaire wand), emfyseem (verlies van oppervlak), pulmonale hypertensie en anemie. De hypoxemie wordt vaak pas duidelijk bij inspanning, omdat het bloed dan korter in de capillair verblijft.</p>","image_url":"","wiki_title":"Diffusing capacity for carbon monoxide","match":"diffusiestoornis|diffusiebeperking|verminderde diffusiecapaciteit","option_only":true},"urachus":{"title":"Urachus","short":"De urachus is de embryonale verbinding tussen blaas en navel (restant van de allantois), die normaal verbindweefselt.","definition":"<p>Na de geboorte wordt de <strong>urachus</strong> een bindweefselstreng (lig. umbilicale medianum). Blijft hij (deels) open, dan kunnen een urachusfistel (urine uit de navel), een cyste of een sinus ontstaan, met risico op infectie en zelden een carcinoom.</p>","image_url":"","wiki_title":"Urachus","match":"urachus","option_only":true},"pericardium":{"title":"Pericard (hartzakje)","short":"Het pericard is het hartzakje: een fibreuze buitenlaag met een sereus dubbelblad, met daartussen een laagje vocht.","definition":"<p>Het <strong>pericard</strong> bestaat uit het fibreuze pericard en het sereuze pericard (pariëtaal en visceraal blad, het epicard). Het fixeert het hart, beperkt overmatige vulling en vermindert wrijving. Ontsteking heet pericarditis; snelle vochtophoping kan een harttamponnade geven, chronische verdikking een constrictieve pericarditis.</p>","image_url":"","wiki_title":"Pericardium","match":"pericardium|pericard|hartzakje","option_only":true},"tromboembolie":{"title":"Longembolie","short":"Bij een longembolie sluit een stolsel (meestal uit de beenvenen) een longslagader af, met acute benauwdheid en pijn bij het ademen.","definition":"<p>Een <strong>longembolie</strong> ontstaat meestal door een trombus uit de diepe venen van been of bekken. Risicofactoren volgen de trias van Virchow: stase (immobilisatie), hypercoagulabiliteit (kanker, oestrogenen, zwangerschap, erfelijke trombofilie) en vaatwandschade (operatie, trauma). Klachten: plotselinge dyspneu, pleuritische pijn, tachycardie, soms hemoptoë of collaps. Diagnostiek met een beslisregel, D-dimeer en CT-angiografie; behandeling met antistolling.</p>","image_url":"","wiki_title":"Pulmonary embolism","match":"tromboembolie","option_only":true},"trombo-embolie":{"title":"Longembolie","short":"Bij een longembolie sluit een stolsel (meestal uit de beenvenen) een longslagader af, met acute benauwdheid en pijn bij het ademen.","definition":"<p>Een <strong>longembolie</strong> ontstaat meestal door een trombus uit de diepe venen van been of bekken. Risicofactoren volgen de trias van Virchow: stase (immobilisatie), hypercoagulabiliteit (kanker, oestrogenen, zwangerschap, erfelijke trombofilie) en vaatwandschade (operatie, trauma). Klachten: plotselinge dyspneu, pleuritische pijn, tachycardie, soms hemoptoë of collaps. Diagnostiek met een beslisregel, D-dimeer en CT-angiografie; behandeling met antistolling.</p>","image_url":"","wiki_title":"Pulmonary embolism","match":"trombo-embolie","option_only":true},"diclofenac (nsaid)":{"title":"NSAID's","short":"NSAID's remmen cyclo-oxygenase en daarmee de vorming van prostaglandinen; ze werken pijnstillend, koortsverlagend en ontstekingsremmend.","definition":"<p><strong>NSAID's</strong> (zoals ibuprofen, naproxen, diclofenac) remmen COX-1 en COX-2. Door remming van beschermende prostaglandinen kunnen ze maagulcera en bloedingen geven, vooral bij ouderen; ook kunnen ze de nierfunctie verslechteren, de bloeddruk verhogen, hartfalen verergeren en het risico op hart- en vaatziekten iets verhogen. Selectieve COX-2-remmers geven minder maagschade.</p>","image_url":"","wiki_title":"Nonsteroidal anti-inflammatory drug","match":"diclofenac (nsaid)","option_only":true},"diclofenac":{"title":"NSAID's","short":"NSAID's remmen cyclo-oxygenase en daarmee de vorming van prostaglandinen; ze werken pijnstillend, koortsverlagend en ontstekingsremmend.","definition":"<p><strong>NSAID's</strong> (zoals ibuprofen, naproxen, diclofenac) remmen COX-1 en COX-2. Door remming van beschermende prostaglandinen kunnen ze maagulcera en bloedingen geven, vooral bij ouderen; ook kunnen ze de nierfunctie verslechteren, de bloeddruk verhogen, hartfalen verergeren en het risico op hart- en vaatziekten iets verhogen. Selectieve COX-2-remmers geven minder maagschade.</p>","image_url":"","wiki_title":"Nonsteroidal anti-inflammatory drug","match":"diclofenac","option_only":true},"ibuprofen":{"title":"NSAID's","short":"NSAID's remmen cyclo-oxygenase en daarmee de vorming van prostaglandinen; ze werken pijnstillend, koortsverlagend en ontstekingsremmend.","definition":"<p><strong>NSAID's</strong> (zoals ibuprofen, naproxen, diclofenac) remmen COX-1 en COX-2. Door remming van beschermende prostaglandinen kunnen ze maagulcera en bloedingen geven, vooral bij ouderen; ook kunnen ze de nierfunctie verslechteren, de bloeddruk verhogen, hartfalen verergeren en het risico op hart- en vaatziekten iets verhogen. Selectieve COX-2-remmers geven minder maagschade.</p>","image_url":"","wiki_title":"Nonsteroidal anti-inflammatory drug","match":"ibuprofen","option_only":true},"colon sigmoideum":{"title":"Colon sigmoideum","short":"Het colon sigmoideum is het S-vormige deel van de dikke darm tussen colon descendens en rectum.","definition":"<p>Het <strong>sigmoïd</strong> heeft een eigen mesenterium en is daardoor beweeglijk, wat een volvulus mogelijk maakt. Het is de meest voorkomende plaats van divertikels en diverticulitis en een veelvoorkomende plaats voor coloncarcinoom.</p>","image_url":"","wiki_title":"Sigmoid colon","match":"colon sigmoideum|sigmoïd|sigmoid","option_only":true},"oesophagusmanometrie":{"title":"Slokdarmmanometrie","short":"Bij slokdarmmanometrie worden drukken in de slokdarm gemeten om motiliteitsstoornissen op te sporen.","definition":"<p>Met <strong>(hoge-resolutie)manometrie</strong> worden de peristaltiek en de ontspanning van de onderste slokdarmsfincter beoordeeld. Het is het belangrijkste onderzoek bij achalasie (geen peristaltiek, onvoldoende sfincterontspanning) en slokdarmspasmen.</p>","image_url":"","wiki_title":"Esophageal motility study","match":"oesophagusmanometrie|slokdarmmanometrie","option_only":true},"epiglottis":{"title":"Epiglottis","short":"De epiglottis is het kraakbenige klepje dat bij het slikken de ingang van het strottenhoofd afdekt.","definition":"<p>De <strong>epiglottis</strong> bestaat uit elastisch kraakbeen. Bij het slikken komt de larynx omhoog en klapt de epiglottis naar achteren, zodat voedsel naar de slokdarm gaat. Ontsteking ervan (epiglottitis) kan levensbedreigend zijn.</p>","image_url":"","wiki_title":"Epiglottis","match":"epiglottis|strotklepje","option_only":true},"cholera":{"title":"Cholera","short":"Cholera is een darminfectie met Vibrio cholerae die door een toxine enorme waterige diarree (‘rijstwaterdiarree’) veroorzaakt.","definition":"<p>Het <strong>choleratoxine</strong> activeert adenylaatcyclase in darmcellen, waardoor chloride en water massaal de darm in gaan. Zonder vochtaanvulling ontstaat binnen uren ernstige uitdroging. Orale rehydratie (ORS) of intraveneus vocht is levensreddend; antibiotica verkorten de ziekte.</p>","image_url":"","wiki_title":"Cholera","match":"cholera|vibrio cholerae","option_only":true},"lipase":{"title":"Lipase","short":"Lipase is een pancreasenzym dat triglyceriden afbreekt; een sterk verhoogd serumlipase past bij acute pancreatitis.","definition":"<p><strong>Pancreaslipase</strong> splitst vetten in vrije vetzuren en monoglyceriden, met galzouten en colipase als hulp. In het bloed is een stijging van meer dan drie keer de bovengrens, bij passende pijn, een criterium voor acute pancreatitis. Lipaseremmers (orlistat) verminderen vetopname.</p>","image_url":"","wiki_title":"Lipase","match":"lipase|pancreaslipase","option_only":true},"beenvarices":{"title":"Varices (spataderen)","short":"Varices zijn verwijde, kronkelige oppervlakkige venen in de benen, door lekkende kleppen.","definition":"<p><strong>Spataderen</strong> komen veel voor, vaker bij vrouwen, met familiaire aanleg, zwangerschap, overgewicht en staand werk als risicofactoren. Klachten: zware, moeë benen, jeuk en oedeem; complicaties zijn tromboflebitis, bloedingen, huidveranderingen en een ulcus cruris. Behandeling: compressie, sclerotherapie, endoveneuze ablatie.</p>","image_url":"","wiki_title":"Varicose veins","match":"beenvarices|varices|spataderen","option_only":true},"inflammatoire darmziekte":{"title":"Inflammatoire darmziekten (IBD)","short":"IBD is de verzamelnaam voor chronische ontstekingsziekten van de darm: de ziekte van Crohn en colitis ulcerosa.","definition":"<p>Bij <strong>IBD</strong> ontstaat een ontregelde afweerreactie tegen de darmflora bij genetisch gevoelige mensen. Klachten: diarree, buikpijn, bloedverlies, gewichtsverlies en extra-intestinale verschijnselen (gewrichten, ogen, huid, galwegen). Calprotectine in de ontlasting helpt IBD te onderscheiden van prikkelbaredarmsyndroom.</p>","image_url":"","wiki_title":"Inflammatory bowel disease","match":"inflammatoire darmziekte|inflammatoire darmziekten|ibd","option_only":true},"meckel's divertikel":{"title":"Divertikel van Meckel","short":"Het divertikel van Meckel is een restant van de ductus omphaloentericus aan het ileum; het kan bloeden, ontsteken of een obstructie veroorzaken.","definition":"<p>De ‘regel van 2’: komt bij ongeveer 2% van de mensen voor, ligt ongeveer 60 cm (2 voet) van de ileocaecaalklep, is ongeveer 5 cm lang en geeft vaak klachten vóór het 2e jaar. Het kan maagslijmvlies bevatten, met ulceratie en pijnloos rectaal bloedverlies, of als leidpunt voor invaginatie dienen.</p>","image_url":"","wiki_title":"Meckel's diverticulum","match":"meckel's divertikel|divertikel van meckel|meckel divertikel","option_only":true},"anus atresie":{"title":"Anusatresie","short":"Bij anusatresie is de anus bij de geboorte niet of op een verkeerde plek aangelegd, vaak met een fistel.","definition":"<p><strong>Anorectale malformaties</strong> ontstaan door een stoornis in de verdeling van de cloaca. Er kan een fistel naar het perineum, de urethra of de vagina zijn. Ze gaan vaak samen met andere afwijkingen (VACTERL-associatie). Behandeling is chirurgisch.</p>","image_url":"","wiki_title":"Imperforate anus","match":"anus atresie|anus-atresie|anorectale malformatie","option_only":true},"geconjugeerd bilirubine":{"title":"Geconjugeerd bilirubine","short":"Geconjugeerd bilirubine is het in de lever aan glucuronzuur gekoppelde, in water oplosbare bilirubine dat via de gal wordt uitgescheiden.","definition":"<p>Een verhoogd <strong>geconjugeerd bilirubine</strong> past bij leverziekte of galwegobstructie. Omdat het in water oplosbaar is, komt het in de urine (donkere urine). Bij pasgeborenen is een verhoogd geconjugeerd bilirubine altijd afwijkend en vraagt het om onderzoek naar bijv. galgangatresie.</p>","image_url":"","wiki_title":"Bilirubin","match":"geconjugeerd bilirubine|direct bilirubine","option_only":true},"trypsine":{"title":"Trypsine","short":"Trypsine is een eiwitsplitsend enzym van de pancreas; het wordt in de darm geactiveerd en activeert de andere pancreasenzymen.","definition":"<p>Het inactieve <strong>trypsinogeen</strong> wordt in het duodenum door enteropeptidase omgezet in trypsine, dat vervolgens andere pro-enzymen (chymotrypsinogeen, procarboxypeptidase, profosfolipase) activeert. Voortijdige activatie in de pancreas zelf speelt een rol bij acute pancreatitis.</p>","image_url":"","wiki_title":"Trypsin","match":"trypsine|trypsinogeen","option_only":true},"cck":{"title":"Cholecystokinine (CCK)","short":"Cholecystokinine is een hormoon uit het duodenum dat de galblaas laat samentrekken en de afgifte van pancreasenzymen stimuleert.","definition":"<p><strong>CCK</strong> wordt door I-cellen afgegeven als reactie op vetten en eiwitten. Het laat de galblaas samentrekken, ontspant de sfincter van Oddi, stimuleert de pancreasenzymen, vertraagt de maaglediging en geeft een verzadigd gevoel.</p>","image_url":"","wiki_title":"Cholecystokinin","match":"cck|cholecystokinine","option_only":true},"norepinephrine":{"title":"Noradrenaline (norepinefrine)","short":"Noradrenaline is de neurotransmitter van de postganglionaire sympathische vezels en een vaatvernauwend middel bij shock.","definition":"<p><strong>Noradrenaline</strong> werkt vooral op α1-receptoren (vasoconstrictie) en β1-receptoren. Centraal komt het uit de locus coeruleus (alertheid, stemming). Als geneesmiddel is het de vasopressor van eerste keus bij septische shock.</p>","image_url":"","wiki_title":"Norepinephrine","match":"norepinephrine|noradrenaline|norepinefrine","option_only":true},"kortademigheid":{"title":"Dyspneu (kortademigheid)","short":"Dyspneu is het subjectieve gevoel van moeilijk of onvoldoende kunnen ademen.","definition":"<p><strong>Kortademigheid</strong> kan een pulmonale oorzaak hebben (astma, COPD, pneumonie, longembolie, pneumothorax), een cardiale (hartfalen, ischemie, ritmestoornissen), of samenhangen met anemie, obesitas, conditieverlies, angst of metabole acidose. Het tijdsbeloop (acuut of chronisch) en bijkomende klachten sturen de diagnostiek.</p>","image_url":"","wiki_title":"Shortness of breath","match":"kortademigheid|dyspneu|dyspnoe|benauwdheid","option_only":true},"tachypneu":{"title":"Tachypneu","short":"Tachypneu is een te snelle ademhaling, bij volwassenen meer dan ongeveer 20 per minuut.","definition":"<p><strong>Tachypneu</strong> komt voor bij koorts, pijn, angst, longaandoeningen, hartfalen, sepsis en metabole acidose (compenserend). Een verhoogde ademfrequentie is een belangrijk alarmsignaal in vroege-waarschuwingsscores. Bij kinderen gelden leeftijdsafhankelijke grenzen.</p>","image_url":"","wiki_title":"Tachypnea","match":"tachypneu|tachypnoe|snelle ademhaling","option_only":true},"tachycardie (hoge hartfrequentie)":{"title":"Tachycardie","short":"Tachycardie is een snelle hartslag, bij volwassenen boven 100 slagen per minuut.","definition":"<p>Een <strong>sinustachycardie</strong> is een fysiologische reactie op o.a. inspanning, koorts, pijn, angst, hypovolemie, anemie, hypoxie en hyperthyreoïdie. Pathologische tachycardieën zijn o.a. boezemfibrilleren, AVNRT en ventrikeltachycardie. Het ECG maakt het onderscheid.</p>","image_url":"","wiki_title":"Tachycardia","match":"tachycardie (hoge hartfrequentie)","option_only":true},"s. aureus":{"title":"Staphylococcus aureus","short":"S. aureus is een grampositieve kok in trosjes, coagulasepositief, die huid- en wondinfecties, abcessen en ernstige systemische infecties veroorzaakt.","definition":"<p><strong><em>Staphylococcus aureus</em></strong> is een grampositieve kok die in trosjes groeit en <em>coagulase-positief</em> is (onderscheid met andere stafylokokken). Ongeveer een derde van de mensen draagt hem in de neus.</p><p>Hij veroorzaakt huid- en wekedeleninfecties (impetigo, furunkels, abcessen, wondinfecties), maar ook osteomyelitis, septische artritis, endocarditis en sepsis. Via toxines kan hij voedselvergiftiging en het toxischeshocksyndroom veroorzaken. MRSA is een methicillineresistente variant.</p>","image_url":"","wiki_title":"Staphylococcus aureus","match":"s. aureus","option_only":true},"klebsiella spp":{"title":"Klebsiella pneumoniae","short":"K. pneumoniae is een gramnegatieve staaf met een dik kapsel die urineweginfecties en (ziekenhuis)pneumonie veroorzaakt.","definition":"<p><strong><em>Klebsiella pneumoniae</em></strong> is een gramnegatieve staaf uit de <em>Enterobacteriaceae</em> met een dik polysacharidekapsel, waardoor kolonies slijmerig zijn.</p><p>Hij veroorzaakt urineweginfecties, sepsis en pneumonie, vooral bij ouderen, alcoholisten en patiënten met diabetes of in het ziekenhuis. Klebsiella is berucht om antibioticaresistentie (ESBL- en carbapenemaseproducerende stammen).</p>","image_url":"","wiki_title":"Klebsiella pneumoniae","match":"klebsiella spp","option_only":true},"diclofenac (een nsaid)":{"title":"NSAID's","short":"NSAID's remmen cyclo-oxygenase en daarmee de vorming van prostaglandinen; ze werken pijnstillend, koortsverlagend en ontstekingsremmend.","definition":"<p><strong>NSAID's</strong> (zoals ibuprofen, naproxen, diclofenac) remmen COX-1 en COX-2. Door remming van beschermende prostaglandinen kunnen ze maagulcera en bloedingen geven, vooral bij ouderen; ook kunnen ze de nierfunctie verslechteren, de bloeddruk verhogen, hartfalen verergeren en het risico op hart- en vaatziekten iets verhogen. Selectieve COX-2-remmers geven minder maagschade.</p>","image_url":"","wiki_title":"Nonsteroidal anti-inflammatory drug","match":"diclofenac (een nsaid)","option_only":true},"sigmoïd":{"title":"Colon sigmoideum","short":"Het colon sigmoideum is het S-vormige deel van de dikke darm tussen colon descendens en rectum.","definition":"<p>Het <strong>sigmoïd</strong> heeft een eigen mesenterium en is daardoor beweeglijk, wat een volvulus mogelijk maakt. Het is de meest voorkomende plaats van divertikels en diverticulitis en een veelvoorkomende plaats voor coloncarcinoom.</p>","image_url":"","wiki_title":"Sigmoid colon","match":"sigmoïd","option_only":true},"ct thorax-abdomen":{"title":"CT abdomen","short":"Een CT abdomen is een röntgenscan in dwarsdoorsneden van de buik, vaak met contrast; goed voor acute buik, tumoren, abcessen en trauma.","definition":"<p>Bij een <strong>CT abdomen</strong> worden met röntgenstraling dunne dwarsdoorsneden van de buik gemaakt, meestal met intraveneus (en soms oraal) contrast.</p><p>Het geeft een overzichtelijk beeld van alle buikorganen, de darm en het retroperitoneum en wordt gebruikt bij een acute buik (bijv. perforatie, diverticulitis, appendicitis bij volwassenen), bij het stadiëren van tumoren, het opsporen van abcessen en bij trauma. Nadelen zijn de stralingsbelasting en het contrastmiddel (nierfunctie, allergie).</p>","image_url":"","wiki_title":"CT scan","match":"ct thorax-abdomen","option_only":true},"ct-abdomen met oraal contrast":{"title":"CT abdomen","short":"Een CT abdomen is een röntgenscan in dwarsdoorsneden van de buik, vaak met contrast; goed voor acute buik, tumoren, abcessen en trauma.","definition":"<p>Bij een <strong>CT abdomen</strong> worden met röntgenstraling dunne dwarsdoorsneden van de buik gemaakt, meestal met intraveneus (en soms oraal) contrast.</p><p>Het geeft een overzichtelijk beeld van alle buikorganen, de darm en het retroperitoneum en wordt gebruikt bij een acute buik (bijv. perforatie, diverticulitis, appendicitis bij volwassenen), bij het stadiëren van tumoren, het opsporen van abcessen en bij trauma. Nadelen zijn de stralingsbelasting en het contrastmiddel (nierfunctie, allergie).</p>","image_url":"","wiki_title":"CT scan","match":"ct-abdomen met oraal contrast","option_only":true},"echo van de lever":{"title":"Echo abdomen","short":"Een echo abdomen is een echografisch onderzoek van de buikorganen; zonder straling en goed voor galblaas, galwegen, lever, nieren en vrij vocht.","definition":"<p>Bij een <strong>echo abdomen</strong> wordt met geluidsgolven een beeld gemaakt van de buikorganen. Het onderzoek gebruikt geen ioniserende straling, is goedkoop en direct beschikbaar.</p><p>Het is bijzonder geschikt voor het aantonen van galstenen en cholecystitis, verwijde galwegen, leverafwijkingen, nierstuwing (hydronefrose), een abdominaal aorta-aneurysma en vrij vocht. Darmgas en een dikke buikwand beperken het zicht; de kwaliteit hangt af van de onderzoeker.</p>","image_url":"","wiki_title":"Abdominal ultrasonography","match":"echo van de lever","option_only":true},"a. mesenterica superior":{"title":"A. mesenterica superior","short":"De a. mesenterica superior voorziet de dunne darm en het proximale colon van bloed.","definition":"<p>De <strong>a. mesenterica superior</strong> ontspringt ter hoogte van L1 uit de aorta, achter de pancreas, en loopt vóór het duodenum. Takken: aa. jejunales en ileales, a. ileocolica, a. colica dextra en media. Een acute afsluiting (embolie) geeft mesenteriale ischemie met hevige buikpijn bij weinig afwijkingen aan de buik.</p>","image_url":"","wiki_title":"Superior mesenteric artery","match":"a. mesenterica superior|arteria mesenterica superior","option_only":true},"barium slikfoto":{"title":"Slikfoto (bariumslik)","short":"Bij een slikfoto drinkt de patiënt contrastvloeistof terwijl röntgenopnamen worden gemaakt van slokdarm en maag.","definition":"<p>Een <strong>bariumslikfoto</strong> laat de vorm en passage van de slokdarm zien, bijvoorbeeld bij achalasie (vogelbekvorm), vernauwingen, een divertikel van Zenker of slokdarmspasmen (kurkentrekker). Bij verdenking op een perforatie wordt een wateroplosbaar contrast gebruikt.</p>","image_url":"","wiki_title":"Upper gastrointestinal series","match":"barium slikfoto|slikfoto|x-oesophagus","option_only":true},"papilla duodeni minor":{"title":"Papilla duodeni minor","short":"De papilla duodeni minor is de kleine uitmonding in het duodenum van de ductus pancreaticus accessorius (Santorini).","definition":"<p>De <strong>papilla minor</strong> ligt iets boven en vóór de papil van Vater. Bij pancreas divisum (onvolledige versmelting van de ventrale en dorsale pancreasaanleg) loopt het meeste pancreassap via deze kleine papil, wat recidiverende pancreatitis kan geven.</p>","image_url":"","wiki_title":"Minor duodenal papilla","match":"papilla duodeni minor","option_only":true},"arteria mesenterica superior":{"title":"A. mesenterica superior","short":"De a. mesenterica superior voorziet de dunne darm en het proximale colon van bloed.","definition":"<p>De <strong>a. mesenterica superior</strong> ontspringt ter hoogte van L1 uit de aorta, achter de pancreas, en loopt vóór het duodenum. Takken: aa. jejunales en ileales, a. ileocolica, a. colica dextra en media. Een acute afsluiting (embolie) geeft mesenteriale ischemie met hevige buikpijn bij weinig afwijkingen aan de buik.</p>","image_url":"","wiki_title":"Superior mesenteric artery","match":"arteria mesenterica superior","option_only":true},"achterdarm":{"title":"Achterdarm (hindgut)","short":"De achterdarm is het caudale deel van de embryonale darm, waaruit het distale colon, het rectum en het bovenste deel van het anaalkanaal ontstaan.","definition":"<p>Uit de <strong>achterdarm</strong> ontstaan het distale derde van het colon transversum, colon descendens, sigmoïd, rectum en bovenste anaalkanaal, en het epitheel van blaas en urethra (via de cloaca). Hij wordt doorbloed door de a. mesenterica inferior; pijn wordt in de onderbuik gevoeld.</p>","image_url":"","wiki_title":"Hindgut","match":"achterdarm|hindgut","option_only":true},"crepiteren":{"title":"Crepitaties","short":"Crepitaties zijn fijne of grove knisperende bijgeluiden bij het luisteren naar de longen, vooral tijdens de inademing.","definition":"<p><strong>Fijne crepitaties</strong> (laat-inspiratoir, ‘klittenband’) passen bij longfibrose en beginnend longoedeem; <strong>grovere</strong> bij pneumonie, longoedeem of bronchiëctasieën. Ook bij gewrichten en onderhuids (emfyseem) spreekt men van crepitaties.</p>","image_url":"","wiki_title":"Crackles","match":"crepiteren|crepitaties|crepitatie","option_only":true},"hyperventilatie":{"title":"Hyperventilatie","short":"Bij hyperventilatie wordt meer geademd dan nodig is, waardoor het CO₂ daalt (respiratoire alkalose) met tintelingen en duizeligheid.","definition":"<p>Een <strong>hyperventilatieaanval</strong> kan worden uitgelokt door angst of paniek en geeft tintelingen rond de mond en in de vingers, duizeligheid, benauwdheid en soms carpopedale spasmen. Hyperventilatie kan ook compensatoir zijn (metabole acidose) of door hypoxie, pijn of koorts ontstaan; die oorzaken moeten worden uitgesloten.</p>","image_url":"","wiki_title":"Hyperventilation","match":"hyperventilatie|chronisch hyperventileren","option_only":true},"decompensatio cordis":{"title":"Hartfalen","short":"Bij hartfalen kan het hart onvoldoende bloed rondpompen voor de behoefte van het lichaam, met kortademigheid, vermoeidheid en vochtophoping.","definition":"<p><strong>Hartfalen</strong> wordt ingedeeld naar ejectiefractie (verminderd, licht verminderd, behouden). Oorzaken zijn o.a. ischemie, hypertensie, klepziekten en cardiomyopathieën. Klachten: inspanningsdyspneu, orthopneu, oedeem, gewichtstoename. Diagnose met NT-proBNP en echocardiografie. Behandeling bij verminderde EF: ACE-remmer/ARNI, bètablokker, MRA, SGLT2-remmer en diuretica bij overvulling.</p>","image_url":"","wiki_title":"Heart failure","match":"decompensatio cordis","option_only":true},"eenzijdig crepiteren":{"title":"Crepitaties","short":"Crepitaties zijn fijne of grove knisperende bijgeluiden bij het luisteren naar de longen, vooral tijdens de inademing.","definition":"<p><strong>Fijne crepitaties</strong> (laat-inspiratoir, ‘klittenband’) passen bij longfibrose en beginnend longoedeem; <strong>grovere</strong> bij pneumonie, longoedeem of bronchiëctasieën. Ook bij gewrichten en onderhuids (emfyseem) spreekt men van crepitaties.</p>","image_url":"","wiki_title":"Crackles","match":"eenzijdig crepiteren","option_only":true},"conventionele x-thorax":{"title":"X-thorax","short":"Een X-thorax is een röntgenfoto van de borstkas; het eerste beeldvormend onderzoek bij verdenking op longafwijkingen, hartfalen of pneumothorax.","definition":"<p>Een <strong>X-thorax</strong> is een röntgenopname van de borstkas, meestal posterieur-anterieur en lateraal. Lucht is zwart, weke delen grijs en bot wit.</p><p>Het is snel, goedkoop en met een lage stralingsdosis, en wordt gebruikt om o.a. pneumonie (infiltraat), pleuravocht, pneumothorax, longtumoren, hartvergroting en tekenen van hartfalen op te sporen. Kleine of subtiele afwijkingen zijn er minder goed op te zien dan op een CT.</p>","image_url":"","wiki_title":"Chest radiograph","match":"conventionele x-thorax","option_only":true},"sinusoïdaal endotheel":{"title":"Sinusoïdale endotheelcel","short":"Sinusoïdale endotheelcellen bekleden de leversinusoïden en hebben open poriën zonder echte basaalmembraan.","definition":"<p><strong>Lever-sinusoïdale endotheelcellen</strong> bevatten groepjes fenestrae (zeefplaten) waardoor plasma vrij de ruimte van Disse in kan stromen, in contact met de microvilli van hepatocyten. Ze ruimen ook kleine deeltjes uit het bloed op. Bij fibrose verdwijnen de fenestrae (capillarisatie).</p>","image_url":"","wiki_title":"Liver sinusoidal endothelial cell","match":"sinusoïdaal endotheel","option_only":true},"endocriene pancreas":{"title":"Pancreas","short":"De pancreas is zowel een exocriene klier (verteringsenzymen en bicarbonaat naar het duodenum) als een endocriene klier (insuline en glucagon uit de eilandjes van Langerhans).","definition":"<p>De <strong>pancreas</strong> ligt retroperitoneaal achter de maag, met de kop in de bocht van het duodenum.</p><p>Het <em>exocriene</em> deel (±98%) maakt verteringsenzymen (trypsine(ogeen), lipase, amylase) en bicarbonaatrijk sap, dat via de ductus pancreaticus samen met de galweg in het duodenum uitmondt. Het <em>endocriene</em> deel bestaat uit de eilandjes van Langerhans met bètacellen (insuline), alfacellen (glucagon) en deltacellen (somatostatine).</p>","image_url":"","wiki_title":"Pancreas","match":"endocriene pancreas","option_only":true},"exocriene pancreas":{"title":"Pancreas","short":"De pancreas is zowel een exocriene klier (verteringsenzymen en bicarbonaat naar het duodenum) als een endocriene klier (insuline en glucagon uit de eilandjes van Langerhans).","definition":"<p>De <strong>pancreas</strong> ligt retroperitoneaal achter de maag, met de kop in de bocht van het duodenum.</p><p>Het <em>exocriene</em> deel (±98%) maakt verteringsenzymen (trypsine(ogeen), lipase, amylase) en bicarbonaatrijk sap, dat via de ductus pancreaticus samen met de galweg in het duodenum uitmondt. Het <em>endocriene</em> deel bestaat uit de eilandjes van Langerhans met bètacellen (insuline), alfacellen (glucagon) en deltacellen (somatostatine).</p>","image_url":"","wiki_title":"Pancreas","match":"exocriene pancreas","option_only":true},"bacteriodes fragilis":{"title":"Bacteroides fragilis","short":"Bacteroides fragilis is een gramnegatieve anaerobe staaf uit de darmflora en een belangrijke verwekker van buikabcessen.","definition":"<p><strong><em>Bacteroides fragilis</em></strong> is een van de talrijkste anaeroben in het colon. Bij perforatie of darmchirurgie kan hij in de buikholte terechtkomen en (met andere bacteriën) abcessen en peritonitis veroorzaken; het kapsel bevordert abcesvorming. Hij maakt vaak bètalactamase; metronidazol, amoxicilline-clavulaanzuur en carbapenems werken wel.</p>","image_url":"","wiki_title":"Bacteroides fragilis","match":"bacteriodes fragilis","option_only":true},"rotavirus infectie":{"title":"Rotavirus","short":"Rotavirus is een dubbelstrengs RNA-virus dat bij jonge kinderen een ernstige gastro-enteritis met braken en waterige diarree veroorzaakt.","definition":"<p><strong>Rotavirus</strong> wordt fecaal-oraal overgedragen en beschadigt de villi van de dunne darm. Vooral kinderen onder de 2 jaar krijgen koorts, braken en waterige diarree, met risico op uitdroging. Er bestaat een oraal levend vaccin, inmiddels opgenomen in het Rijksvaccinatieprogramma.</p>","image_url":"","wiki_title":"Rotavirus","match":"rotavirus infectie","option_only":true},"glycogenolyse":{"title":"Glycogenolyse","short":"Glycogenolyse is de afbraak van glycogeen tot glucose(-1-fosfaat), gestimuleerd door glucagon en adrenaline.","definition":"<p>Het sleutelenzym is <strong>glycogeenfosforylase</strong>. In de lever levert glycogenolyse glucose aan het bloed; in spier alleen brandstof voor de spier zelf. Enzymdefecten geven glycogeenstapelingsziekten (bijv. ziekte van McArdle in spier, Von Gierke in lever).</p>","image_url":"","wiki_title":"Glycogenolysis","match":"glycogenolyse|glycogeenafbraak","option_only":true},"allantoïs":{"title":"Allantoïs","short":"De allantoïs is een embryonale uitstulping van de achterdarm naar de navelstreng; ze wordt later de urachus.","definition":"<p>De <strong>allantoïs</strong> is bij de mens klein, maar de vaten in haar wand worden de navelvaten. Haar restant, de urachus, verbindt de blaas met de navel en verbindweefselt normaal.</p>","image_url":"","wiki_title":"Allantois","match":"allantoïs|allantois","option_only":true},"chondrocyten":{"title":"Chondrocyten","short":"Chondrocyten zijn kraakbeencellen, die in holtes (lacunes) in de kraakbeenmatrix liggen en de matrix maken en onderhouden.","definition":"<p>Omdat kraakbeen geen bloedvaten heeft, worden <strong>chondrocyten</strong> gevoed via diffusie. Ze delen weinig, waardoor kraakbeenschade slecht herstelt.</p>","image_url":"","wiki_title":"Chondrocyte","match":"chondrocyten|chondrocyt","option_only":true},"detoxificatie":{"title":"Detoxificatie (lever)","short":"Detoxificatie is het onschadelijk maken van giftige stoffen en geneesmiddelen, vooral door de lever.","definition":"<p>In de lever worden stoffen via <strong>fase I</strong> (cytochroom P450) en <strong>fase II</strong> (conjugatie) omgezet, en ammoniak wordt via de ureumcyclus afgevoerd. Bij leverfalen hopen toxines en geneesmiddelen zich op.</p>","image_url":"","wiki_title":"","match":"detoxificatie|ontgifting","option_only":true},"nasopharynx":{"title":"Nasofarynx (neuskeelholte)","short":"De farynx bestaat uit nasofarynx, orofarynx en hypofarynx (laryngofarynx).","definition":"<p>In de <strong>nasofarynx</strong> liggen de neusamandel en de opening van de buis van Eustachius. De orofarynx bevat de keelamandelen en de tongbasis; de hypofarynx ligt achter het strottenhoofd. Het nasofarynxcarcinoom is geassocieerd met EBV.</p>","image_url":"","wiki_title":"Pharynx","match":"nasopharynx|nasofarynx|neuskeelholte|laryngopharynx|oropharynx","option_only":true},"fissura horizontalis":{"title":"Longkwabben en fissuren","short":"De rechterlong heeft drie kwabben (gescheiden door de fissura obliqua en horizontalis), de linker twee (alleen fissura obliqua).","definition":"<p>De <strong>longhilus</strong> is de plek waar bronchus, vaten en zenuwen de long in- en uitgaan. De <strong>longtop</strong> reikt tot boven de clavicula; een Pancoast-tumor hier kan de plexus brachialis en de sympathische keten (Horner) aantasten.</p>","image_url":"","wiki_title":"Lung","match":"fissura horizontalis|fissura obliqua|longapex|longhilus","option_only":true},"barrett-slokdarm":{"title":"Barrett-slokdarm","short":"Bij een Barrett-slokdarm is het plaveiselepitheel onderin de slokdarm door chronische reflux vervangen door darmachtig cilinderepitheel.","definition":"<p>Een <strong>Barrett-slokdarm</strong> is een voorstadium van het adenocarcinoom van de slokdarm. Patiënten worden periodiek gecontroleerd met endoscopie en biopten; bij dysplasie volgt endoscopische behandeling.</p>","image_url":"","wiki_title":"Barrett's esophagus","match":"barrett-slokdarm|barrett oesophagus|een barrett slokdarm","option_only":true},"geconjugeerde hyperbilirubinemie":{"title":"Geconjugeerd bilirubine","short":"Geconjugeerd bilirubine is het in de lever aan glucuronzuur gekoppelde, in water oplosbare bilirubine dat via de gal wordt uitgescheiden.","definition":"<p>Een verhoogd <strong>geconjugeerd bilirubine</strong> past bij leverziekte of galwegobstructie. Omdat het in water oplosbaar is, komt het in de urine (donkere urine). Bij pasgeborenen is een verhoogd geconjugeerd bilirubine altijd afwijkend en vraagt het om onderzoek naar bijv. galgangatresie.</p>","image_url":"","wiki_title":"Bilirubin","match":"geconjugeerde hyperbilirubinemie","option_only":true},"ongeconjugeerde hyperbiliribinumie":{"title":"Ongeconjugeerd bilirubine","short":"Ongeconjugeerd bilirubine is het in vet oplosbare bilirubine dat bij de afbraak van heem ontstaat, voordat de lever het koppelt aan glucuronzuur.","definition":"<p>Bij afbraak van hemoglobine ontstaat <strong>ongeconjugeerd bilirubine</strong>, dat aan albumine gebonden naar de lever gaat. Daar koppelt UGT1A1 het aan glucuronzuur (geconjugeerd, wateroplosbaar). Een verhoogd ongeconjugeerd bilirubine past bij hemolyse, het syndroom van Gilbert of neonatale icterus; bij pasgeborenen kan het de bloed-hersenbarrière passeren (kernicterus).</p>","image_url":"","wiki_title":"Bilirubin","match":"ongeconjugeerde hyperbiliribinumie","option_only":true},"voedselintolerantie":{"title":"Lactose-intolerantie","short":"Bij lactose-intolerantie is er te weinig lactase in de dunne darm, waardoor melksuiker in de dikke darm wordt gefermenteerd.","definition":"<p>Bij <strong>lactose-intolerantie</strong> geeft melk een opgeblazen gevoel, winderigheid, buikkrampen en osmotische diarree. De primaire vorm (afnemende lactase na de kindertijd) komt wereldwijd bij de meerderheid van de volwassenen voor; secundaire vormen ontstaan bij darmschade (bijv. coeliakie, gastro-enteritis). Diagnose met een waterstofademtest of eliminatie.</p>","image_url":"","wiki_title":"Lactose intolerance","match":"voedselintolerantie","option_only":true},"salmonella infectie":{"title":"Salmonella","short":"Salmonella zijn gramnegatieve staven die voedselinfecties (gastro-enteritis) en buiktyfus kunnen veroorzaken.","definition":"<p>Niet-tyfeuze <strong>salmonellae</strong> komen via onvoldoende verhit voedsel (kip, eieren) binnen en geven koorts, buikkrampen en diarree. <em>S. typhi</em> en <em>S. paratyphi</em> veroorzaken (para)tyfus, een systemische ziekte met hoge koorts, relatieve bradycardie en roseola. Bij sikkelcelziekte kan Salmonella osteomyelitis veroorzaken.</p>","image_url":"","wiki_title":"Salmonella","match":"salmonella infectie","option_only":true},"candida-infectie":{"title":"Candida albicans","short":"Candida albicans is een gist die normaal op slijmvliezen voorkomt en bij verminderde weerstand spruw, vaginale schimmelinfectie of invasieve infecties geeft.","definition":"<p><strong><em>Candida albicans</em></strong> is een gist (schimmel) die bij veel mensen in mond, darm en vagina voorkomt. Hij kan zowel als ronde gistcel als met (pseudo)hyfen groeien.</p><p>Bij een verstoorde flora (antibiotica) of verminderde afweer veroorzaakt hij oppervlakkige infecties zoals spruw (orale candidiasis), vaginale candidiasis en intertrigo. Bij ernstig immuungecompromitteerden of patiënten met lijnen kan een invasieve candidemie ontstaan.</p>","image_url":"","wiki_title":"Candida albicans","match":"candida-infectie","option_only":true},"hepatitis-b":{"title":"Hepatitis B","short":"Hepatitis B is een via bloed en seks overgedragen DNA-virus dat acute en chronische leverontsteking geeft, met risico op cirrose en levercelcarcinoom.","definition":"<p><strong>Hepatitis B</strong> wordt veroorzaakt door het hepatitis B-virus, een omhuld (gedeeltelijk dubbelstrengs) DNA-virus. Overdracht via bloed, seksueel contact en van moeder op kind rond de geboorte.</p><p>Bij volwassenen geneest de meeste acute infectie; bij pasgeborenen wordt de infectie meestal <em>chronisch</em>. Chronische hepatitis B kan leiden tot levercirrose en hepatocellulair carcinoom. Diagnostiek via serologie (HBsAg, anti-HBc, anti-HBs). Er is een effectief vaccin.</p>","image_url":"","wiki_title":"Hepatitis B","match":"hepatitis-b","option_only":true},"hepatitis b virus":{"title":"Hepatitis B","short":"Hepatitis B is een via bloed en seks overgedragen DNA-virus dat acute en chronische leverontsteking geeft, met risico op cirrose en levercelcarcinoom.","definition":"<p><strong>Hepatitis B</strong> wordt veroorzaakt door het hepatitis B-virus, een omhuld (gedeeltelijk dubbelstrengs) DNA-virus. Overdracht via bloed, seksueel contact en van moeder op kind rond de geboorte.</p><p>Bij volwassenen geneest de meeste acute infectie; bij pasgeborenen wordt de infectie meestal <em>chronisch</em>. Chronische hepatitis B kan leiden tot levercirrose en hepatocellulair carcinoom. Diagnostiek via serologie (HBsAg, anti-HBc, anti-HBs). Er is een effectief vaccin.</p>","image_url":"","wiki_title":"Hepatitis B","match":"hepatitis b virus","option_only":true},"tachypnoe":{"title":"Tachypneu","short":"Tachypneu is een te snelle ademhaling, bij volwassenen meer dan ongeveer 20 per minuut.","definition":"<p><strong>Tachypneu</strong> komt voor bij koorts, pijn, angst, longaandoeningen, hartfalen, sepsis en metabole acidose (compenserend). Een verhoogde ademfrequentie is een belangrijk alarmsignaal in vroege-waarschuwingsscores. Bij kinderen gelden leeftijdsafhankelijke grenzen.</p>","image_url":"","wiki_title":"Tachypnea","match":"tachypnoe","option_only":true},"astma-aanval":{"title":"Astma","short":"Astma is een chronische ontsteking van de luchtwegen met wisselende, reversibele luchtwegobstructie en hyperreactiviteit; klachten zijn piepen, benauwdheid en hoesten.","definition":"<p>Bij <strong>astma</strong> zijn de luchtwegen chronisch ontstoken (vaak eosinofiel/Th2-gemedieerd) en <em>hyperreactief</em>: op prikkels zoals allergenen, inspanning, koude lucht of rook ontstaan bronchoconstrictie, slijmvliesoedeem en slijmproductie.</p><p>De obstructie is variabel en grotendeels <em>reversibel</em> (verbetering van de FEV1 na een luchtwegverwijder). Klachten: aanvallen van piepen, kortademigheid, een beklemd gevoel op de borst en hoesten, vaak ’s nachts. Behandeling met inhalatiecorticosteroïden en luchtwegverwijders.</p>","image_url":"","wiki_title":"Asthma","match":"astma-aanval","option_only":true},"astma-exacerbatie":{"title":"Astma","short":"Astma is een chronische ontsteking van de luchtwegen met wisselende, reversibele luchtwegobstructie en hyperreactiviteit; klachten zijn piepen, benauwdheid en hoesten.","definition":"<p>Bij <strong>astma</strong> zijn de luchtwegen chronisch ontstoken (vaak eosinofiel/Th2-gemedieerd) en <em>hyperreactief</em>: op prikkels zoals allergenen, inspanning, koude lucht of rook ontstaan bronchoconstrictie, slijmvliesoedeem en slijmproductie.</p><p>De obstructie is variabel en grotendeels <em>reversibel</em> (verbetering van de FEV1 na een luchtwegverwijder). Klachten: aanvallen van piepen, kortademigheid, een beklemd gevoel op de borst en hoesten, vaak ’s nachts. Behandeling met inhalatiecorticosteroïden en luchtwegverwijders.</p>","image_url":"","wiki_title":"Asthma","match":"astma-exacerbatie","option_only":true},"ct-scan van het abdomen":{"title":"CT abdomen","short":"Een CT abdomen is een röntgenscan in dwarsdoorsneden van de buik, vaak met contrast; goed voor acute buik, tumoren, abcessen en trauma.","definition":"<p>Bij een <strong>CT abdomen</strong> worden met röntgenstraling dunne dwarsdoorsneden van de buik gemaakt, meestal met intraveneus (en soms oraal) contrast.</p><p>Het geeft een overzichtelijk beeld van alle buikorganen, de darm en het retroperitoneum en wordt gebruikt bij een acute buik (bijv. perforatie, diverticulitis, appendicitis bij volwassenen), bij het stadiëren van tumoren, het opsporen van abcessen en bij trauma. Nadelen zijn de stralingsbelasting en het contrastmiddel (nierfunctie, allergie).</p>","image_url":"","wiki_title":"CT scan","match":"ct-scan van het abdomen","option_only":true},"mesenterica superior":{"title":"A. mesenterica superior","short":"De a. mesenterica superior voorziet de dunne darm en het proximale colon van bloed.","definition":"<p>De <strong>a. mesenterica superior</strong> ontspringt ter hoogte van L1 uit de aorta, achter de pancreas, en loopt vóór het duodenum. Takken: aa. jejunales en ileales, a. ileocolica, a. colica dextra en media. Een acute afsluiting (embolie) geeft mesenteriale ischemie met hevige buikpijn bij weinig afwijkingen aan de buik.</p>","image_url":"","wiki_title":"Superior mesenteric artery","match":"mesenterica superior","option_only":true},"cyclo-oxygenase inhibitors (cox-remmers)":{"title":"NSAID's","short":"NSAID's remmen cyclo-oxygenase en daarmee de vorming van prostaglandinen; ze werken pijnstillend, koortsverlagend en ontstekingsremmend.","definition":"<p><strong>NSAID's</strong> (zoals ibuprofen, naproxen, diclofenac) remmen COX-1 en COX-2. Door remming van beschermende prostaglandinen kunnen ze maagulcera en bloedingen geven, vooral bij ouderen; ook kunnen ze de nierfunctie verslechteren, de bloeddruk verhogen, hartfalen verergeren en het risico op hart- en vaatziekten iets verhogen. Selectieve COX-2-remmers geven minder maagschade.</p>","image_url":"","wiki_title":"Nonsteroidal anti-inflammatory drug","match":"cyclo-oxygenase inhibitors (cox-remmers)","option_only":true},"een ventilatie-perfusie ongelijkheid":{"title":"Ventilatie-perfusiemismatch","short":"Bij een ventilatie-perfusiemismatch passen luchtstroom en bloedstroom in delen van de long niet bij elkaar; dat is de belangrijkste oorzaak van hypoxemie.","definition":"<p>Gebieden met wel bloed maar te weinig ventilatie (lage V/Q, ‘relatieve shunt’, bijv. pneumonie, atelectase, astma) leveren zuurstofarm bloed. Gebieden met ventilatie maar weinig bloed (hoge V/Q, dode ruimte, bijv. longembolie) dragen niet bij aan de gaswisseling. Extra zuurstof verbetert hypoxemie door V/Q-mismatch goed, in tegenstelling tot een echte shunt.</p>","image_url":"","wiki_title":"Ventilation/perfusion ratio","match":"een ventilatie-perfusie ongelijkheid","option_only":true},"een diffusiestoornis":{"title":"Diffusiestoornis","short":"Bij een diffusiestoornis gaat zuurstof minder goed van de alveoli naar het bloed, door verdikking van de membraan of verlies van oppervlak.","definition":"<p>Een <strong>diffusiestoornis</strong> wordt gemeten met de DLCO (koolmonoxide-diffusiecapaciteit). Ze komt voor bij interstitiële longziekten (verdikte alveolaire wand), emfyseem (verlies van oppervlak), pulmonale hypertensie en anemie. De hypoxemie wordt vaak pas duidelijk bij inspanning, omdat het bloed dan korter in de capillair verblijft.</p>","image_url":"","wiki_title":"Diffusing capacity for carbon monoxide","match":"een diffusiestoornis","option_only":true},"barretoesophagus":{"title":"Barrett-slokdarm","short":"Bij een Barrett-slokdarm is het plaveiselepitheel onderin de slokdarm door chronische reflux vervangen door darmachtig cilinderepitheel.","definition":"<p>Een <strong>Barrett-slokdarm</strong> is een voorstadium van het adenocarcinoom van de slokdarm. Patiënten worden periodiek gecontroleerd met endoscopie en biopten; bij dysplasie volgt endoscopische behandeling.</p>","image_url":"","wiki_title":"Barrett's esophagus","match":"barretoesophagus","option_only":true},"glycogeen fosforylase":{"title":"Glycogenolyse","short":"Glycogenolyse is de afbraak van glycogeen tot glucose(-1-fosfaat), gestimuleerd door glucagon en adrenaline.","definition":"<p>Het sleutelenzym is <strong>glycogeenfosforylase</strong>. In de lever levert glycogenolyse glucose aan het bloed; in spier alleen brandstof voor de spier zelf. Enzymdefecten geven glycogeenstapelingsziekten (bijv. ziekte van McArdle in spier, Von Gierke in lever).</p>","image_url":"","wiki_title":"Glycogenolysis","match":"glycogeen fosforylase","option_only":true},"hdl":{"title":"HDL-cholesterol","short":"HDL vervoert cholesterol uit de weefsels terug naar de lever (reverse cholesterol transport); een hoog HDL hangt samen met minder hart- en vaatziekten.","definition":"<p>Een laag <strong>HDL</strong> komt voor bij roken, overgewicht, weinig beweging, diabetes type 2 en hypertriglyceridemie. Medicijnen die alleen het HDL verhogen, verminderen het risico op hart- en vaatziekten niet.</p>","image_url":"","wiki_title":"High-density lipoprotein","match":"hdl|high density lipoproteins|hdl-cholesterol","option_only":true},"diafragma":{"title":"Diafragma (middenrif)","short":"Het diafragma is de koepelvormige ademhalingsspier tussen borst- en buikholte, geïnnerveerd door de n. phrenicus (C3–C5).","definition":"<p>Bij inademing trekt het <strong>diafragma</strong> samen en zakt het, waardoor de borstholte groter wordt. Door het diafragma lopen o.a. de aorta, de slokdarm en de v. cava inferior. Uitval van de n. phrenicus geeft een hoogstand van het diafragma aan die kant.</p>","image_url":"","wiki_title":"Thoracic diaphragm","match":"diafragma|diaphragma|middenrif","option_only":true},"high density lipoproteins":{"title":"HDL-cholesterol","short":"HDL vervoert cholesterol uit de weefsels terug naar de lever (reverse cholesterol transport); een hoog HDL hangt samen met minder hart- en vaatziekten.","definition":"<p>Een laag <strong>HDL</strong> komt voor bij roken, overgewicht, weinig beweging, diabetes type 2 en hypertriglyceridemie. Medicijnen die alleen het HDL verhogen, verminderen het risico op hart- en vaatziekten niet.</p>","image_url":"","wiki_title":"High-density lipoprotein","match":"high density lipoproteins","option_only":true},"diaphragma":{"title":"Diafragma (middenrif)","short":"Het diafragma is de koepelvormige ademhalingsspier tussen borst- en buikholte, geïnnerveerd door de n. phrenicus (C3–C5).","definition":"<p>Bij inademing trekt het <strong>diafragma</strong> samen en zakt het, waardoor de borstholte groter wordt. Door het diafragma lopen o.a. de aorta, de slokdarm en de v. cava inferior. Uitval van de n. phrenicus geeft een hoogstand van het diafragma aan die kant.</p>","image_url":"","wiki_title":"Thoracic diaphragm","match":"diaphragma","option_only":true},"sterk verhoogd c-reactief proteïne (crp)":{"title":"CRP","short":"C-reactief proteïne; ontstekingseiwit in het bloed dat helpt de kans op een gecompliceerde infectie in te schatten.","definition":"<p>Het CRP stijgt bij ontsteking of infectie; in de huisartsenpraktijk stuurt het het antibioticabeleid bij luchtweginfecties.</p>","image_url":"","wiki_title":"C-reactive_protein","match":"sterk verhoogd c-reactief proteïne (crp)","option_only":true},"ct thorax/abdomen":{"title":"CT abdomen","short":"Een CT abdomen is een röntgenscan in dwarsdoorsneden van de buik, vaak met contrast; goed voor acute buik, tumoren, abcessen en trauma.","definition":"<p>Bij een <strong>CT abdomen</strong> worden met röntgenstraling dunne dwarsdoorsneden van de buik gemaakt, meestal met intraveneus (en soms oraal) contrast.</p><p>Het geeft een overzichtelijk beeld van alle buikorganen, de darm en het retroperitoneum en wordt gebruikt bij een acute buik (bijv. perforatie, diverticulitis, appendicitis bij volwassenen), bij het stadiëren van tumoren, het opsporen van abcessen en bij trauma. Nadelen zijn de stralingsbelasting en het contrastmiddel (nierfunctie, allergie).</p>","image_url":"","wiki_title":"CT scan","match":"ct thorax/abdomen","option_only":true},"middendarm":{"title":"Middendarm","short":"Embryonaal darmsegment waaruit distale duodenum tot en met het proximale tweederde deel van het colon ontstaat.","definition":"<p>De <b>middendarm</b> (midgut) vormt o.a. het jejunum, ileum, caecum, appendix en het rechter deel van het colon. Wordt gevoed door de a. mesenterica superior.</p>","image_url":"","wiki_title":"Midgut","match":"middendarm","option_only":true},"endometriose":{"title":"Endometriose","short":"Aanwezigheid van endometriumweefsel buiten de uterusholte, met cyclische pijn en subfertiliteit.","definition":"<p><strong>Endometriose</strong> kan oppervlakkig peritoneaal, ovarieel (endometrioom) of diep infiltrerend zijn; diepe endometriose wordt met MRI in beeld gebracht.</p>","image_url":"","wiki_title":"Endometriosis","match":"endometriose","option_only":true},"mass movements":{"title":"Mass movements","short":"Krachtige, enkele keren per dag optredende voortstuwende golven in het colon.","definition":"<p><b>Mass movements</b> (massabewegingen) treden vaak op na een maaltijd, onder invloed van de gastrocolische reflex. Ze verschillen van haustrale segmentaties, die de inhoud vooral mengen.</p>","image_url":"","wiki_title":"","match":"mass movements","option_only":true},"palatum durum":{"title":"Palatum durum","short":"Het harde gehemelte: benig dak van de mondholte.","definition":"<p>Het palatum durum (harde verhemelte) wordt gevormd door de processus palatini van de maxilla en de horizontale platen van de ossa palatina en scheidt de mond- van de neusholte.</p>","image_url":"","wiki_title":"Hard palate","match":"palatum durum","option_only":true},"fructose-2,6-bisfosfaat (f2,6-bisp)":{"title":"Fructose 2,6-bisfosfaat","short":"Krachtige allostere activator van de glycolyse (PFK1) en remmer van de gluconeogenese in de lever.","definition":"<p><b>Fructose 2,6-bisfosfaat</b> (F2,6-bisP) stuurt de balans tussen glycolyse en gluconeogenese. Insuline verhoogt de spiegel (glycolyse aan), glucagon verlaagt haar.</p>","image_url":"","wiki_title":"Fructose 2,6-bisphosphate","match":"fructose-2,6-bisfosfaat (f2,6-bisp)","option_only":true},"bronchiolus":{"title":"Bronchiolus","short":"Kleine luchtweg (< 1 mm) zonder kraakbeen en klieren, herkenbaar aan een geplooide muur met gladde spier.","definition":"<p>Een <b>bronchiolus</b> is een geleidende luchtweg zonder kraakbeen of submuceuze klieren. Histologisch valt de relatief dikke laag gladde spier en het (soms geplooide) cilindrische tot kubische epitheel op.</p>","image_url":"","wiki_title":"Bronchiole","match":"bronchiolus","option_only":true},"vetzuurverbranding":{"title":"Vetzuren","short":"Vetzuren zijn koolstofketens met een carboxylgroep; ze worden via bèta-oxidatie in de mitochondriën verbrand en leveren veel ATP, maar alleen aeroob.","definition":"<p><strong>Vetzuren</strong> zijn lange koolwaterstofketens met een carboxylgroep, verzadigd of onverzadigd. Ze worden opgeslagen als triglyceriden in vetweefsel en bij behoefte door lipolyse vrijgemaakt.</p><p>In de cel worden ze met carnitine de mitochondriën in getransporteerd en via <em>bèta-oxidatie</em> afgebroken tot acetyl-CoA, dat de citroenzuurcyclus in gaat. Vetzuren leveren per gram veel meer energie dan glucose, maar alleen via zuurstofafhankelijke stofwisseling en relatief langzaam. In de lever kunnen ze ketonlichamen vormen.</p>","image_url":"","wiki_title":"Fatty acid","match":"vetzuurverbranding","option_only":true},"creatine fosfaat":{"title":"Creatinefosfaat","short":"Energierijke fosfaatverbinding die zeer snel ATP kan regenereren voor kortdurende, explosieve inspanning zoals sprinten.","definition":"<p><b>Creatinefosfaat (fosfocreatine)</b> levert onmiddellijk een fosfaatgroep om ADP snel om te zetten in ATP. Dit systeem domineert bij korte, maximale inspanning (enkele seconden) zoals de 100 m sprint.</p>","image_url":"","wiki_title":"Phosphocreatine","match":"creatine fosfaat","option_only":true},"ct-thorax/abdomen":{"title":"CT abdomen","short":"Een CT abdomen is een röntgenscan in dwarsdoorsneden van de buik, vaak met contrast; goed voor acute buik, tumoren, abcessen en trauma.","definition":"<p>Bij een <strong>CT abdomen</strong> worden met röntgenstraling dunne dwarsdoorsneden van de buik gemaakt, meestal met intraveneus (en soms oraal) contrast.</p><p>Het geeft een overzichtelijk beeld van alle buikorganen, de darm en het retroperitoneum en wordt gebruikt bij een acute buik (bijv. perforatie, diverticulitis, appendicitis bij volwassenen), bij het stadiëren van tumoren, het opsporen van abcessen en bij trauma. Nadelen zijn de stralingsbelasting en het contrastmiddel (nierfunctie, allergie).</p>","image_url":"","wiki_title":"CT scan","match":"ct-thorax/abdomen","option_only":true},"fecaal calprotectine":{"title":"Fecaal calprotectine","short":"Ontstekingsmarker in de ontlasting; verhoogd bij inflammatoire darmziekten, laag bij IBS.","definition":"<p><b>Fecaal calprotectine</b> is een eiwit uit neutrofielen dat in de feces wordt gemeten. Een verhoogde waarde wijst op darmontsteking (bv. de ziekte van Crohn of colitis ulcerosa) en helpt IBD van functionele klachten te onderscheiden.</p>","image_url":"","wiki_title":"Calprotectin","match":"fecaal calprotectine","option_only":true},"hoofdcellen":{"title":"Hoofdcellen","short":"Cellen in de maagwand die pepsinogeen produceren.","definition":"<p><b>Hoofdcellen</b> (chief cells) van de maagklieren bezitten veel ruw endoplasmatisch reticulum voor de aanmaak en secretie van pepsinogeen, het inactieve voorloperenzym van pepsine.</p>","image_url":"","wiki_title":"Gastric chief cell","match":"hoofdcellen","option_only":true},"d-dimeer":{"title":"D-dimeer","short":"Afbraakproduct van fibrine; een normale waarde sluit bij lage verdenking een trombose/longembolie vrijwel uit.","definition":"<p>D-dimeer is een fibrinolyse-afbraakproduct. Een normale waarde bij lage klinische verdenking sluit een longembolie uit; een verhoogde waarde is aspecifiek en vereist beeldvorming.</p>","image_url":"","wiki_title":"","match":"d-dimeer","option_only":true},"chronisch inflammatoir darmlijden (inflammatory bowel disease)":{"title":"Inflammatory bowel disease (IBD)","short":"Chronische darmontsteking (ziekte van Crohn, colitis ulcerosa) met bloed in de ontlasting en koorts.","definition":"<p><b>IBD</b> onderscheidt zich van prikkelbaredarmsyndroom (PDS) door alarmsymptomen als bloed in de ontlasting, koorts en ontstekingsafwijkingen.</p>","image_url":"","wiki_title":"Inflammatory bowel disease","match":"chronisch inflammatoir darmlijden (inflammatory bowel disease)","option_only":true},"stikstofmonoxide (no)":{"title":"Stikstofoxide (NO)","short":"Stikstofoxide (NO) is een gasvormige signaalstof uit het endotheel die gladde spier ontspant en zo vaten verwijdt.","definition":"<p><strong>NO</strong> wordt gemaakt uit arginine door NO-synthase. In het endotheel ontstaat het o.a. door schuifspanning en acetylcholine; het diffundeert naar de gladde spiercel, activeert guanylaatcyclase en verhoogt cGMP, wat relaxatie geeft. NO remt ook de plaatjesaggregatie. Nitraten en PDE5-remmers versterken deze route.</p>","image_url":"","wiki_title":"Nitric oxide","match":"stikstofmonoxide (no)","option_only":true},"fructose 2,6-bisfosfaat (f2,6bp)":{"title":"Fructose 2,6-bisfosfaat","short":"Krachtige allostere activator van de glycolyse (PFK1) en remmer van de gluconeogenese in de lever.","definition":"<p><b>Fructose 2,6-bisfosfaat</b> (F2,6-bisP) stuurt de balans tussen glycolyse en gluconeogenese. Insuline verhoogt de spiegel (glycolyse aan), glucagon verlaagt haar.</p>","image_url":"","wiki_title":"Fructose 2,6-bisphosphate","match":"fructose 2,6-bisfosfaat (f2,6bp)","option_only":true},"adenosine trifosfaat (atp)":{"match":"adenosine trifosfaat (atp)","title":"ATP (adenosinetrifosfaat)","short":"ATP is de energiemunt van de cel: bij afsplitsing van de derde fosfaatgroep komt energie vrij die transport, contractie en biosynthese aandrijft.","definition":"<p><strong>ATP</strong> (adenosinetrifosfaat) bestaat uit adenine, ribose en drie fosfaatgroepen. Hydrolyse van de eindstandige fosfaatbinding (ATP → ADP + P<sub>i</sub>) levert ongeveer 30 kJ/mol — genoeg om ongunstige reacties te koppelen aan een gunstige: spiercontractie, de Na⁺/K⁺-ATPase, en de opbouw van eiwitten, vetten en DNA.</p><p>Het meeste ATP komt uit de <em>oxidatieve fosforylering</em> in het mitochondrion: de elektronentransportketen pompt protonen naar de intermembraanruimte, en ATP-synthase laat die protonengradiënt terugstromen en maakt daarmee ATP (chemiosmose). Glycolyse en de citroenzuurcyclus leveren daarnaast rechtstreeks een kleine hoeveelheid.</p><p>De cel slaat ATP nauwelijks op — de voorraad gaat in seconden — dus productie en verbruik zijn strak gekoppeld: veel ADP versnelt de verbranding, overmaat ATP remt die af.</p>","image_url":"","wiki_titles":["Adenosine triphosphate","ATP synthase"],"option_only":true},"citraat (citroenzuur)":{"title":"Citraat","short":"Eerste product van de citroenzuurcyclus, gevormd uit acetyl-CoA en oxaalacetaat.","definition":"<p><b>Citraat</b> (citroenzuur) ontstaat wanneer acetyl-CoA in de citroenzuurcyclus aan oxaalacetaat wordt gekoppeld.</p><p>Het is de eerste stap van de cyclus; de naamgever citroenzuurcyclus verwijst ernaar.</p>","image_url":"","wiki_title":"Citric acid","match":"citraat (citroenzuur)","option_only":true},"mediastinum":{"title":"Mediastinum","short":"Ruimte tussen beide longen met o.a. hart, grote vaten en oesophagus; ingedeeld in superius, anterius, medium en posterius.","definition":"<p>Het <b>mediastinum</b> is het middencompartiment van de borstholte tussen de beide pleuraholten.</p>","image_url":"","wiki_title":"Mediastinum","match":"mediastinum","option_only":true},"area nuda":{"title":"Area nuda","short":"Het deel van het leveroppervlak zonder peritoneale bekleding, direct tegen het diafragma.","definition":"<p>Onbeklede (peritoneumvrije) zone aan de achterbovenzijde van de lever, waar deze direct aan het diafragma vastzit.</p>","image_url":"","wiki_title":"Bare area of the liver","match":"area nuda","option_only":true},"malonyl coa":{"title":"Malonyl-CoA","short":"Carboxyleringsproduct van acetyl-CoA dat als bouwsteen dient voor de vetzuursynthese en de vetzuuroxidatie remt.","definition":"<p><b>Malonyl-CoA</b> ontstaat door acetyl-CoA-carboxylase en levert de C2-eenheden voor de groeiende vetzuurketen.</p>","image_url":"","wiki_title":"Malonyl-CoA","match":"malonyl coa","option_only":true},"pleura visceralis":{"title":"Pleura visceralis en parietalis","short":"De pleura visceralis bekleedt de long, de pleura parietalis de borstwand; ertussen ligt de pleuraholte.","definition":"<p>De <strong>pleura visceralis</strong> ligt direct op het longoppervlak, de <strong>pleura parietalis</strong> tegen de thoraxwand en het diafragma. De overgang tussen beide ligt bij de longhilus. De dunne vochtlaag ertussen maakt wrijvingsloze ademhaling mogelijk.</p>","image_url":"","wiki_title":"Pulmonary pleurae","match":"pleura visceralis","option_only":true},"vesiculair ademgeruis":{"title":"Vesiculair ademgeruis","short":"Normaal, zacht ademgeruis dat over gezonde longen hoorbaar is.","definition":"<p><b>Vesiculair ademgeruis</b> is het fysiologische ademgeruis over de longvelden; afwijkingen ervan (bronchiaal, verzwakt) wijzen op pathologie.</p>","image_url":"","wiki_title":"Respiratory sounds","match":"vesiculair ademgeruis","option_only":true},"dyssynergie":{"title":"Bekkenbodemdyssynergie","short":"Gestoorde ontspanning of paradoxale aanspanning van de bekkenbodem tijdens defecatie.","definition":"<p>Bij <b>dyssynergie</b> van de bekkenbodem ontspant de bekkenbodem niet of trekt juist samen bij persen, wat langdurig en moeizaam toiletbezoek veroorzaakt.</p>","image_url":"","wiki_title":"","match":"dyssynergie","option_only":true},"omentum minus":{"title":"Omentum minus","short":"Dubbele peritoneumplooi tussen de kleine curvatuur van de maag/duodenum en de lever.","definition":"<p>Het <b>omentum minus</b> (kleine net) is een peritoneale plooi die van de leverhilus naar de kleine curvatuur van de maag en het begin van het duodenum loopt. Het bevat onder andere de a. hepatica, v. portae en ductus choledochus in de vrije rand.</p>","image_url":"","wiki_title":"Lesser omentum","match":"omentum minus","option_only":true},"pseudocroup (laryngitis subglottica)":{"title":"Pseudocroup","short":"Virale ontsteking van het strottenhoofd onder de stembanden bij jonge kinderen, met blafhoest.","definition":"<p><b>Pseudocroup</b> wordt meestal veroorzaakt door het para-influenzavirus en treedt vooral 's nachts op bij kinderen van 6 maanden tot 6 jaar. Bij een ernstige vorm worden dexamethason en soms vernevelde adrenaline gegeven.</p>","image_url":"","wiki_title":"Croup","match":"pseudocroup (laryngitis subglottica)","option_only":true},"mmc (migrating myoelectrical complex)-contracties":{"title":"Migrating myoelectrical complex (MMC)","short":"Golf van contracties tussen maaltijden die onverteerd materiaal uit maag en dunne darm veegt.","definition":"<p>Het <b>MMC</b> is de 'housekeeper' van het maag-darmkanaal: cyclische motoractiviteit tijdens vasten die restanten en bacteriën aboraal voortstuwt. Wordt onderbroken zodra er weer voedsel binnenkomt.</p>","image_url":"","wiki_title":"Migrating motor complex","match":"mmc (migrating myoelectrical complex)-contracties","option_only":true},"truncus coeliacus":{"title":"Truncus coeliacus","short":"Eerste onparige tak van de buikaorta die de lever, maag, milt en het bovenste deel van het duodenum van bloed voorziet.","definition":"<p>De <b>truncus coeliacus</b> ontspringt net onder het diafragma uit de aorta abdominalis en splitst zich in de a. gastrica sinistra, a. splenica en a. hepatica communis.</p>","image_url":"","wiki_title":"Celiac artery","match":"truncus coeliacus","option_only":true},"lig. falciforme":{"title":"Ligamentum falciforme","short":"Sikkelvormige buikvliesplooi die de lever aan de voorste buikwand en het middenrif verbindt.","definition":"<p>Het <b>lig. falciforme</b> is een rest van het ventrale mesenterium; in de vrije onderrand loopt het lig. teres hepatis (obliteratie van de v. umbilicalis).</p>","image_url":"","wiki_title":"Falciform ligament","match":"lig. falciforme","option_only":true},"omentum majus":{"title":"Omentum majus","short":"Grote vetschort die vanaf de grote curvatuur van de maag over de darmen hangt.","definition":"<p>Het <b>omentum majus</b> ontwikkelt uit het dorsale mesogastrium en heeft een afdekkende, immunologische functie in de buikholte.</p>","image_url":"","wiki_title":"Greater omentum","match":"omentum majus","option_only":true},"ductus cysticus":{"title":"Ductus cysticus","short":"De galbuis die de galblaas verbindt met de ductus hepaticus communis.","definition":"<p>De buis die de <b>galblaas</b> verbindt met de ductus hepaticus communis; samen vormen zij de ductus choledochus.</p>","image_url":"","wiki_title":"Cystic duct","match":"ductus cysticus","option_only":true},"papilla duodeni major (vater)":{"title":"Papilla duodeni major (van Vater)","short":"Het slijmvliesheuveltje in het dalende deel van het duodenum waar de ductus choledochus en de ductus pancreaticus uitmonden.","definition":"<p>Bij de <b>papilla duodeni major</b> ligt de sfincter van Oddi. Via deze papil wordt bij een ERCP de galweg in beeld gebracht en behandeld. De papilla duodeni minor (iets hoger) is de uitmonding van de ductus pancreaticus accessorius.</p>","image_url":"","wiki_title":"Major duodenal papilla","match":"papilla duodeni major (vater)","option_only":true},"ductus hepaticus communis":{"title":"Ductus hepaticus communis","short":"De gemeenschappelijke leverbuis die de gal uit beide leverkwabben verzamelt.","definition":"<p>Gevormd door samenvloeiing van de rechter en linker ductus hepaticus; sluit zich aan met de ductus cysticus tot de ductus choledochus.</p>","image_url":"","wiki_title":"Common hepatic duct","match":"ductus hepaticus communis","option_only":true},"bloedgasanalyse":{"title":"Bloedgasanalyse","short":"Meting van pH, PCO2, PO2 en base-excess in arterieel bloed om gaswisseling en zuur-base te beoordelen.","definition":"<p>De arteriële bloedgasanalyse toont de oxygenatie, ventilatie (PCO2) en de zuur-basebalans (pH, base-excess).</p>","image_url":"","wiki_title":"Arterial_blood_gas_test","match":"bloedgasanalyse","option_only":true},"migrating myoelectrical complex (mmc) contracties":{"title":"Migrating motor complex (MMC)","short":"Cyclisch motoriekpatroon in maag en dunne darm tijdens vasten dat resten wegveegt.","definition":"<p>Het <b>migrating motor complex</b> is de 'huishoudgolf' van de darm in nuchtere toestand, gestuurd door motiline, die onverteerde resten en bacteriën aboraal verplaatst.</p>","image_url":"","wiki_title":"Migrating motor complex","match":"migrating myoelectrical complex (mmc) contracties","option_only":true},"kubisch epitheel":{"title":"Kubisch epitheel","short":"Kubisch epitheel bestaat uit kubusvormige cellen en bekleedt onder meer de terminale bronchioli en klierbuizen.","definition":"<p><strong>Kubisch epitheel</strong> heeft cellen die ongeveer even hoog als breed zijn. Het komt voor in klieren, nierbuisjes en de kleinste luchtwegen (bronchioli), in tegenstelling tot het plaveiselepitheel van de alveoli.</p>","image_url":"","wiki_title":"Simple cuboidal epithelium","match":"kubisch epitheel","option_only":true},"appendices omentales (epiploicae)":{"title":"Appendices omentales","short":"Kleine vetophangsels aan de buitenzijde van het colon.","definition":"<p><b>Appendices omentales</b> (epiploicae) zijn met vet gevulde peritoneale uitstulpingen langs het colon, een van de morfologische kenmerken van de dikke darm.</p>","image_url":"","wiki_title":"Epiploic appendix","match":"appendices omentales (epiploicae)","option_only":true},"plicae circulares":{"title":"plicae circulares","short":"Circulaire plooien van de mucosa en submucosa van de dunne darm (met name jejunum) die het absorptieoppervlak vergroten.","definition":"<p><b>Plicae circulares</b> (plooien van Kerckring) zijn permanente circulaire plooien in de dunne darm. Ze zijn het talrijkst en hoogst in het jejunum en vergroten samen met villi en microvilli het resorptieoppervlak.</p>","image_url":"","wiki_title":"Circular folds","match":"plicae circulares","option_only":true},"lactose intolerantie":{"title":"Lactose-intolerantie","short":"Bij lactose-intolerantie is er te weinig lactase in de dunne darm, waardoor melksuiker in de dikke darm wordt gefermenteerd.","definition":"<p>Bij <strong>lactose-intolerantie</strong> geeft melk een opgeblazen gevoel, winderigheid, buikkrampen en osmotische diarree. De primaire vorm (afnemende lactase na de kindertijd) komt wereldwijd bij de meerderheid van de volwassenen voor; secundaire vormen ontstaan bij darmschade (bijv. coeliakie, gastro-enteritis). Diagnose met een waterstofademtest of eliminatie.</p>","image_url":"","wiki_title":"Lactose intolerance","match":"lactose intolerantie","option_only":true},"incretines (zoals gip en glp-1)":{"title":"Incretines","short":"Incretines (zoals GIP en GLP-1) zijn darmhormonen die na een maaltijd de insulinesecretie versterken.","definition":"<p><strong>Incretines</strong> worden door de darm afgegeven bij voedselopname en stimuleren de bètacellen tot insulineafgifte, nog voordat de bloedglucose sterk stijgt. GIP (glucose-dependent insulinotrophic peptide) is er één van.</p>","image_url":"","wiki_title":"Incretin","match":"incretines (zoals gip en glp-1)","option_only":true},"zoutzuur (hcl)":{"title":"Zoutzuur (maagzuur)","short":"Zoutzuur wordt door de pariëtale cellen van de maag uitgescheiden; het maakt de maaginhoud zuur, doodt micro-organismen en activeert pepsine.","definition":"<p>De pariëtale cellen pompen H⁺ via de H⁺/K⁺-ATPase het maaglumen in; chloride volgt. Stimulatoren zijn gastrine, histamine (H2) en acetylcholine (vagus); somatostatine remt. Het lage pH (1–2) helpt bij eiwitvertering en ijzeropname en beschermt tegen infecties. Protonpompremmers en H2-antagonisten verminderen de productie.</p>","image_url":"","wiki_title":"Gastric acid","match":"zoutzuur (hcl)","option_only":true},"lactase":{"title":"Lactase","short":"Enzym van de dunnedarmborstelzoom dat lactose splitst in glucose en galactose.","definition":"<p><b>Lactase</b> hydrolyseert het disacharide lactose tot de monosachariden D-glucose en D-galactose. Een verlaagde activiteit veroorzaakt lactose-intolerantie.</p>","image_url":"","wiki_title":"Lactase","match":"lactase","option_only":true},"saturatie":{"title":"Zuurstofsaturatie","short":"Percentage hemoglobine dat met zuurstof is verzadigd; maat voor de oxygenatie.","definition":"<p>De (perifere) zuurstofsaturatie (SpO2) geeft aan welk deel van het hemoglobine met O2 is verzadigd. Bij CO-vergiftiging kan de SpO2 vals-normaal zijn.</p>","image_url":"","wiki_title":"Oxygen saturation (medicine)","match":"saturatie","option_only":true},"arcus aortae":{"title":"Arcus aortae","short":"De aortaboog in het mediastinum superius waaruit de grote halsslagaders en de a. subclavia ontspringen.","definition":"<p>De <b>arcus aortae</b> verbindt de aorta ascendens met de aorta descendens en geeft de truncus brachiocephalicus, a. carotis communis sinistra en a. subclavia sinistra af.</p>","image_url":"","wiki_title":"Aortic arch","match":"arcus aortae","option_only":true},"vetzuuroxidatie":{"title":"Vetzuren","short":"Vetzuren zijn koolstofketens met een carboxylgroep; ze worden via bèta-oxidatie in de mitochondriën verbrand en leveren veel ATP, maar alleen aeroob.","definition":"<p><strong>Vetzuren</strong> zijn lange koolwaterstofketens met een carboxylgroep, verzadigd of onverzadigd. Ze worden opgeslagen als triglyceriden in vetweefsel en bij behoefte door lipolyse vrijgemaakt.</p><p>In de cel worden ze met carnitine de mitochondriën in getransporteerd en via <em>bèta-oxidatie</em> afgebroken tot acetyl-CoA, dat de citroenzuurcyclus in gaat. Vetzuren leveren per gram veel meer energie dan glucose, maar alleen via zuurstofafhankelijke stofwisseling en relatief langzaam. In de lever kunnen ze ketonlichamen vormen.</p>","image_url":"","wiki_title":"Fatty acid","match":"vetzuuroxidatie","option_only":true},"oropharynx":{"title":"Nasofarynx (neuskeelholte)","short":"De farynx bestaat uit nasofarynx, orofarynx en hypofarynx (laryngofarynx).","definition":"<p>In de <strong>nasofarynx</strong> liggen de neusamandel en de opening van de buis van Eustachius. De orofarynx bevat de keelamandelen en de tongbasis; de hypofarynx ligt achter het strottenhoofd. Het nasofarynxcarcinoom is geassocieerd met EBV.</p>","image_url":"","wiki_title":"Pharynx","match":"oropharynx","option_only":true},"hepatocyt":{"title":"Hepatocyten","short":"Hepatocyten zijn de levercellen die vrijwel alle metabole, synthetiserende en ontgiftende functies van de lever uitvoeren.","definition":"<p><strong>Hepatocyten</strong> vormen ±80% van het levervolume. Ze liggen in balkjes langs de sinusoïden en hebben veel mitochondriën, glad en ruw ER en Golgi.</p><p>Ze maken plasma-eiwitten (albumine, stollingsfactoren), gal, glucose (gluconeogenese) en ureum, slaan glycogeen, vet en vitamines op en ontgiften stoffen via het cytochroom P450-systeem. Tussen naburige hepatocyten liggen de galcanaliculi.</p>","image_url":"","wiki_title":"Hepatocyte","match":"hepatocyt","option_only":true},"urobiline":{"title":"Urobiline","short":"Geel afbraakproduct van bilirubine dat de urine kleurt.","definition":"<p><b>Urobiline</b> ontstaat uit urobilinogeen dat in de darm door bacteriën wordt gevormd en deels via de nier wordt uitgescheiden.</p>","image_url":"","wiki_title":"Urobilin","match":"urobiline","option_only":true},"kupffer-cel":{"title":"Kupffer-cel","short":"Levermacrofaag in de sinusoïden die bacteriën en celresten opruimt.","definition":"<p><b>Kupffer-cellen</b> zijn de vaste macrofagen van de lever. Ze liggen in de sinusoïden en fagocyteren micro-organismen en verouderde erytrocyten uit het poortaderbloed.</p>","image_url":"","wiki_title":"Kupffer cell","match":"kupffer-cel","option_only":true},"kupffercel":{"title":"Kupffer-cel","short":"Levermacrofaag in de sinusoïden die bacteriën en celresten opruimt.","definition":"<p><b>Kupffer-cellen</b> zijn de vaste macrofagen van de lever. Ze liggen in de sinusoïden en fagocyteren micro-organismen en verouderde erytrocyten uit het poortaderbloed.</p>","image_url":"","wiki_title":"Kupffer cell","match":"kupffercel","option_only":true},"refluxoesophagitis":{"title":"Gastro-oesofageale reflux","short":"Bij refluxklachten stroomt maaginhoud terug in de slokdarm, met zuurbranden en oprispingen.","definition":"<p><strong>Gastro-oesofageale refluxziekte</strong> ontstaat bij een tekortschietende onderste slokdarmsfincter, een hiatus hernia of verhoogde druk in de buik (overgewicht, zwangerschap). Klachten zijn zuurbranden achter het borstbeen en zure oprispingen, soms hoesten of heesheid. Complicaties: oesofagitis, stenose en Barrett-slokdarm. Behandeling met leefstijladviezen en protonpompremmers.</p>","image_url":"","wiki_title":"Gastroesophageal reflux disease","match":"refluxoesophagitis","option_only":true},"bilirubine":{"title":"Bilirubine","short":"Geel afbraakproduct van heem dat via de gal wordt uitgescheiden.","definition":"<p><b>Bilirubine</b> ontstaat bij afbraak van erytrocyten. Een galwegafsluiting geeft verhoogd (geconjugeerd) bilirubine in het bloed, donkere urine en lichte ontlasting.</p>","image_url":"","wiki_title":"Bilirubin","match":"bilirubine","option_only":true},"vena portae":{"title":"Vena portae","short":"De poortader die het veneuze, voedingrijke bloed van de darmen, milt en pancreas naar de lever transporteert.","definition":"<p>De <strong>vena portae</strong> (poortader) verzamelt het veneuze bloed van de tractus digestivus, milt en pancreas (o.a. via de v. mesenterica superior en v. lienalis) en voert het naar de lever, waar het door de sinusoïden stroomt vóór het via de venae hepaticae naar de v. cava inferior gaat.</p>","image_url":"","wiki_title":"Portal vein","match":"vena portae","option_only":true},"achalasie":{"title":"Achalasie","short":"Achalasie is een slokdarmmotiliteitsstoornis waarbij de onderste slokdarmsfincter niet goed ontspant, met passageklachten tot gevolg.","definition":"<p><strong>Achalasie</strong> ontstaat door verlies van remmende neuronen in de slokdarmwand: de onderste sfincter (LES) blijft te strak en peristaltiek ontbreekt. Gevolg: dysfagie en voedselstase.</p>","image_url":"","wiki_title":"Esophageal achalasia","match":"achalasie","option_only":true},"ct-abdomen, met oraal contrast":{"title":"CT abdomen","short":"Een CT abdomen is een röntgenscan in dwarsdoorsneden van de buik, vaak met contrast; goed voor acute buik, tumoren, abcessen en trauma.","definition":"<p>Bij een <strong>CT abdomen</strong> worden met röntgenstraling dunne dwarsdoorsneden van de buik gemaakt, meestal met intraveneus (en soms oraal) contrast.</p><p>Het geeft een overzichtelijk beeld van alle buikorganen, de darm en het retroperitoneum en wordt gebruikt bij een acute buik (bijv. perforatie, diverticulitis, appendicitis bij volwassenen), bij het stadiëren van tumoren, het opsporen van abcessen en bij trauma. Nadelen zijn de stralingsbelasting en het contrastmiddel (nierfunctie, allergie).</p>","image_url":"","wiki_title":"CT scan","match":"ct-abdomen, met oraal contrast","option_only":true},"galzouten":{"title":"Galzouten","short":"Uit cholesterol gevormde stoffen die vetten emulgeren voor de vertering en opname.","definition":"<p><b>Galzouten</b> worden door de lever aangemaakt, in de gal uitgescheiden en grotendeels in het ileum heropgenomen (enterohepatische kringloop).</p>","image_url":"","wiki_title":"Bile acid","match":"galzouten","option_only":true},"prikkelbare darmsyndroom":{"title":"Prikkelbare darm syndroom","short":"Functionele darmstoornis met buikpijn en wisselend ontlastingspatroon zonder aantoonbare afwijkingen.","definition":"<p>Het <b>prikkelbare darm syndroom</b> (PDS/IBS) is een diagnose per uitsluiting: buikpijn en veranderd defecatiepatroon zonder alarmsymptomen of afwijkend onderzoek.</p>","image_url":"","wiki_title":"Irritable bowel syndrome","match":"prikkelbare darmsyndroom","option_only":true},"leptine":{"title":"Leptine","short":"Verzadigingshormoon uit vetweefsel dat de eetlust remt.","definition":"<p><b>Leptine</b> wordt door adipocyten afgegeven in verhouding tot de vetmassa en onderdrukt via de hypothalamus het hongergevoel.</p>","image_url":"","wiki_title":"Leptin","match":"leptine","option_only":true},"schatzi ring":{"title":"Schatzki-ring","short":"Een Schatzki-ring is een dunne, ringvormige vernauwing van het slijmvlies onderin de slokdarm, vlak boven de overgang naar de maag.","definition":"<p>Een <strong>Schatzki-ring</strong> geeft periodiek slikklachten voor vast voedsel, soms met een vastzittende voedselbrok (‘steakhouse syndrome’). Op een slikfoto is een smalle ring te zien. Behandeling met endoscopische dilatatie.</p>","image_url":"","wiki_title":"Schatzki ring","match":"schatzi ring|schatzki-ring|schatzki ring","option_only":true},"m. constrictor pharyngeus":{"title":"Mm. constrictores pharyngis","short":"De mm. constrictores pharyngis (superior, medius en inferior) vormen de spierwand van de keel en duwen tijdens het slikken de voedselbrok naar beneden.","definition":"<p>De constrictoren worden geïnnerveerd door de n. vagus via de plexus pharyngeus. Tussen het onderste deel van de m. constrictor inferior en de m. cricopharyngeus ligt een zwakke plek (driehoek van Killian), waar een Zenker-divertikel kan ontstaan.</p>","image_url":"","wiki_title":"Pharyngeal constrictor muscles","match":"m. constrictor pharyngeus|constrictores pharyngis","option_only":true},"palatum molle":{"title":"Palatum molle (zachte gehemelte)","short":"Het palatum molle is het beweeglijke achterste deel van het gehemelte, dat tijdens slikken en spreken de neuskeelholte afsluit.","definition":"<p>Het <strong>zachte gehemelte</strong> eindigt in de huig (uvula). Bij uitval van de n. vagus aan één kant trekt de huig naar de gezonde kant. Een slecht sluitend gehemelte (bijv. bij een schisis) geeft een nasale spraak en terugvloed van voedsel naar de neus.</p>","image_url":"","wiki_title":"Soft palate","match":"palatum molle|zachte gehemelte|velum","option_only":true},"cisterna chyli":{"title":"Cisterna chyli","short":"De cisterna chyli is een verwijde lymfezak achter de aorta ter hoogte van L1–L2, waaruit de ductus thoracicus ontspringt.","definition":"<p>In de <strong>cisterna chyli</strong> komt lymfe uit de benen en de darmen samen; de darmlymfe (chylus) is melkachtig door vetten in chylomicronen. Beschadiging van de ductus thoracicus kan een chylothorax geven.</p>","image_url":"","wiki_title":"Cisterna chyli","match":"cisterna chyli","option_only":true},"linea pectinata":{"title":"Linea pectinata (linea dentata)","short":"De linea pectinata is de getande grens in het anaalkanaal tussen het deel dat uit de einddarm en het deel dat uit de huid is ontstaan.","definition":"<p>Boven de <strong>linea pectinata</strong> is het slijmvlies cilinderepitheel, met autonome innervatie (pijnloos) en afvoer naar de v. portae; eronder plaveiselepitheel met somatische innervatie (gevoelig) en afvoer naar de systemische circulatie. Daarom zijn inwendige aambeien pijnloos en uitwendige pijnlijk. De linea anocutanea is de overgang naar de gewone huid.</p>","image_url":"","wiki_title":"Pectinate line","match":"linea pectinata|linea dentata|linea anocutanea","option_only":true},"terminale bronchiolus":{"title":"Terminale bronchiolus","short":"De terminale bronchiolus is de laatste vertakking van het geleidende deel van de luchtwegen, zonder alveoli in de wand.","definition":"<p>Na de <strong>terminale bronchiolus</strong> volgen de respiratoire bronchioli, alveolaire gangen en alveoli, waar gaswisseling plaatsvindt. Bronchioli hebben geen kraakbeen, maar wel gladde spieren.</p>","image_url":"","wiki_title":"Bronchiole","match":"terminale bronchiolus|bronchiolus terminalis","option_only":true},"clara-cel":{"title":"Clubcel (Clara-cel)","short":"Clubcellen (vroeger Clara-cellen) zijn niet-trilhaardragende cellen in de bronchioli die beschermende eiwitten uitscheiden en als stamcel kunnen dienen.","definition":"<p><strong>Clubcellen</strong> maken o.a. surfactantachtige eiwitten en ontgiften stoffen via cytochroom P450. Ze kunnen delen om beschadigd epitheel van de bronchioli te herstellen.</p>","image_url":"","wiki_title":"Club cell","match":"clara-cel|clubcel|club cell","option_only":true},"trilhaarepitheelcel":{"title":"Trilhaarepitheel","short":"Trilhaarepitheelcellen hebben trilharen die slijm met daarin gevangen deeltjes richting keel bewegen (mucociliaire klaring).","definition":"<p>Het luchtwegepitheel is meerrijig cilindrisch <strong>trilhaarepitheel</strong> met slijmbekercellen. Roken beschadigt de trilharen. Bij primaire ciliaire dyskinesie werken de trilharen niet goed, met recidiverende luchtweginfecties.</p>","image_url":"","wiki_title":"Respiratory epithelium","match":"trilhaarepitheelcel|trilhaarepitheel|ciliën","option_only":true},"pneumocyt ii":{"title":"Pneumocyten type I en II","short":"Type I-pneumocyten zijn platte cellen voor de gaswisseling; type II-pneumocyten maken surfactant en kunnen delen om het alveolaire epitheel te herstellen.","definition":"<p><strong>Type I-pneumocyten</strong> bedekken ongeveer 95% van het alveolaire oppervlak. <strong>Type II-pneumocyten</strong> zijn kubisch en bevatten lamellaire lichaampjes met surfactant. Bij prematuren is de surfactantproductie nog onvoldoende (IRDS).</p>","image_url":"","wiki_title":"Pulmonary alveolus","match":"pneumocyt ii|type ii pneumocyt|pneumocyt type i|type i pneumocyt","option_only":true},"borstelcel":{"title":"Borstelcel (tuft cell)","short":"Borstelcellen zijn zeldzame cellen met korte microvilli in het epitheel van luchtwegen en darm, met een sensorische functie.","definition":"<p><strong>Borstelcellen</strong> reageren o.a. op parasieten en kunnen een type 2-immuunreactie (IL-25) op gang brengen. Hun functie in de luchtwegen is nog niet volledig bekend.</p>","image_url":"","wiki_title":"Tuft cell","match":"borstelcel|tuft cell","option_only":true},"kleine korrelcel":{"title":"Kleine korrelcel (neuro-endocriene cel)","short":"Kleine korrelcellen (Kulchitsky-cellen) zijn neuro-endocriene cellen in het luchtwegepitheel, met hormoonhoudende korrels.","definition":"<p>Uit deze neuro-endocriene cellen kunnen carcinoïden en het kleincellig longcarcinoom ontstaan. Dat verklaart waarom die tumoren soms hormonen maken (paraneoplastische syndromen, zoals SIADH en ectopisch ACTH).</p>","image_url":"","wiki_title":"Neuroendocrine cell","match":"kleine korrelcel|kulchitsky-cel|neuro-endocriene cel","option_only":true},"basale cellen":{"title":"Basale cellen (luchtweg)","short":"Basale cellen liggen op de basaalmembraan van het luchtwegepitheel en zijn de stamcellen waaruit andere epitheelcellen ontstaan.","definition":"<p>Uit <strong>basale cellen</strong> kunnen trilhaarcellen en slijmbekercellen ontstaan. Bij chronische prikkeling (roken) kan het epitheel omzetten in plaveiselepitheel (squameuze metaplasie).</p>","image_url":"","wiki_title":"","match":"basale cellen|basale cel","option_only":true},"alveolaire macrofaag":{"title":"Alveolaire macrofaag","short":"Alveolaire macrofagen ruimen in de longblaasjes stofdeeltjes, micro-organismen en surfactantresten op.","definition":"<p><strong>Alveolaire macrofagen</strong> (stofcellen) zijn de eerste afweer in de alveoli. Bij hartfalen kunnen ze ijzerpigment uit rode bloedcellen bevatten (hartfaalcellen).</p>","image_url":"","wiki_title":"Alveolar macrophage","match":"alveolaire macrofaag|stofcel","option_only":true},"pharynx":{"title":"Farynx (keelholte)","short":"De farynx is de spierbuis achter neus- en mondholte die lucht naar het strottenhoofd en voedsel naar de slokdarm leidt.","definition":"<p>De <strong>farynx</strong> wordt verdeeld in nasofarynx, orofarynx en hypofarynx. In de wand liggen de lymfoïde organen van de ring van Waldeyer (keel-, neus- en tongamandelen).</p>","image_url":"","wiki_title":"Pharynx","match":"pharynx|farynx|keelholte","option_only":true},"peritoneum visceralis":{"title":"Peritoneum viscerale en parietale","short":"Het buikvlies bestaat uit het pariëtale blad, dat de buikwand bekleedt, en het viscerale blad, dat de organen bedekt.","definition":"<p>Het <strong>pariëtale peritoneum</strong> is somatisch geïnnerveerd en goed lokaliseerbaar pijngevoelig (loslaatpijn, défense bij peritonitis). Het <strong>viscerale peritoneum</strong> is autonoom geïnnerveerd en geeft vage, slecht lokaliseerbare pijn.</p>","image_url":"","wiki_title":"Peritoneum","match":"peritoneum visceralis|peritoneum viscerale|peritoneum parietale|buikvlies","option_only":true},"colon transversum":{"title":"Colon transversum","short":"Het colon transversum is het dwarslopende deel van de dikke darm tussen de flexura hepatica en de flexura lienalis.","definition":"<p>Het <strong>colon transversum</strong> hangt aan het mesocolon transversum en is daardoor beweeglijk. De eerste twee derde wordt verzorgd door de a. mesenterica superior (a. colica media), het laatste derde door de a. mesenterica inferior.</p>","image_url":"","wiki_title":"Transverse colon","match":"colon transversum|dwarse colon","option_only":true},"pylorus":{"title":"Pylorus (maagportier)","short":"De pylorus is de gespierde overgang van de maag naar het duodenum, die de lediging van de maag regelt.","definition":"<p>De <strong>pylorus</strong> laat de maaginhoud in kleine porties door. Bij zuigelingen kan de spier verdikken (hypertrofische pylorusstenose). Bij volwassenen kan een ulcus of tumor bij de pylorus een maaguitgangsstenose geven.</p>","image_url":"","wiki_title":"Pylorus","match":"pylorus|maagportier|pylorussfincter","option_only":true},"waterstofademtest":{"title":"Waterstofademtest","short":"Bij een waterstofademtest wordt na het drinken van een suiker gemeten of er waterstof in de uitademingslucht verschijnt, als teken van bacteriële vergisting.","definition":"<p>De <strong>waterstofademtest</strong> wordt gebruikt bij verdenking op lactose- of fructosemalabsorptie en bacteriële overgroei in de dunne darm.</p>","image_url":"","wiki_title":"Hydrogen breath test","match":"waterstofademtest|h2-ademtest","option_only":true},"aminopeptidases":{"title":"Peptidasen van de borstelzoom","short":"Aminopeptidasen in de borstelzoom van de dunne darm knippen aminozuren één voor één af van het uiteinde van peptiden.","definition":"<p>Eiwitvertering begint in de maag (pepsine), gaat verder in het duodenum met <strong>trypsine en chymotrypsine</strong> uit de pancreas en eindigt met peptidasen in de borstelzoom. Aminozuren en kleine peptiden worden daarna opgenomen.</p>","image_url":"","wiki_title":"","match":"aminopeptidases|aminopeptidase|dipeptidases","option_only":true},"chymotrypsine":{"title":"Chymotrypsine","short":"Chymotrypsine is een eiwitsplitsend enzym uit de pancreas, dat als inactief chymotrypsinogeen wordt afgegeven en door trypsine wordt geactiveerd.","definition":"<p>Trypsinogeen wordt in het duodenum door enterokinase omgezet in trypsine, dat vervolgens <strong>chymotrypsinogeen</strong> en andere pancreasenzymen activeert. Voortijdige activatie in de pancreas zelf speelt een rol bij pancreatitis.</p>","image_url":"","wiki_title":"Chymotrypsin","match":"chymotrypsine|chymotrypsinogeen","option_only":true},"disaccharidases":{"title":"Disaccharidasen","short":"Disaccharidasen in de borstelzoom van de dunne darm splitsen disachariden (lactose, sucrose, maltose) in monosachariden.","definition":"<p>Koolhydraten worden eerst door <strong>amylase</strong> (speeksel, pancreas) afgebroken tot di- en oligosachariden en daarna door disaccharidasen (lactase, sucrase-isomaltase, maltase) tot glucose, galactose en fructose, die opgenomen kunnen worden. Bij vlokatrofie (coeliakie) is de activiteit verminderd.</p>","image_url":"","wiki_title":"Disaccharidase","match":"disaccharidases|disaccharidasen|sucrase|maltase","option_only":true},"ductus hepaticus dexter":{"title":"Ductus hepaticus dexter en sinister","short":"De ductus hepaticus dexter en sinister voeren gal af uit de rechter en linker leverhelft en vormen samen de ductus hepaticus communis.","definition":"<p>De ductus hepaticus communis vormt samen met de ductus cysticus (van de galblaas) de ductus choledochus. Een tumor op de splitsing heet een Klatskin-tumor.</p>","image_url":"","wiki_title":"Common hepatic duct","match":"ductus hepaticus dexter|ductus hepaticus sinister","option_only":true},"proctodeum":{"title":"Proctodeum","short":"Het proctodeum is een instulping van het ectoderm bij het embryo waaruit het onderste deel van het anaalkanaal ontstaat.","definition":"<p>Het <strong>proctodeum</strong> komt samen met de einddarm (endoderm); de grens is later de linea pectinata. Als de anale membraan niet opengaat, ontstaat een anusatresie.</p>","image_url":"","wiki_title":"Proctodeum","match":"proctodeum|anale membraan","option_only":true},"flexura coli dextra":{"title":"Flexura coli dextra en sinistra","short":"De flexura coli dextra (hepatica) en sinistra (lienalis) zijn de bochten van het colon bij de lever en de milt.","definition":"<p>De <strong>flexura lienalis</strong> ligt op de grens van de stroomgebieden van de a. mesenterica superior en inferior (punt van Griffiths) en is daardoor gevoelig voor ischemie. Het ligt hoger dan de flexura hepatica.</p>","image_url":"","wiki_title":"Splenic flexure","match":"flexura coli dextra|flexura hepatica|flexura lienalis|flexura coli sinistra","option_only":true},"vena lienalis":{"title":"Vena lienalis (v. splenica)","short":"De v. lienalis voert bloed af uit de milt en loopt achter de pancreas naar de v. portae, waarin ze samenkomt met de v. mesenterica superior.","definition":"<p>Trombose van de <strong>v. lienalis</strong> (bijv. na pancreatitis) kan geïsoleerde maagvarices veroorzaken (linkszijdige portale hypertensie).</p>","image_url":"","wiki_title":"Splenic vein","match":"vena lienalis|v. lienalis|vena splenica","option_only":true},"vena gastrica sinistra":{"title":"V. gastrica sinistra (v. coronaria ventriculi)","short":"De v. gastrica sinistra voert bloed van de kleine curvatuur van de maag af naar de v. portae en staat in verbinding met slokdarmvenen.","definition":"<p>Bij portale hypertensie wordt de verbinding tussen de <strong>v. gastrica sinistra</strong> en de slokdarmvenen een belangrijke portocavale shunt, waardoor slokdarmvarices ontstaan.</p>","image_url":"","wiki_title":"Left gastric vein","match":"vena gastrica sinistra|v. gastrica sinistra|vena gastrica dextra","option_only":true},"aldolase b":{"title":"Aldolase B","short":"Aldolase B splitst in de lever fructose-1-fosfaat; een erfelijk tekort geeft erfelijke fructose-intolerantie.","definition":"<p>Bij een tekort aan <strong>aldolase B</strong> hoopt fructose-1-fosfaat zich op, wat fosfaat vastlegt en de glycogenolyse en gluconeogenese remt. Na het eten van fructose of sucrose ontstaan hypoglykemie, braken, leverschade en nierproblemen. Behandeling: fructose, sucrose en sorbitol vermijden.</p>","image_url":"","wiki_title":"Hereditary fructose intolerance","match":"aldolase b|erfelijke fructose-intolerantie","option_only":true},"udp-glucose epimerase":{"title":"UDP-galactose-4-epimerase","short":"Dit enzym zet UDP-galactose om in UDP-glucose en is een van de stappen in de afbraak van galactose.","definition":"<p>De galactoseafbraak verloopt via galactokinase, galactose-1-fosfaat-uridyltransferase (GALT) en de <strong>epimerase</strong>. Een tekort aan GALT geeft klassieke galactosemie bij pasgeborenen (braken, icterus, leverfalen, cataract en E. coli-sepsis); daar wordt in de hielprik op gescreend.</p>","image_url":"","wiki_title":"Galactosemia","match":"udp-glucose epimerase|udp-galactose-4-epimerase|galactosemie","option_only":true},"bacteroides spp":{"title":"Bacteroides","short":"Bacteroides zijn gramnegatieve, anaerobe staven en de belangrijkste bacteriën in de dikke darm.","definition":"<p><strong><em>Bacteroides fragilis</em></strong> is een belangrijke verwekker van intra-abdominale abcessen en peritonitis, vaak samen met aerobe darmbacteriën. Effectieve middelen zijn metronidazol, amoxicilline/clavulaanzuur en carbapenems.</p>","image_url":"","wiki_title":"Bacteroides","match":"bacteroides spp|bacteroides|bacteroides fragilis","option_only":true},"overloopdiarree":{"title":"Overloopdiarree","short":"Bij overloopdiarree lekt dunne ontlasting langs een harde ophoping van feces in het rectum (fecale impactie).","definition":"<p><strong>Overloopdiarree</strong> komt vooral voor bij ouderen, bedlegerigen en bij gebruik van opiaten. Bij rectaal toucher is een harde massa te voelen. Behandeling: het rectum leegmaken (klysma) en daarna laxeren.</p>","image_url":"","wiki_title":"Fecal impaction","match":"overloopdiarree|paradoxale diarree","option_only":true},"calprotectine":{"title":"Fecaal calprotectine","short":"Calprotectine is een eiwit uit neutrofielen; een verhoogde waarde in de ontlasting wijst op een ontsteking van de darm.","definition":"<p>Met <strong>fecaal calprotectine</strong> kan onderscheid worden gemaakt tussen een prikkelbaredarmsyndroom (normaal) en IBD (verhoogd). Het wordt ook gebruikt om de activiteit van IBD te volgen. Het is niet specifiek: ook infecties en NSAID's verhogen het.</p>","image_url":"","wiki_title":"Calprotectin","match":"calprotectine|fecaal calprotectine","option_only":true},"protonpompremmer":{"title":"Protonpompremmer (PPI)","short":"Protonpompremmers remmen de H⁺/K⁺-ATPase van de pariëtale cellen en zijn de krachtigste remmers van de maagzuurproductie.","definition":"<p><strong>PPI's</strong> worden gebruikt bij refluxziekte, ulcera, H. pylori-eradicatie, maagbescherming bij NSAID's en een bloedend ulcus (intraveneus). Langdurig gebruik hangt samen met hypomagnesiëmie, vitamine B12-tekort, fracturen en infecties (<em>C. difficile</em>).</p>","image_url":"","wiki_title":"Proton-pump inhibitor","match":"protonpompremmer|ppi|omeprazol|pantoprazol|esomeprazol","option_only":true},"x colon inloop":{"title":"Colon-inloopfoto","short":"Bij een colon-inloopfoto wordt het colon met contrast via de anus gevuld en op röntgenfoto's afgebeeld.","definition":"<p>Een <strong>colon-inloop</strong> is grotendeels vervangen door coloscopie en CT-colografie, maar wordt nog gebruikt om fistels, stricturen of naadlekkage in beeld te brengen (met wateroplosbaar contrast).</p>","image_url":"","wiki_title":"Lower gastrointestinal series","match":"x colon inloop|colon inloop|x-colon","option_only":true},"d-dimeer bepalen":{"title":"D-dimeer","short":"D-dimeer is een afbraakproduct van fibrine; een normale waarde maakt trombose of longembolie onwaarschijnlijk bij een laag klinisch risico.","definition":"<p><strong>D-dimeer</strong> is gevoelig maar niet specifiek: het is ook verhoogd na operaties, bij infecties, kanker, zwangerschap en ouderdom. Daarom wordt het alleen gebruikt in combinatie met een beslisregel (Wells, YEARS).</p>","image_url":"","wiki_title":"D-dimer","match":"d-dimeer bepalen|d-dimeer|d-dimeren","option_only":true},"α-amylase":{"title":"Amylase","short":"Amylase is een enzym uit speekselklieren en pancreas dat zetmeel afbreekt; een verhoogde bloedwaarde past o.a. bij pancreatitis.","definition":"<p><strong>Amylase</strong> splitst α-1,4-bindingen in zetmeel. Bij acute pancreatitis stijgt het, maar het is minder specifiek dan lipase (ook verhoogd bij o.a. parotitis, darmperforatie en nierfalen) en normaliseert sneller.</p>","image_url":"","wiki_title":"Amylase","match":"α-amylase","option_only":true},"clara cel":{"title":"Clubcel (Clara-cel)","short":"Clubcellen (vroeger Clara-cellen) zijn niet-trilhaardragende cellen in de bronchioli die beschermende eiwitten uitscheiden en als stamcel kunnen dienen.","definition":"<p><strong>Clubcellen</strong> maken o.a. surfactantachtige eiwitten en ontgiften stoffen via cytochroom P450. Ze kunnen delen om beschadigd epitheel van de bronchioli te herstellen.</p>","image_url":"","wiki_title":"Club cell","match":"clara cel","option_only":true},"borstel cellen":{"title":"Borstelcel (tuft cell)","short":"Borstelcellen zijn zeldzame cellen met korte microvilli in het epitheel van luchtwegen en darm, met een sensorische functie.","definition":"<p><strong>Borstelcellen</strong> reageren o.a. op parasieten en kunnen een type 2-immuunreactie (IL-25) op gang brengen. Hun functie in de luchtwegen is nog niet volledig bekend.</p>","image_url":"","wiki_title":"Tuft cell","match":"borstel cellen","option_only":true},"kleine korrelcellen":{"title":"Kleine korrelcel (neuro-endocriene cel)","short":"Kleine korrelcellen (Kulchitsky-cellen) zijn neuro-endocriene cellen in het luchtwegepitheel, met hormoonhoudende korrels.","definition":"<p>Uit deze neuro-endocriene cellen kunnen carcinoïden en het kleincellig longcarcinoom ontstaan. Dat verklaart waarom die tumoren soms hormonen maken (paraneoplastische syndromen, zoals SIADH en ectopisch ACTH).</p>","image_url":"","wiki_title":"Neuroendocrine cell","match":"kleine korrelcellen","option_only":true},"peritoneum parietalis":{"title":"Peritoneum viscerale en parietale","short":"Het buikvlies bestaat uit het pariëtale blad, dat de buikwand bekleedt, en het viscerale blad, dat de organen bedekt.","definition":"<p>Het <strong>pariëtale peritoneum</strong> is somatisch geïnnerveerd en goed lokaliseerbaar pijngevoelig (loslaatpijn, défense bij peritonitis). Het <strong>viscerale peritoneum</strong> is autonoom geïnnerveerd en geeft vage, slecht lokaliseerbare pijn.</p>","image_url":"","wiki_title":"Peritoneum","match":"peritoneum parietalis","option_only":true},"ductus hepaticus sinister":{"title":"Ductus hepaticus dexter en sinister","short":"De ductus hepaticus dexter en sinister voeren gal af uit de rechter en linker leverhelft en vormen samen de ductus hepaticus communis.","definition":"<p>De ductus hepaticus communis vormt samen met de ductus cysticus (van de galblaas) de ductus choledochus. Een tumor op de splitsing heet een Klatskin-tumor.</p>","image_url":"","wiki_title":"Common hepatic duct","match":"ductus hepaticus sinister","option_only":true},"flexura coli sinistra (lienalis)":{"title":"Flexura coli dextra en sinistra","short":"De flexura coli dextra (hepatica) en sinistra (lienalis) zijn de bochten van het colon bij de lever en de milt.","definition":"<p>De <strong>flexura lienalis</strong> ligt op de grens van de stroomgebieden van de a. mesenterica superior en inferior (punt van Griffiths) en is daardoor gevoelig voor ischemie. Het ligt hoger dan de flexura hepatica.</p>","image_url":"","wiki_title":"Splenic flexure","match":"flexura coli sinistra (lienalis)","option_only":true},"vena gastrica dextra":{"title":"V. gastrica sinistra (v. coronaria ventriculi)","short":"De v. gastrica sinistra voert bloed van de kleine curvatuur van de maag af naar de v. portae en staat in verbinding met slokdarmvenen.","definition":"<p>Bij portale hypertensie wordt de verbinding tussen de <strong>v. gastrica sinistra</strong> en de slokdarmvenen een belangrijke portocavale shunt, waardoor slokdarmvarices ontstaan.</p>","image_url":"","wiki_title":"Left gastric vein","match":"vena gastrica dextra","option_only":true},"disacchariden":{"title":"Disaccharidasen","short":"Disaccharidasen in de borstelzoom van de dunne darm splitsen disachariden (lactose, sucrose, maltose) in monosachariden.","definition":"<p>Koolhydraten worden eerst door <strong>amylase</strong> (speeksel, pancreas) afgebroken tot di- en oligosachariden en daarna door disaccharidasen (lactase, sucrase-isomaltase, maltase) tot glucose, galactose en fructose, die opgenomen kunnen worden. Bij vlokatrofie (coeliakie) is de activiteit verminderd.</p>","image_url":"","wiki_title":"Disaccharidase","match":"disacchariden","option_only":true},"polysacchariden":{"title":"Disaccharidasen","short":"Disaccharidasen in de borstelzoom van de dunne darm splitsen disachariden (lactose, sucrose, maltose) in monosachariden.","definition":"<p>Koolhydraten worden eerst door <strong>amylase</strong> (speeksel, pancreas) afgebroken tot di- en oligosachariden en daarna door disaccharidasen (lactase, sucrase-isomaltase, maltase) tot glucose, galactose en fructose, die opgenomen kunnen worden. Bij vlokatrofie (coeliakie) is de activiteit verminderd.</p>","image_url":"","wiki_title":"Disaccharidase","match":"polysacchariden","option_only":true},"oesophagus mesoderm":{"title":"Kiembladen","short":"Bij de gastrulatie ontstaan drie kiembladen: ectoderm, mesoderm en endoderm, waaruit alle weefsels ontstaan.","definition":"<p>Uit het <strong>ectoderm</strong> ontstaan o.a. de opperhuid en het zenuwstelsel; uit het <strong>endoderm</strong> het epitheel van darm, luchtwegen, lever en pancreas. Het <strong>mesoderm</strong> wordt verdeeld in axiaal (chorda), paraxiaal (somieten: spieren, wervels, dermis), intermediair (nieren en geslachtsorganen) en zijplaatmesoderm (lichaamswand, hart en bloedvaten, wand van de darm).</p>","image_url":"","wiki_title":"Germ layer","match":"oesophagus mesoderm","option_only":true},"geconjugeerd hyperbilirubinemie":{"title":"Geconjugeerd bilirubine","short":"Geconjugeerd bilirubine is het in de lever aan glucuronzuur gekoppelde, in water oplosbare bilirubine dat via de gal wordt uitgescheiden.","definition":"<p>Een verhoogd <strong>geconjugeerd bilirubine</strong> past bij leverziekte of galwegobstructie. Omdat het in water oplosbaar is, komt het in de urine (donkere urine). Bij pasgeborenen is een verhoogd geconjugeerd bilirubine altijd afwijkend en vraagt het om onderzoek naar bijv. galgangatresie.</p>","image_url":"","wiki_title":"Bilirubin","match":"geconjugeerd hyperbilirubinemie","option_only":true},"stafylokok":{"title":"Staphylococcus aureus","short":"S. aureus is een grampositieve kok in trosjes, coagulasepositief, die huid- en wondinfecties, abcessen en ernstige systemische infecties veroorzaakt.","definition":"<p><strong><em>Staphylococcus aureus</em></strong> is een grampositieve kok die in trosjes groeit en <em>coagulase-positief</em> is (onderscheid met andere stafylokokken). Ongeveer een derde van de mensen draagt hem in de neus.</p><p>Hij veroorzaakt huid- en wekedeleninfecties (impetigo, furunkels, abcessen, wondinfecties), maar ook osteomyelitis, septische artritis, endocarditis en sepsis. Via toxines kan hij voedselvergiftiging en het toxischeshocksyndroom veroorzaken. MRSA is een methicillineresistente variant.</p>","image_url":"","wiki_title":"Staphylococcus aureus","match":"stafylokok","option_only":true},"acute hepatitis c":{"title":"Hepatitis C","short":"Hepatitis C is een via bloed overgedragen RNA-virus dat vaak chronisch wordt en tot cirrose en levercelkanker kan leiden.","definition":"<p>Het <strong>hepatitis C-virus</strong> (flavivirus) wordt vooral via bloed overgedragen (drugsgebruik met naalden, vroeger transfusies). Een acute infectie verloopt meestal zonder klachten, maar wordt in de meerderheid chronisch. Na jaren kunnen fibrose, cirrose en hepatocellulair carcinoom ontstaan. Er is geen vaccin, maar direct werkende antivirale middelen genezen de infectie in vrijwel alle gevallen.</p>","image_url":"","wiki_title":"Hepatitis C","match":"acute hepatitis c","option_only":true},"hepatitis a infectie":{"title":"Hepatitis A","short":"Hepatitis A is een fecaal-oraal overgedragen virale leverontsteking die acuut verloopt en nooit chronisch wordt.","definition":"<p><strong>Hepatitis A</strong> wordt veroorzaakt door het hepatitis A-virus, een niet-omhuld RNA-virus dat fecaal-oraal wordt overgedragen (besmet water en voedsel, reizen).</p><p>Het geeft een acute hepatitis met moeheid, misselijkheid, geelzucht en verhoogde transaminasen; bij jonge kinderen vaak zonder klachten. Hepatitis A wordt <em>niet chronisch</em> en geeft levenslange immuniteit. Er is een vaccin.</p>","image_url":"","wiki_title":"Hepatitis A","match":"hepatitis a infectie","option_only":true},"irritable bowel syndrome":{"title":"Prikkelbare darm syndroom","short":"Functionele darmstoornis met buikpijn en wisselend ontlastingspatroon zonder aantoonbare afwijkingen.","definition":"<p>Het <b>prikkelbare darm syndroom</b> (PDS/IBS) is een diagnose per uitsluiting: buikpijn en veranderd defecatiepatroon zonder alarmsymptomen of afwijkend onderzoek.</p>","image_url":"","wiki_title":"Irritable bowel syndrome","match":"irritable bowel syndrome","option_only":true},"colorectaal carcinoom":{"title":"Colorectaal carcinoom","short":"Het colorectaal carcinoom is een adenocarcinoom van de dikke darm, meestal ontstaan uit een adenoom.","definition":"<p>Een tumor <strong>links</strong> geeft vaak een veranderd ontlastingspatroon en bloed bij de ontlasting; een tumor <strong>rechts</strong> vaker een ijzergebreksanemie. Risicofactoren: leeftijd, familie, IBD, Lynch-syndroom en FAP. In Nederland is er een bevolkingsonderzoek met een FIT-test.</p>","image_url":"","wiki_title":"Colorectal cancer","match":"colorectaal carcinoom|darmkanker|coloncarcinoom|rectumcarcinoom","option_only":true}};
